```javascript
import { parse } from 'ts-node';
import { esprima } from 'esprima';
import { estreeToCode } from 'estree-to-code';
import { exec } from 'child_process';

/**
 * Parses TypeScript source code and transforms it into ESTree compatible form using escodegen.
 *
 * @param {string} tsSource The TypeScript source code to parse.
 * @returns {string} The ESTree-compatible JavaScript code.
 * @throws {Error} If the TypeScript parsing or conversion fails.
 */
async function typescriptToEstree(tsSource) {
  try {
    // 1. Parse TypeScript to Abstract Syntax Tree (AST) using ts-node
    const tsAst = parse(tsSource);

    // 2. Convert TypeScript AST to JavaScript AST using esprima
    const jsAst = esprima.parse(tsSource);

    // 3. Convert JavaScript AST to ESTree format using estree-to-code
    const estreeCode = estreeToCode(jsAst);

    // 4. Use escodegen to generate JavaScript code from ESTree
    const escodegenCode = exec(`escodegen -f -@ ${estreeCode}`, (error, stdout, stderr) => {
      if (error) {
        console.error(`exec error: ${error}`);
        throw error;
      }
      if (stderr) {
        console.error(`exec stderr: ${stderr}`);
        throw new Error(stderr);
      }
      return stdout;
    });

    return escodegenCode;

  } catch (error) {
    console.error("Error during TypeScript to ESTree conversion:", error);
    throw error;
  }
}

export default typescriptToEstree;
```

```javascript
import * as esprima from 'esprima';
import * as estree from 'estree';

/**
 * Creates a TypeScript-ESTree AST parser.
 *
 * @returns {function} A function that parses TypeScript code and returns an ESTree AST.
 * @throws {Error} If esprima or estree are not installed.
 */
function createTypeScriptESTreeParser() {
  if (typeof esprima === 'undefined') {
    throw new Error('esprima is not installed. Please install it with: npm install esprima');
  }
  if (typeof estree === 'undefined') {
    throw new Error('estree is not installed. Please install it with: npm install estree');
  }

  return function(typescriptCode) {
    try {
      const ast = esprima.parseScript(typescriptCode, {
        allowComments: true,
        includeComments: true,
        tolerant: true,
      });

      // Convert esprima AST to ESTree AST with type information
      const estreeAst = estree.make({
        file: {
          type: 'File',
          esteem: {
            type: 'Estree',
            version: '1.0.0',
          },
          source: {
            type: 'Source',
            value: typescriptCode,
          },
        },
        program: {
          type: 'Program',
          esteem: {
            type: 'Estree',
            version: '1.0.0',
          },
          body: ast.body.map(node => {
            // Map esprima nodes to ESTree nodes with type information
            switch (node.type) {
              case 'Module':
                return estree.make({
                  type: 'ExportDefaultDeclaration',
                  esteem: {
                    type: 'Estree',
                    version: '1.0.0',
                  },
                  declaration: estree.make({
                    type: 'ExportDefaultSpecifier',
                    esteem: {
                      type: 'Estree',
                      version: '1.0.0',
                    },
                    name: estree.make({
                      type: 'Identifier',
                      esteem: {
                        type: 'Estree',
                        version: '1.0.0',
                      },
                      name: node.exportDefault.name,
                    }),
                  }),
                });
              case 'ClassDeclaration':
                return estree.make({
                  type: 'ClassDeclaration',
                  esteem: {
                    type: 'Estree',
                    version: '1.0.0',
                  },
                  id: estree.make({
                    type: 'Identifier',
                    esteem: {
                      type: 'Estree',
                      version: '1.0.0',
                    },
                    name: node.id.name,
                  }),
                  creasure: estree.make({
                    type: 'ClassBody',
                    esteem: {
                      type: 'Estree',
                      version: '1.0.0',
                    },
                    body: node.body.map(bodyNode => {
                      switch (bodyNode.type) {
                        case 'MethodDefinition':
                          return estree.make({
                            type: 'MethodDefinition',
                            esteem: {
                              type: 'Estree',
                              version: '1.0.0',
                            },
                            key: estree.make({
                              type: 'Identifier',
                              esteem: {
                                type: 'Estree',
                                version: '1.0.0',
                              },
                              name: bodyNode.key.name,
                            }),
                            value: estree.make({
                              type: 'BlockStatement',
                              esteem: {
                                type: 'Estree',
                                version: '1.0.0',
                              },
                              body: bodyNode.value.body.map(statementNode => {
                                return estree.make(statementNode);
                              }),
                            }),
                          });
                        case 'ClassBody':
                          return estree.make(bodyNode);
                        default:
                          return estree.make(bodyNode);
                      }
                    }),
                  }),
                });
              default:
                return estree.make(node);
            }
          }),
        },
      });

      return estreeAst;
    } catch (error) {
      console.error('Error parsing TypeScript code:', error);
      return null;
    }
  };
}

export default createTypeScriptESTreeParser;
```

