```javascript
module.exports = function(config) {
  const { createProxyMiddleware, createHotModuleMiddleware } = require('webpack-dev-middleware');
  const { DockerMiddleware } = require('docker-middleware');

  const proxyConfig = config.proxy || {};
  const hotConfig = config.hot || false;

  const middleware = (req, res, next) => {
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
    console.log(`[${new Date().toISOString()}] Headers: ${JSON.stringify(req.headers)}`);

    // Proxying
    if (proxyConfig && proxyConfig.target) {
      createProxyMiddleware(proxyConfig.target, {
        prefix: proxyConfig.prefix || '',
      }, next);
      return;
    }

    // Serve static files
    if (req.url.startsWith((proxyConfig.base || '') + '/')) {
      return next();
    }

    // Handle other requests
    res.status(200).send('Hello from middleware!');
  };

  if (hotConfig) {
    middleware = (req, res, next) => {
      createHotModuleMiddleware(req, res, next);
    };
  }

  return {
    middleware,
    docker: (options) => {
      return new DockerMiddleware(options);
    },
  };
};
