```javascript
const fs = require('fs');
const cssMinifier = require('css-minifier');

/**
 * Minifies and optimizes a CSS file.
 * @param {string} inputFilePath - The path to the input CSS file.
 * @param {string} outputFilePath - The path to save the optimized CSS file.
 * @returns {Promise<void>} A promise that resolves when the process is complete.
 * @throws {Error} If there is an error during file reading, minification, or writing.
 */
async function minifyAndOptimizeCSS(inputFilePath, outputFilePath) {
  try {
    // Read the CSS file
    const cssContent = fs.readFileSync(inputFilePath, 'utf8');

    // Minify the CSS
    const minifiedCSS = cssMinifier.minify(cssContent);

    // Apply structural optimizations (example: remove duplicate declarations)
    const optimizedCSS = optimizeCSS(minifiedCSS);

    // Write the optimized CSS to the output file
    fs.writeFileSync(outputFilePath, optimizedCSS);

    console.log(`CSS minified and optimized. Output saved to ${outputFilePath}`);

  } catch (error) {
    console.error('Error:', error);
    throw error; // Re-throw the error to be handled by the caller
  }
}

/**
 * Applies structural optimizations to the CSS code.
 * This is a placeholder for more advanced optimizations.
 * @param {string} cssContent - The minified CSS content.
 * @returns {string} The optimized CSS content.
 */
function optimizeCSS(cssContent) {
  // Basic example: Remove duplicate declarations (very basic and might not catch all cases)
  const lines = cssContent.split('\n');
  const uniqueLines = new Set();
  const optimizedLines = [];

  for (const line of lines) {
    const trimmedLine = line.trim();
    if (!uniqueLines.has(trimmedLine)) {
      uniqueLines.add(trimmedLine);
      optimizedLines.push(line);
    }
  }

  return optimizedLines.join('\n');
}


// Example usage (replace with your file paths)
const inputCSSFile = 'input.css';
const outputCSSFile = 'output.css';

minifyAndOptimizeCSS(inputCSSFile, outputCSSFile).catch(err => {
  console.error("An error occurred:", err);
});
```

