import { parse } from 'unist-util';

/**
 * Checks if a Node.js module passes a test based on its content.
 *
 * @param {string} moduleContent The content of the Node.js module.
 * @param {string} testPassKeyword The keyword indicating a successful test (e.g., "test passed").
 * @returns {boolean} True if the module passes the test, false otherwise.
 */
function checkModuleTest(moduleContent, testPassKeyword) {
  try {
    const ast = parse(moduleContent);

    for (const node of ast.children) {
      if (node.value.includes(testPassKeyword)) {
        return true;
      }
    }

    return false;
  } catch (error) {
    console.error("Error parsing module content:", error);
    return false; // Return false in case of parsing errors
  }
}

export default checkModuleTest;
