function getNpmToken() {
  try {
    const config = require('node_modules/npm/lib/config');
    const token = config.token;
    if (token) {
      return token;
    }
  } catch (e) {
    // npm might not be installed or accessible
    console.warn("npm not found or accessible. Prompting for credentials.");
  }

  const username = prompt("Enter your npm username:");
  const password = prompt("Enter your npm password:");

  if (!username || !password) {
    console.error("Username and password are required.");
    return null;
  }

  try {
    const config = require('node_modules/npm/lib/config');
    config.user = username;
    config.password = password;
    config.save();
    console.log("Credentials saved to npm config.");
  } catch (e) {
    console.error("Error saving credentials to npm config:", e);
    return null;
  }

  // Attempt to retrieve the token again after saving
  try {
    const config = require('node_modules/npm/lib/config');
    const token = config.token;
    if (token) {
      return token;
    }
  } catch (e) {
    console.error("Failed to retrieve token after saving credentials:", e);
    return null;
  }
}

// Example usage:
const token = getNpmToken();

if (token) {
  console.log("Npm token:", token);
} else {
  console.log("Failed to retrieve npm token.");
}
