function minifyAtRuleParams(filepath) {
  const fs = require('fs');
  const path = require('path');
  const postcss = require('postcss');

  fs.readFile(filepath, 'utf8', (err, css) => {
    if (err) {
      console.error('Error reading file:', err);
      return;
    }

    const postcssOptions = {
      plugins: [
        require('postcss-at-rule-params')({
          minify: true,
        }),
      ],
    };

    postcss.parse(css, postcssOptions)
      .then(result => {
        const minifiedCss = result.css;
        fs.writeFile(filepath, minifiedCss, 'utf8', err => {
          if (err) {
            console.error('Error writing file:', err);
          } else {
            console.log('CSS file minified successfully.');
          }
        });
      })
      .catch(err => {
        console.error('Error processing CSS:', err);
      });
  });
}

// Example usage:
// minifyAtRuleParams('input.css');
