 * @param {object} options - Configuration options for the provider.
 * @param {string} options.region - The default AWS region.
 * @returns {AWSProvider} - An AWS credential provider instance.
 */
export function createCredentialsProvider(options = {}) {
  const { region = 'us-east-1' } = options;

  const credentials = new AWSProvider({
    region,
    credentialsPath: [
      '$.aws/credentials',
      '$.aws/config'
    ],
    profileName: process.env.AWS_PROFILE || 'default', // Optional: Use environment variable for profile
  });

  return credentials;
}
