```javascript
// postcss-normalize-urls.js
const postcss = require('postcss');

module.exports = function (options) {
  return function (root, rules) {
    return postcss.process(rules, {
      plugins: [
        {
          name: 'normalize-urls',
          process(root, rootNode) {
            const baseDir = options.baseDir || '.';
            const removeTrailingSlashes = options.removeTrailingSlashes || true;

            const normalizeUrl = (url) => {
              try {
                const resolvedUrl = new URL(url, baseDir).toString();
                if (removeTrailingSlashes && resolvedUrl.endsWith('/')) {
                  return resolvedUrl.slice(0, -1);
                }
                return resolvedUrl;
              } catch (e) {
                return url; // Return original URL if parsing fails
              }
            };

            rootNode.walkDecls((decl) => {
              if (decl.value) {
                decl.value = normalizeUrl(decl.value);
              }
            });

            return root;
          },
        },
      ],
    });
  };
};
```

