```javascript
const fs = require('fs');
const asn1Parser = require('asn1-js').parse;

/**
 * Parses an ASN.1 file and extracts relevant information for browserify-sign.
 *
 * @param {string} filePath The path to the ASN.1 file.
 * @returns {Promise<object>} A promise that resolves to an object containing the extracted information.
 *                           Rejects if the file cannot be read or parsed.
 */
async function parseAsn1ForBrowserifySign(filePath) {
  try {
    const fileContent = fs.readFileSync(filePath, 'utf8');
    const asn1Data = asn1Parser(fileContent);

    const extractedData = {};

    // Extract Distinguished Names (DNs)
    if (asn1Data && asn1Data.elements) {
      for (const element of asn1Data.elements) {
        if (element.tag === 'EX' && element.subtag === '01') { //EX is for Distinguished Names
          extractedData.distinguishedName = element.value.map(v => v.data.toString());
          break; // Assuming only one DN in the file
        }
      }
    }

    // Extract Subject Alternative Names (SANs)
    if (asn1Data && asn1Data.elements) {
      for (const element of asn1Data.elements) {
        if (element.tag === 'EX' && element.subtag === '02') { //EX is for Subject Alternative Names
          extractedData.subjectAltNames = element.value.map(v => v.data.toString());
          break; // Assuming only one SAN in the file
        }
      }
    }

    // Extract Issuer Serial
    if (asn1Data && asn1Data.elements) {
      for (const element of asn1Data.elements) {
        if (element.tag === '00' && element.subtag === '01') { //00 is for Serial Number
          extractedData.issuerSerial = element.value.map(v => v.data.toString());
          break; // Assuming only one serial number
        }
      }
    }

    return extractedData;

  } catch (error) {
    console.error('Error parsing ASN.1 file:', error);
    throw error; // Re-throw the error to be handled by the caller
  }
}


module.exports = parseAsn1ForBrowserifySign;
