import { KeyPair, generateKeyPair, encrypt, decrypt } from 'webcrypt';

/**
 * Performs modular exponentiation using the WebCrypt API.
 *
 * @param {bigint} base The base.
 * @param {bigint} exponent The exponent.
 * @param {bigint} modulus The modulus.
 * @returns {bigint} The result of (base^exponent) % modulus.
 */
async function modularExponentiation(base, exponent, modulus) {
  return await KeyPair.modExp(base, exponent, modulus);
}


/**
 * RSA Encryption function.
 * @param {string} plaintext The message to encrypt.
 * @param {bigint} publicKey The public key.
 * @returns {bigint} The encrypted message.
 */
async function encryptRSA(plaintext, publicKey) {
  const plaintextBigInt = BigInt(plaintext);
  return await modularExponentiation(plaintextBigInt, publicKey.e, publicKey.n);
}

/**
 * RSA Decryption function.
 * @param {bigint} ciphertext The encrypted message.
 * @param {bigint} privateKey The private key.
 * @returns {string} The decrypted message.
 */
async function decryptRSA(ciphertext, privateKey) {
  return (await modularExponentiation(ciphertext, privateKey.d, privateKey.n)).toString();
}


/**
 * Generates an RSA key pair using WebCrypt.
 * @returns {{publicKey: KeyPair, privateKey: KeyPair}} An object containing the public and private keys.
 */
async function generateRSAKeys() {
  const keyPair = await generateKeyPair({
    type: 'rsa',
    bits: 2048, // You can adjust the key size
  });

  return {
    publicKey: keyPair.publicKey,
    privateKey: keyPair.privateKey,
  };
}


// Example Usage (Illustrative - requires a browser environment with WebCrypt)
async function example() {
  const keys = await generateRSAKeys();
  const publicKey = keys.publicKey;
  const privateKey = keys.privateKey;

  const message = "Hello, RSA!";
  console.log("Original message:", message);

  const encryptedMessage = await encryptRSA(message, publicKey);
  console.log("Encrypted message:", encryptedMessage);

  const decryptedMessage = await decryptRSA(encryptedMessage, privateKey);
  console.log("Decrypted message:", decryptedMessage);
}

//example(); //Uncomment to run the example.  Requires a browser environment.
