```javascript
import * as Cstria from 'cstria';
import * as fs from 'fs/promises';

/**
 * Cleans a CSS file by removing browser hacks.
 *
 * @param {string} inputFilePath - The path to the input CSS file.
 * @param {string} outputFilePath - The path to the output cleaned CSS file.
 * @param {string[]} browserHacks - An array of known browser hacks to remove.
 * @returns {Promise<void>}
 */
async function cleanCss(inputFilePath, outputFilePath, browserHacks) {
  try {
    const cssContent = await fs.readFile(inputFilePath, 'utf-8');
    const ast = Cstria.parse(cssContent);

    const cleanedAst = removeBrowserHacks(ast, browserHacks);

    const cleanedCss = Cstria.stringify(cleanedAst);

    await fs.writeFile(outputFilePath, cleanedCss, 'utf-8');
    console.log(`Cleaned CSS written to ${outputFilePath}`);

  } catch (error) {
    console.error('Error cleaning CSS:', error);
  }
}


/**
 * Removes browser hacks from a CSS AST.
 *
 * @param {Cstria.Ast} ast - The CSS AST.
 * @param {string[]} browserHacks - An array of known browser hacks to remove.
 * @returns {Cstria.Ast} The cleaned CSS AST.
 */
function removeBrowserHacks(ast, browserHacks) {
  if (!ast) {
    return null;
  }

  if (ast.type === 'MediaFeatureQuery') {
    if (browserHacks.includes(ast.condition.conditionText)) {
      return null; // Remove the entire media query
    }
  } else if (ast.type === 'Declaration' && browserHacks.some(hack => ast.property.name.toLowerCase().includes(hack.toLowerCase()))) {
    return null; // Remove the declaration
  }

  for (const key in ast) {
    if (typeof ast[key] === 'object' && ast[key] !== null) {
      ast[key] = removeBrowserHacks(ast[key], browserHacks);
    }
  }

  return ast;
}



// Example Usage (replace with your file paths and hacks)
async function main() {
  const inputCssFile = 'input.css';
  const outputCssFile = 'output.css';
  const hacks = ['-webkit-', '-moz-', '-ms-'];

  await cleanCss(inputCssFile, outputCssFile, hacks);
}

//main(); // Uncomment to run the example
export {cleanCss};
```

```javascript
import WebCrypt from 'webcrypt';

/**
 * Encrypts data using the specified key and algorithm.
 * @param {string} data The data to encrypt.
 * @param {string} key The encryption key (hexadecimal string).
 * @param {string} algorithm The encryption algorithm (e.g., 'aes-256-cbc').
 * @returns {Promise<string>} A promise that resolves with the encrypted data (hexadecimal string).
 * @throws {Error} If WebCrypt is not available or if there is an error during encryption.
 */
async function publicEncrypt(data, key, algorithm) {
  try {
    const webcrypt = new WebCrypt();
    const encrypted = await webcrypt.publicEncrypt({
      data: data,
      key: Buffer.from(key, 'hex'),
      algorithm: algorithm,
    });
    return encrypted.toString('hex');
  } catch (error) {
    console.error("Error during public encryption:", error);
    throw error;
  }
}

/**
 * Decrypts data using the specified key and algorithm.
 * @param {string} data The data to decrypt (hexadecimal string).
 * @param {string} key The decryption key (hexadecimal string).
 * @param {string} algorithm The decryption algorithm (e.g., 'aes-256-cbc').
 * @returns {Promise<string>} A promise that resolves with the decrypted data.
 * @throws {Error} If WebCrypt is not available or if there is an error during decryption.
 */
async function privateDecrypt(data, key, algorithm) {
  try {
    const webcrypt = new WebCrypt();
    const decrypted = await webcrypt.privateDecrypt({
      data: Buffer.from(data, 'hex'),
      key: Buffer.from(key, 'hex'),
      algorithm: algorithm,
    });
    return decrypted.toString();
  } catch (error) {
    console.error("Error during private decryption:", error);
    throw error;
  }
}

export { publicEncrypt, privateDecrypt };
```

