const upon = require('upon-it');
const htmlparser = require('htmlparser2');

/**
 * Streams HTML form data and emits events for each field.
 *
 * @param {string} htmlString The HTML string containing the form data.
 * @param {function} onField - Callback function to handle each field.  Receives field name and value.
 * @param {function} onError - Callback function to handle errors.
 */
function streamFormParser(htmlString, onField, onError) {
  const parser = new htmlparser.Parser({
    onopentag: (name, attributes) => {
      if (name === 'input' || name === 'textarea' || name === 'select') {
        //console.log(`Found ${name} with attributes:`, attributes);
      }
    },
    ontext: (text) => {
      //console.log(`Found text: ${text}`);
    },
    onclosetag: (name) => {
      if (name === 'input' || name === 'textarea' || name === 'select') {
        //console.log(`Closed ${name}`);
        const fieldName = 'input'; // Default field name, adjust as needed
        const fieldValue = ''; // Default field value, adjust as needed

        // Extract name and value from the input tag
        const nameAttribute = (this.tag.attributes && this.tag.attributes['name']) ? this.tag.attributes['name'] : 'unknown';
        const valueAttribute = (this.tag.attributes && this.tag.attributes['value']) ? this.tag.attributes['value'] : '';

        fieldName = nameAttribute;
        fieldValue = valueAttribute;

        if (fieldName) {
          onField(fieldName, fieldValue);
        }
      }
    },
    onend: () => {
      //console.log('Finished parsing');
    },
    error: (err) => {
      onError(err);
    }
  });

  parser.write(htmlString);
  parser.end();
}

module.exports = streamFormParser;
```

The code defines a `streamFormParser` function that takes an HTML string, an `onField` callback, and an `onError` callback as arguments. It uses the `htmlparser2` library to parse the HTML string. The parser listens for `input`, `textarea`, and `select` tags. When it encounters these tags, it extracts the `name` and `value` attributes and calls the `onField` callback with the field name and value.  The `onend` and `error` handlers are also implemented for completeness.  The `onopentag` and `ontext` handlers are included for potential future expansion or debugging.  The `module.exports` statement makes the function available for use in other modules.

