/**
 * @typedef {object} RemarkPluginOptions
 * @property {object} [remarkPlugins] - An array of Remark plugins to apply to the AST.
 * @property {object} [remarkPluginsOptions] - An object of options to pass to the Remark plugins.
 */

/**
 * Remark plugin to parse Markdown using remark-parser.
 * @param {RemarkPluginOptions} options - Plugin options.
 * @returns {import('remark-parser').Plugin} - The Remark plugin.
 */
function remarkParserPlugin(options) {
  return function (markdown, file) {
    try {
      const remarkParser = require('remark-parser');
      const ast = remarkParser.parse(markdown);

      if (!ast) {
        return null; // Or handle the error as needed
      }

      return remark.process(ast, options.remarkPlugins, options.remarkPluginsOptions);
    } catch (error) {
      console.error("Error parsing Markdown with remark-parser:", error);
      return null; // Or handle the error as needed
    }
  };
}

module.exports = remarkParserPlugin;
