/**
 * Google Authentication Client Library for Node.js
 */
class GoogleAuth {
  /**
   * Constructor for GoogleAuth.
   * @param {object} config - Configuration object containing client ID, client secret, and authorized redirect URIs.
   */
  constructor(config) {
    this.clientId = config.clientId;
    this.clientSecret = config.clientSecret;
    this.redirectUris = config.redirectUris;
    this.scopes = config.scopes || [
      'https://www.googleapis.com/auth/drive',
      'https://www.googleapis.com/auth/gmail.readonly',
      'https://www.googleapis.com/auth/cloud-platform'
    ];
    this.oauth2Client = null;
  }

  /**
   * Initializes the OAuth 2.0 client.
   * @returns {Promise<void>}
   */
  async init() {
    const oauth2Client = new google.auth.OAuth2(this.clientId, this.clientSecret, this.redirectUris);
    this.oauth2Client = oauth2Client;
  }

  /**
   * Gets the authorization URL.
   * @returns {string} The authorization URL.
   */
  getAuthUrl() {
    const authUrl = this.oauth2Client.generateAuthUrl({
      accessType: 'offline',
      scope: this.scopes
    });
    return authUrl;
  }

  /**
   * Sets the access token.
   * @param {string} accessToken The access token.
   * @returns {void}
   */
  setAccessToken(accessToken) {
    this.oauth2Client.setAccessToken(accessToken);
  }

  /**
   * Gets the current access token.
   * @returns {string | null} The access token, or null if no token is available.
   */
  getAccessToken() {
    return this.oauth2Client.getAccessToken();
  }

  /**
   * Makes an API call to Google services.
   * @param {string} endpoint The API endpoint to call.
   * @param {object} [params] The request parameters.
   * @returns {Promise<object>} The API response.
   * @throws {Error} If the API call fails.
   */
  async callApi(endpoint, params = {}) {
    try {
      const client = new google.auth.Client(this.oauth2Client);
      const response = await client.request({
        method: 'get',
        url: endpoint,
        params: params
      });
      return response.data;
    } catch (error) {
      console.error('API call failed:', error);
      throw error;
    }
  }
}

