import { Duplex } from 'streams3';

/**
 * Creates a duplexer-like stream using Streams3.
 *
 * @param {ReadableStream | WritableStream} readableStream The readable stream to pipe into the duplexer.
 * @param {WritableStream | ReadableStream} writableStream The writable stream to pipe out of the duplexer.
 * @returns {Duplex} A Streams3 Duplex stream.
 */
function createDuplexer(readableStream, writableStream) {
  const duplex = new Duplex();

  duplex.readable = readableStream;
  duplex.writable = writableStream;

  return duplex;
}

export default createDuplexer;
```

```javascript
import { Duplex } from 'streams3';

/**
 * Creates a duplexer-like stream using Streams3.
 *
 * @param {AsyncIterable<any>} source - An asynchronous iterable representing the source of data.
 * @returns {Duplex} A Streams3 Duplex stream.
 */
function createDuplexerStream(source) {
  const readable = new Readable({
    async read(size) {
      const iterator = source[Symbol.asyncIterator]();
      let chunk;
      while ((chunk = await iterator.next())) {
        if (chunk.done) {
          this.push(null); // Signal end of stream
          return;
        }
        this.push(chunk);
      }
      this.push(null); // Signal end of stream
    },
    close() {
      this.push(null);
    },
  });

  const writable = new Writable({
    write(chunk) {
      // In a real-world scenario, you might want to process the chunk here.
      // For this example, we just pass it through.
      console.log("Writable received:", chunk);
    },
    close() {
      console.log("Writable closed.");
    },
    error(err) {
      console.error("Writable error:", err);
    },
  });

  return new Duplex({ readable, writable });
}

export { createDuplexerStream };
```

