```javascript
import * as mdast from '@mdast/core';

/**
 * Finds definition nodes in a Markdown AST.
 *
 * @param {mdast.Document} document The Markdown document AST.
 * @returns {Array<mdast.Node>} An array of definition nodes.
 */
function findDefinitionNodes(document) {
  const definitionNodes = [];

  function traverse(node) {
    if (node.type === 'definition') {
      definitionNodes.push(node);
    }

    if (node.children) {
      for (const child of node.children) {
        traverse(child);
      }
    }
  }

  traverse(document);
  return definitionNodes;
}
```

