```javascript
import * as postcss from 'postcss';
import * as cssVariables from 'postcss-css-variables';
import * as autoprefixer from 'autoprefixer';
import * as sugarMap from 'sugar-map';

/**
 * Parses a CSS file using PostCSS with robust error handling.
 * @param {string} cssFilePath - The path to the CSS file.
 * @param {string} outputFilePath - The path to save the processed CSS.
 * @param {object} options - Optional configuration for PostCSS plugins.
 * @returns {Promise<void>} - A promise that resolves when the CSS is processed successfully.
 * @throws {Error} - If an error occurs during CSS processing.
 */
async function processCssFile(cssFilePath, outputFilePath, options = {}) {
  try {
    const result = await postcss([
      cssVariables({ sourceMap: true }),
      autoprefixer({ sourceMap: true }),
    ]).process(
      cssFilePath,
      {
        destination: outputFilePath,
        ...options,
      }
    );

    if (result.errors.length > 0) {
      console.error('PostCSS Errors:', result.errors);
      throw new Error(`PostCSS processing failed with errors: ${JSON.stringify(result.errors)}`);
    }

    if (result.warnings.length > 0) {
      console.warn('PostCSS Warnings:', result.warnings);
    }

    // Optionally write the sourcemap to a separate file
    if (result.map) {
      await result.map.save('sourcemap.css');
    }

  } catch (error) {
    console.error('Error processing CSS file:', error);
    throw error; // Re-throw the error to be handled by the caller
  }
}

export default processCssFile;
