// trace.js
import { Tracing } from '@opentelemetry/api';
import { Resource } from '@opentelemetry/resources';
import { Span } from '@opentelemetry/trace';

// Initialize tracing
const tracing = new Tracing({ resource: new Resource({ attributes: { serviceName: 'my-node-app' } }) });

export async function startTrace(spanName) {
  return tracing.startSpan(spanName, {
    attributes: {
      operationName: spanName,
    },
  });
}

export function endTrace(span) {
  span.end();
}

// metrics.js
import { Metrics } from '@opentelemetry/api';
import { Meter } from '@opentelemetry/metrics';

// Initialize metrics
const metrics = new Metrics({ resource: new Resource({ attributes: { serviceName: 'my-node-app' } }) });
const meter = metrics.meter({ name: 'my-node-app' });

export function incrementCounter(name) {
  meter.increment({ name });
}

export function recordGauge(name, value) {
  meter.record({ name, value });
}

// logs.js
import { Logs } from '@opentelemetry/api';
import { Console } from '@opentelemetry/logs';

// Initialize logs
const logs = new Logs({
  level: 'info',
  handler: new Console(),
});

export function logMessage(severity, message) {
  logs.log({ severity, message });
}


// Example Usage (main.js)
import { startTrace, endTrace, incrementCounter, recordGauge, logMessage } from './trace.js';
import { incrementCounter, recordGauge, logMessage } from './metrics.js';
import { logMessage } from './logs.js';


async function main() {
  // Example Trace
  const spanName = 'process-data';
  const span = await startTrace(spanName);

  try {
    console.log('Processing data...');
    // Simulate some work
    await new Promise(resolve => setTimeout(resolve, 1000));
    console.log('Data processed successfully.');

    incrementCounter('data.processed');
    recordGauge('memory.usage', 12345);

  } catch (error) {
    console.error('Error processing data:', error);
  } finally {
    endTrace(span);
  }

  // Example Log
  logMessage('info', 'Application started successfully.');

  // Example Metric
  incrementCounter('user.login');
  recordGauge('cpu.usage', 75);
}

main();
