```html
<!-- index.html -->
<!DOCTYPE html>
<html>
<head>
  <title>SVG Webpack Example</title>
  <link rel="stylesheet" href="dist/bundle.css">
</head>
<body>
  <h1>SVG Example</h1>
</body>
</html>
```

**Explanation:**

1.  **`webpack.config.js`**:
    *   `svg-url-loader`: This loader replaces SVG URLs in CSS with the actual SVG content.
    *   `glob.Plugin`: This plugin automatically finds all SVG files in the project directory.  It's used to ensure that all SVG files are processed.
    *   `limit`:  This option in `svg-url-loader` specifies the maximum size of the SVG file (in bytes) that should be embedded.  Files larger than this limit will be treated as external URLs.

2.  **`src/index.js`**:
    *   Imports the CSS file. This ensures that the CSS is included in the bundle.

3.  **`style.css`**:
    *   Contains CSS rules that use SVG URLs.

4.  **`index.html`**:
    *   Links to the bundled CSS file.

**To run this example:**

1.  Make sure you have Node.js and npm installed.
2.  Create a `package.json` file in your project directory: `npm init -y`
3.  Install the necessary dependencies: `npm install webpack webpack-cli svg-url-loader glob style-loader css-loader`
4.  Create the files as shown above.
5.  Run the webpack build: `npx webpack`
6.  Open `index.html` in your browser to see the result.

This setup will bundle the CSS file, replacing the SVG URLs with the SVG content, resulting in a smaller bundle size and improved performance.  The `svg-url-loader` effectively tree-shakes the SVG data into the JavaScript bundle, avoiding separate HTTP requests for each SVG file.

```javascript
import { StyleSheet } from 'react-native';
import * as csstoxjs from 'csstoxjs';

/**
 * Converts a CSS text string to a React Native StyleSheet object.
 *
 * @param {string} cssText The CSS text string.
 * @returns {StyleSheet} A React Native StyleSheet object.
 * @throws {Error} If the CSS string is invalid or parsing fails.
 */
const cssToStyleSheet = (cssText) => {
  try {
    const parsedCss = csstoxjs.parse(cssText);
    const style = {};

    // Helper function to recursively build the style object
    const buildStyle = (node) => {
      if (node.type === 'declaration') {
        const property = node.property;
        const value = node.value;

        if (node.value.type === 'string') {
          style[property] = value.value;
        } else if (node.value.type === 'number') {
          style[property] = value.value;
        } else if (node.value.type === 'length') {
          style[property] = value.value;
        } else if (node.value.type === 'color') {
          style[property] = value.value;
        } else if (node.value.type === 'custom') {
          // Handle custom properties (e.g., --my-color)
          style[property] = value.value;
        } else if (node.value.type === 'function') {
          // Handle functions (e.g., calc())
          style[property] = value.value;
        } else if (node.value.type === 'map') {
          // Handle maps (e.g., background: linear-gradient(...))
          style[property] = value.value;
        } else if (node.value.type === 'list') {
          // Handle lists (e.g., display: flex; flex-direction: row;)
          style[property] = value.value;
        }
      } else if (node.type === 'rule') {
        // Handle rules (e.g., .my-class { ... })
        const selector = node.selector;
        const rule = node.declarations;

        if (rule) {
          buildStyle(rule);
        }
      }
    };

    buildStyle(parsedCss);

    return StyleSheet.create(style);
  } catch (error) {
    console.error('Error parsing CSS:', error);
    throw new Error('Invalid CSS string.');
  }
};

export default cssToStyleSheet;
```

```javascript
/**
 * Converts a CSS text string to a React Native stylesheet object.
 *
 * @param {string} cssText The CSS text string.
 * @returns {object} A React Native stylesheet object.  Returns an empty object if parsing fails.
 */
function cssToReactNativeStyleSheet(cssText) {
  try {
    const css = require('csstoxjs').parse(cssText);
    const style = {};

    function traverse(node) {
      if (node.type === 'declaration') {
        for (const property of node.properties) {
          const propertyName = property.name;
          const propertyValue = property.value;

          // Handle color values
          if (propertyName === 'color' || propertyName === 'background-color') {
            if (propertyValue.startsWith('#')) {
              style[propertyName] = `#${propertyValue.slice(1)}`;
            } else if (propertyValue.startsWith('rgb')) {
              const rgbMatch = propertyValue.match(/rgb\((\d+),\s*(\d+),\s*(\d+)\)/);
              if (rgbMatch) {
                style[propertyName] = `rgb(${rgbMatch[1]}, ${rgbMatch[2]}, ${rgbMatch[3]})`;
              }
            } else if (propertyValue.startsWith('rgba')) {
              const rgbaMatch = propertyValue.match(/rgba\((\d+),\s*(\d+),\s*(\d+),\s*([\d.]+)\)/);
              if (rgbaMatch) {
                style[propertyName] = `rgba(${rgbaMatch[1]}, ${rgbaMatch[2]}, ${rgbaMatch[3]}, ${rgbaMatch[4]})`;
              }
            } else if (propertyValue.startsWith('hsl')) {
              const hslMatch = propertyValue.match(/hsl\((\d+),\s*(\d+%),\s*(\d+%)?\)/);
              if (hslMatch) {
                style[propertyName] = `hsl(${hslMatch[1]}, ${hslMatch[2]}%, ${hslMatch[3] || '100%'})`;
              }
            } else if (propertyValue.startsWith('hsla')) {
              const hslaMatch = propertyValue.match(/hsla\((\d+),\s*(\d+%),\s*(\d+%),\s*([\d.]+)\)/);
              if (hslaMatch) {
                style[propertyName] = `hsla(${hslaMatch[1]}, ${hslaMatch[2]}%, ${hslaMatch[3]}%, ${hslaMatch[4]})`;
              }
            } else {
              style[propertyName] = propertyValue;
            }
          } else {
            style[propertyName] = propertyValue;
          }
        }
      }

      for (const child of node.children) {
        traverse(child);
      }
    }

    traverse(css);
    return style;

  } catch (error) {
    console.error("Error parsing CSS:", error);
    return {};
  }
}
