```javascript
import { transform } from 'jsx-transformer-plugin';

function addSourceProp(element) {
  if (typeof element === 'string') {
    return element;
  }

  if (element && element.type) {
    const newProps = { ...element.props, __source: element.props };
    element.props = newProps;

    if (element.children) {
      element.children = element.children.map(child => addSourceProp(child));
    }
  }

  return element;
}


export default function transformJSX(jsx) {
  return transform(jsx, {
    transform: (element) => addSourceProp(element)
  });
}
