const http = require('http');
const path = require('path');

function setupHotReloading(config) {
  const webpackDevStatic = require('webpack-dev-static');
  const webpack = require('webpack');

  const webpackConfig = {
    mode: 'development',
    devtool: 'inline-source-map',
    devServer: {
      static: {
        directory: config.publicPath || path.join(__dirname, 'public'),
      },
      hot: true,
      open: true,
    },
    plugins: [
      new webpackDevStatic({
        publicPath: config.publicPath || path.join(__dirname, 'public'),
      }),
    ],
  };

  const compiler = webpack(webpackConfig);

  const server = http.createServer((req, res) => {
    compiler.interceptLivereload();

    res.writeHead(200);
    res.end();
  });

  const port = config.port || 3000;
  server.listen(port, () => {
    console.log(`Server listening on port ${port}`);
  });
}

module.exports = setupHotReloading;
