/**
 * Transforms an asynchronous generator function into an ES2015 generator function.
 *
 * @param {Function} asyncGenerator - The asynchronous generator function to transform.
 * @returns {Function} - The transformed ES2015 generator function.
 * @throws {Error} - If the input is not a function.
 */
function convertAsyncGeneratorToGenerator(asyncGenerator) {
