class ChromeAPI {
  constructor(chromePath = '/usr/bin/google-chrome') {
    this.chromePath = chromePath;
    this.wsUrl = `ws://${chromePath}:443/devtools/browser`;
    this.devtoolsProtocol = require('devtools-public-protocol');
    this.wsSocket = null;
    this.target = null;
  }

  async connect() {
    try {
      this.wsSocket = await this.createWebSocket(this.wsUrl);
      await this.connectToTarget();
      console.log('Connected to Chrome DevTools');
    } catch (error) {
      console.error('Error connecting to Chrome:', error);
      return false;
    }
    return true;
  }

  async createWebSocket(url) {
    return new Promise((resolve, reject) => {
      const ws = new WebSocket(url);

      ws.onopen = () => {
        console.log('WebSocket connected');
        resolve(ws);
      };

      ws.onmessage = (event) => {
        try {
          const message = await this.parseMessage(event.data);
          this.handleMessage(message);
        } catch (error) {
          console.error('Error parsing message:', error);
        }
      };

      ws.onclose = (event) => {
        console.log('WebSocket closed:', event);
        this.wsSocket = null;
      };

      ws.onerror = (error) => {
        console.error('WebSocket error:', error);
        this.wsSocket = null;
      };
    });
  }

  async parseMessage(data) {
    const protocol = require('devtools-public-protocol');
    return protocol.decode(data);
  }

  handleMessage(message) {
    if (message.type === 'method_response') {
      this.processResponse(message);
    } else if (message.type === 'error') {
      console.error('Chrome Error:', message.message);
    }
  }

  processResponse(message) {
    const method = message.method;
    const args = message.args;

    if (method === 'Target.navigate') {
      this.navigate(args);
    } else if (method === 'Page.evaluate') {
      this.evaluate(args);
    } else if (method === 'Page.getProperties') {
      this.getProperties(args);
    } else if (method === 'Page.setProperties') {
      this.setProperties(args);
    } else if (method === 'Page.executeScript') {
      this.executeScript(args);
    } else if (method === 'Page.dumpFrame') {
      this.dumpFrame(args);
    } else if (method === 'Page.printFrame') {
      this.printFrame(args);
    } else if (method === 'Page.addScript') {
      this.addScript(args);
    } else if (method === 'Page.removeScript') {
      this.removeScript(args);
    } else if (method === 'Page.sendEvent') {
      this.sendEvent(args);
    } else if (method === 'Page.getConsoleMessages') {
      this.getConsoleMessages(args);
    } else if (method === 'Page.setConsoleMessages') {
      this.setConsoleMessages(args);
    } else if (method === 'Target.getSocketProxy') {
      this.getSocketProxy(args);
    } else if (method === 'Target.sendAuthToken') {
      this.sendAuthToken(args);
    } else if (method === 'Target.setExtensionState') {
      this.setExtensionState(args);
    } else if (method === 'Target.getExtensionState') {
      this.getExtensionState(args);
    } else if (method === 'Target.kill') {
      this.kill(args);
    } else if (method === 'Target.reload') {
      this.reload(args);
    } else if (method === 'Target.getBrowserInfo') {
      this.getBrowserInfo(args);
    } else if (method === 'Target.getDomains') {
      this.getDomains(args);
    } else if (method === 'Target.getNetworkConditions') {
      this.getNetworkConditions(args);
    } else if (method === 'Target.getScreenshot') {
      this.getScreenshot(args);
    } else if (method === 'Target.setScreenshot') {
      this.setScreenshot(args);
    } else if (method === 'Target.getFrame') {
      this.getFrame(args);
    } else if (method === 'Target.setFrame') {
      this.setFrame(args);
    } else if (method === 'Target.getFrames') {
      this.getFrames(args);
    } else if (method === 'Target.getTab') {
      this.getTab(args);
    } else if (method === 'Target.setTab') {
      this.setTab(args);
    } else if (method === 'Target.getWindows') {
      this.getWindows(args);
    } else if (method === 'Target.setWindow') {
      this.setWindow(args);
    } else if (method === 'Target.getHandles') {
      this.getHandles(args);
    } else if (method === 'Target.kill') {
      this.kill(args);
    } else if (method === 'Target.getPage') {
      this.getPage(args);
    } else if (method === 'Target.getHandles') {
      this.getHandles(args);
    } else if (method === 'Target.getSocketProxy') {
      this.getSocketProxy(args);
    } else if (method === 'Target.sendAuthToken') {
