/**
 * Parses a PostgreSQL bytea column into a readable format (JSON).
 * Uses the pg-bytea-parser library.
 *
 * @param {Buffer} byteaData The bytea data from PostgreSQL.
 * @returns {Promise<any>} A promise that resolves to the parsed data (JSON).
 * @throws {Error} If the pg-bytea-parser library is not installed.
 */
async function parseByteaToJson(byteaData) {
  try {
    const { parse } = require('pg-bytea-parser');
    const parsedData = await parse(byteaData);
    return parsedData;
  } catch (error) {
    if (error.code === 'MODULE_NOT_FOUND') {
      throw new Error('pg-bytea-parser library is not installed. Please run: npm install pg-bytea-parser');
    }
    throw error;
  }
}

module.exports = parseByteaToJson;
```

