const { Tracing } = require('@microsoft/application-insights');

// Initialize Application Insights with the instrumenting key
const tracing = new Tracing({
  instrumentationKey: process.env.APPINSIGHTS_INSTRUMENTATION_KEY,
});

// Configure the Azure Monitor trace exporter
tracing.setAzureMonitorExporter({
  endpoint: process.env.AZURE_MONITOR_ENDPOINT,
  key: process.env.AZURE_MONITOR_KEY,
});


/**
 * Azure Function to handle incoming requests and outgoing responses.
 * @param {req} req - The incoming request object.
 * @param {res} res - The outgoing response object.
 */
exports.myFunction = async (req, res) => {
  try {
    // Start a new trace
    await tracing.start();

    // Log the incoming request
    console.log('Incoming request:', req.method, req.url);
    tracing.log('Incoming request', { method: req.method, url: req.url });

    // Process the request (simulated)
    await new Promise(resolve => setTimeout(resolve, 100));

    // Prepare the response
    const responseData = { message: 'Request processed successfully!' };
    res.status(200).json(responseData);

    // Log the outgoing response
    console.log('Outgoing response:', res.statusCode);
    tracing.log('Outgoing response', { statusCode: res.statusCode });

    // Stop the trace
    await tracing.stop();

  } catch (error) {
    console.error('Error:', error);
    tracing.log('Error', { message: error.message });
    res.status(500).json({ error: 'Internal Server Error' });
  }
};
