function findVerticalUnicodeCharacters() {
  const unicode = require('unicode-aware');

  const sets = unicode.getSets();

  for (let i = 0; i < sets.length; i++) {
    const set = sets[i];
    const properties = set.properties;

    for (let j = 0; j < properties.length; j++) {
      const prop = properties[j];
      if (prop.name === 'v') {
        const chars = set.characters;
        for (let k = 0; k < chars.length; k++) {
          const char = chars[k];
          console.log(`Character: ${char.codePoint、《char.graphemeClusterBreak》}, Property: ${prop.name}`);
        }
      }
    }
  }
}

