/**
 * Remark plugin for MDX support.
 *
 * Allows Markdown documents to include JSX elements and React components,
 * rendering them as HTML.
 */
const remarkMDX = {
  /**
   * Processes MDX content and transforms it into HTML.
   * @param {string} md - The Markdown content.
   * @returns {Promise<string>} - A promise that resolves to the HTML content.
   */
  process(md) {
    try {
      const { JSX } = require('mdx-js');
      return JSX.render(md);
    } catch (error) {
      console.error("Error rendering MDX:", error);
      return `<div>Error rendering MDX: ${error.message}</div>`;
    }
  },

  /**
   *  Plugin metadata.
   */
  metadata: {
    name: 'remark-mdx',
    description: 'Remark plugin for MDX support',
    version: '1.0.0',
  },
};

module.exports = remarkMDX;
