```javascript
// This code snippet demonstrates how to create a Google API client and configure it for Google Sheets and Google Drive APIs.
// It assumes you have already set up a Google Cloud project, enabled the necessary APIs, and created credentials.

// Import the necessary libraries.  You'll need to install these using npm install @google-api-nodejs-client googleapis
const { GoogleAuth } = require('google-auth-library');
const { Sheets, Drive } = require('googleapis');

/**
 * Initializes the Google API client for Google Sheets and Google Drive.
 * @returns {object} An object containing the Sheets and Drive API clients.
 */
function initializeGoogleAPIClient() {
  // Configure authentication using OAuth 2.0.  Replace with your credentials.
  const auth = new GoogleAuth({
    keyFile: 'path/to/your/credentials.json', // Replace with the path to your credentials file
    scopes: ['https://www.googleapis.com/auth/spreadsheets', 'https://www.googleapis.com/auth/drive']
  });

  // Authenticate and get the client.
  const client = auth.getClient();

  // Initialize the Google Sheets API client.
  const sheets = Sheets({ version: 'v4' }, client);

  // Initialize the Google Drive API client.
  const drive = Drive({ version: 'v3' }, client);

  return { sheets, drive };
}


// Example usage (This part is not required for the core functionality, but shows how to use the initialized clients)
async function exampleUsage() {
  const { sheets, drive } = initializeGoogleAPIClient();

  // Example: Read data from a spreadsheet
  try {
    const spreadsheetId = 'your_spreadsheet_id'; // Replace with your spreadsheet ID
    const response = await sheets.spreadsheets.values.get({
      spreadsheetId: spreadsheetId,
      range: 'Sheet1!A:B' // Replace with the desired range
    });
    const values = response.data.values;
    console.log('Spreadsheet data:', values);
  } catch (error) {
    console.error('Error reading spreadsheet:', error);
  }

  // Example: Upload a file to Google Drive
  try {
    const media = drive.files.insert({
      name: 'my_uploaded_file.txt',
      content: 'This is the content of the file.'
    });
    console.log('File uploaded:', media.id);
  } catch (error) {
    console.error('Error uploading file:', error);
  }
}

//exampleUsage(); // Uncomment to run the example usage.  Remember to replace placeholders.

module.exports = { initializeGoogleAPIClient };
```

