import {
  useHeadless,
  useComponent,
  useStyle,
  useAccessibility,
  useLayout,
} from "@base-ui/headless";

// Define a custom component using useComponent
function MyCustomComponent() {
  const { component, style } = useComponent("div"); // Use a basic div as a base

  const { css } = useStyle(style); // Access the style object

  const { accessibility } = useAccessibility(); // Access accessibility features

  const { layout } = useLayout(); // Access layout features

  // Define custom styles using the 'css' object
  const customStyles = css`
    background-color: #f0f0f0;
    padding: 20px;
    border: 1px solid #ccc;
    border-radius: 5px;
    font-family: sans-serif;
  `;

  // Example of using accessibility features
  const ariaLabel = "My Custom Component";
  const ariaDescribedBy = "my-component-id";

  // Example of using layout features
  const layoutProps = {
    width: "80%",
    margin: "0 auto",
  };

  return (
    <component style={customStyles} aria-label={ariaLabel} aria-describedby={ariaDescribedBy} {...layoutProps}>
      <h1>Hello from my custom component!</h1>
      <p>This component is built with Base UI's headless components and hooks.</p>
    </component>
  );
}

// Example of using useHeadless (for setting document head properties)
function App() {
  useHeadless({
    title: "My Custom App",
    meta: [
      { name: "description", content: "A custom UI built with Base UI" },
    ],
  });

  return (
    <div>
      <MyCustomComponent />
    </div>
  );
}

export default App;
