import {
  sassCompile,
  sassVariables,
  sassFunctions,
  sassMixins,
  sassFunctionsAsObjects,
} from 'libsass';

function wrapLisasassFunctions() {
  const wrappedFunctions = {};

  // Wrap sassCompile
  wrappedFunctions.sassCompile = (...args) => {
    return sassCompile(...args);
  };

  // Wrap sassVariables
  wrappedFunctions.sassVariables = (...args) => {
    return sassVariables(...args);
  };

  // Wrap sassFunctions
  wrappedFunctions.sassFunctions = (...args) => {
    return sassFunctions(...args);
  };

  // Wrap sassMixins
  wrappedFunctions.sassMixins = (...args) => {
    return sassMixins(...args);
  };

  // Wrap sassFunctionsAsObjects
  wrappedFunctions.sassFunctionsAsObjects = (...args) => {
    return sassFunctionsAsObjects(...args);
  };

  return wrappedFunctions;
}

export default wrapLisasassFunctions;
