/**
 * Creates a tracer provider with a service name and max trace time.
 *
 * @param {string} serviceName The name of the service.
 * @param {number} maxTraceTime The maximum trace time in milliseconds.
 * @returns {Provider} A tracer provider instance.
 */
export function createTracerProvider(serviceName, maxTraceTime) {
  const builder = new Tracing.Builder();
  builder.withService(serviceName);
  builder.setMaxTraceTime(maxTraceTime);

  return builder.build();
}

/**
 * Creates a tracer instance from a tracer provider.
 *
 * @param {Provider} provider The tracer provider instance.
 * @returns {Tracing.Tracer} A tracer instance.
 */
export function createTracer(provider) {
  return provider.getTracer();
}
