import { CognitoIdentityClient, GetIdTokenCommand } from "@aws-sdk/cognito-identity-client";

async function authenticateNode(UserPoolId, UserPoolIdAlias, username, password) {
  const cognitoIdentityClient = new CognitoIdentityClient({
    region: "YOUR_AWS_REGION", // e.g., "us-east-1"
    endpoint: `https://${UserPoolId}.auth.${process.env.AWS_REGION}.amazoncognito.com`,
  });

  const command = new GetIdTokenCommand({
    UserPoolId: UserPoolId,
    Username: username,
