  return new Promise((resolve, reject) => {
    const command = 'yarn install esbuild-openbsd'; // Assuming a package exists with this name.  You might need to adjust this.

    exec(command, (error, stdout, stderr) => {
      if (error) {
        console.error(`exec error: ${error}`);
        reject(error);
        return;
      }
      if (stderr) {
        console.error(`stderr: ${stderr}`);
        reject(stderr);
        return;
      }
      console.log(`stdout: ${stdout}`);
      resolve();
    });
  });
}

