```javascript
const sassParse = require('sass-parse');

function extractImportGraph(sassFilePath) {
  try {
    const ast = sassParse.parse(sassFilePath);
    const importGraph = {};

    function traverse(node, parentNode = null) {
      if (node.type === 'use') {
        const importPath = node.value;
        if (!importGraph[importPath]) {
          importGraph[importPath] = [];
        }
        if (parentNode) {
          importGraph[parentNode.name].push(importPath);
        }
      }

      for (const key in node) {
        if (typeof node[key] === 'object' && node[key] !== null) {
          if (Array.isArray(node[key])) {
            for (const item of node[key]) {
              if (typeof item === 'object' && item !== null) {
                traverse(item, node);
              }
            }
          } else {
            traverse(node[key], node);
          }
        }
      }
    }

    traverse(ast);
    return importGraph;

  } catch (error) {
    console.error("Error parsing Sass:", error);
    return {}; // Return an empty graph in case of error
  }
}

module.exports = extractImportGraph;
```

```javascript
function extractImportGraph(sassFilePath) {
  try {
    const fs = require('fs');
    const path = require('path');
    const sassParser = require('sass-parse');

    const filePath = path.resolve(sassFilePath);
    const fileContent = fs.readFileSync(filePath, 'utf8');
    const ast = sassParser.parse(fileContent);

    const importGraph = {};
    const importNodes = [];

    function traverseAST(node, parentNode = null) {
      if (node.type === 'use') {
        const importPath = node.value;
        const importNode = {
          type: 'import',
          path: importPath,
          parent: parentNode,
          children: [],
        };
        importNodes.push(importNode);
        importGraph[importPath] = importNode;
      }

      for (const key in node) {
        if (node.hasOwnProperty(key)) {
          const child = node[key];
          if (typeof child === 'object' && child !== null) {
            traverseAST(child, importNode);
          }
        }
      }
    }

    traverseAST(ast);

    // Link nodes to form the graph
    for (let i = 0; i < importNodes.length; i++) {
      const node = importNodes[i];
      if (node.parent) {
        node.parent.children.push(node);
      }
    }

    return importNodes;
  } catch (error) {
    console.error('Error parsing Sass file:', error);
    return [];
  }
}

module.exports = extractImportGraph;
```

```javascript
/**
 * URI Handling Module for VS Code Extensions
 */

const uri = require('@uri/core');

/**
 * Parses a URI string.
 * @param {string} uriString The URI string to parse.
 * @returns {object | null} The parsed URI object, or null if parsing fails.
 */
function parseUri(uriString) {
  try {
    return uri.parse(uriString);
  } catch (error) {
    console.error("Error parsing URI:", error);
    return null;
  }
}

/**
 * Resolves a URI against a base URI.
 * @param {object} uri The URI to resolve.
 * @param {object} baseUri The base URI to resolve against.
 * @returns {object} The resolved URI object.
 */
function resolveUri(uri, baseUri) {
  try {
    return uri.resolve(baseUri);
  } catch (error) {
    console.error("Error resolving URI:", error);
    return null;
  }
}

/**
 * Normalizes a URI.
 * @param {object} uri The URI to normalize.
 * @returns {object} The normalized URI object.
 */
function normalizeUri(uri) {
  try {
    return uri.normalize();
  } catch (error) {
    console.error("Error normalizing URI:", error);
    return uri; // Return original URI on error
  }
}

/**
 * Checks if a URI is a custom scheme URI.
 * @param {object} uri The URI to check.
 * @returns {boolean} True if the URI is a custom scheme URI, false otherwise.
 */
function isCustomSchemeUri(uri) {
  return uri.scheme.startsWith('custom'); // Example: 'custom://...'
}

/**
 * Extracts the custom scheme from a URI.
 * @param {object} uri The URI to extract the scheme from.
 * @returns {string | null} The custom scheme, or null if no custom scheme is found.
 */
function getCustomScheme(uri) {
  if (uri.scheme && uri.scheme.startsWith('custom')) {
    return uri.scheme;
  }
  return null;
}

/**
 *  Creates a hierarchical URI.
 * @param {string} baseUri The base URI.
 * @param {string} path The path to append.
 * @returns {object} The hierarchical URI object.
 */
function createHierarchicalUri(baseUri, path) {
  try {
    return uri.format(baseUri, path);
  } catch (error) {
    console.error("Error creating hierarchical URI:", error);
    return null;
  }
}


module.exports = {
  parseUri,
  resolveUri,
  normalizeUri,
  isCustomSchemeUri,
  getCustomScheme,
  createHierarchicalUri,
};
```

