```javascript
import { String } from 'icu-js/normalizer/icu';
import { Trie } from 'javascript-trie';

/**
 * Creates a Unicode Trie data structure from a string.
 *
 * @param {string} text The Unicode string to create the Trie from.
 * @returns {object} A Trie object representing the Unicode string.
 */
function createUnicodeTrie(text) {
  const trie = new Trie();
  const normalizedText = String.normalize(text, 'NFKD').replace(/[\u0300-\u036f]/g, ''); // Remove diacritics

  for (let i = 0; i < normalizedText.length; i++) {
    const char = normalizedText[i];
    if (!trie.has(char)) {
      trie.insert(char);
    }
  }

  return trie;
}

export default createUnicodeTrie;
