```javascript
import { createEd25519 } from 'ed25519-js';
import { createRSAKey } from 'node-rsa';

/**
 * Key signing and verification function for rotated credentials.
 * Supports Ed25519 and RSA algorithms.
 *
 * @param {string} data - The data to be signed.
 * @param {object} key - The private key object.  Can be Ed25519 or RSA.
 * @param {string} algorithm - The signing algorithm to use ('ed25519' or 'rsa'). Defaults to 'ed25519'.
 * @returns {Promise<{signature: string, verified: boolean}>} - A promise that resolves to an object containing the signature and verification status.
 * @throws {Error} - If the algorithm is invalid or if there are issues with the key.
 */
async function signAndVerify(data, key, algorithm = 'ed25519') {
  try {
    if (!key) {
      throw new Error('Key is required.');
    }

    if (algorithm === 'ed25519') {
      const signer = createEd25519();
      const signature = await signer.sign(data);
      const verified = await signer.verify(data, signature);
      return { signature: signature.toString('hex'), verified };
    } else if (algorithm === 'rsa') {
      const rsaKey = key;
      const signer = createRSAKey(rsaKey);
      const signature = await signer.sign(data);
      const verified = await signer.verify(data, signature);
      return { signature: signature.toString('hex'), verified };
    } else {
      throw new Error('Invalid algorithm.  Must be "ed25519" or "rsa".');
    }
  } catch (error) {
    console.error('Error during signing/verification:', error);
    throw error; // Re-throw the error for the caller to handle.
  }
}

export default signAndVerify;

// Example Usage (for testing - not part of the core function)
async function exampleUsage() {
  // Ed25519 Example
  const ed25519Key = createEd25519();
  const data = 'This is the data to be signed.';
  const result = await signAndVerify(data, ed25519Key, 'ed25519');
  console.log('Ed25519 Signature:', result.signature);
  console.log('Ed25519 Verified:', result.verified);

  // RSA Example
  const rsaKey = createRSAKey({ keySize: 2048 });
  const rsaData = 'This is RSA data.';
  const rsaResult = await signAndVerify(rsaData, rsaKey, 'rsa');
  console.log('RSA Signature:', rsaResult.signature);
  console.log('RSA Verified:', rsaResult.verified);
}

//exampleUsage(); // Uncomment to run the example.
```

