import { createDeserializer } from 'eventstream-serde-node';
import { EventStream } from 'event-stream';

/**
 * Creates a serde for EventStream using eventstream-serde-node.
 *
 * @returns {function} A function that takes an EventStream and returns a deserialized stream.
 */
function createEventStreamSerde() {
  return (stream) => {
    const deserializer = createDeserializer();
    const deserializedStream = new EventStream(deserializer);

    stream.pipe(deserializer).pipe(deserializedStream);

    return deserializedStream;
  };
}

export default createEventStreamSerde;
