import { EventStream } from 'event-stream';
import { serialize, deserialize } from 'serde';

/**
 * Serializes an EventStream to a JSON string.
 * @param {EventStream} stream The EventStream to serialize.
 * @returns {Promise<string>} A promise that resolves to the JSON string representation of the stream.
 * @throws {Error} If serialization fails.
 */
async function serializeEventStream(stream) {
  try {
    const serialized = await serialize(stream);
    return JSON.stringify(serialized);
  } catch (error) {
    console.error("Serialization error:", error);
    throw error;
  }
}

/**
 * Deserializes a JSON string to an EventStream.
 * @param {string} jsonString The JSON string to deserialize.
 * @returns {Promise<EventStream>} A promise that resolves to an EventStream.
 * @throws {Error} If deserialization fails.
 */
async function deserializeEventStream(jsonString) {
  try {
    const deserialized = await deserialize(jsonString);
    return deserialized;
  } catch (error) {
    console.error("Deserialization error:", error);
    throw error;
  }
}


export { serializeEventStream, deserializeEventStream };
