// Mock Workspace class
class Workspace {
  documents: TextDocument[] = [];

  addDocument(textDocument: TextDocument): void {
    this.documents.push(textDocument);
  }

  updateDocument(textDocument: TextDocument): void {
    const index = this.documents.findIndex((doc) => doc.uri === textDocument.uri);
    if (index !== -1) {
      this.documents[index] = textDocument;
    }
  }

  removeDocument(textDocument: TextDocument): void {
    this.documents = this.documents.filter((doc) => doc.uri !== textDocument.uri);
  }

  saveDocument(textDocument: TextDocument): void {
    const index = this.documents.findIndex((doc) => doc.uri === textDocument.uri);
    if (index !== -1) {
      this.documents[index] = textDocument;
    }
  }

  getDocument(uri: string): TextDocument | undefined {
    return this.documents.find((doc) => doc.uri === uri);
  }
}


export {
  handleTextDocumentCreate,
  handleTextDocumentUpdate,
  handleTextDocumentDelete,
  handleTextDocumentSave,
  handleTextDocumentSymbol,
  handleDiagnostic,
  handleCompletion,
  handleInitialize,
  handleTextDocumentOpen,
  handleTextDocumentClose,
};
