```javascript
import { encode } from 'svg-url-encode';

/**
 * Encodes SVG data to a compact URL format suitable for CSS/HTML.
 *
 * @param {string} svgData The SVG data to encode.
 * @returns {string} The encoded SVG data URL.  Returns an empty string if input is invalid.
 */
function encodeSvgData(svgData) {
  if (typeof svgData !== 'string' || svgData.trim() === '') {
    return ""; // Handle invalid input
  }

  try {
    const encodedData = encode(svgData);
    return encodedData;
  } catch (error) {
    console.error("Error encoding SVG data:", error);
    return ""; // Return empty string on error
  }
}


export default encodeSvgData;
