/**
 * node-debugging-tools module
 *
 * Provides functions for debugging Node.js modules and the event loop.
 */

const fs = require('fs');

function inspectActiveHandles() {
  try {
    const handles = require('child_process').getActiveHandles();
    console.log('Active Handles:', handles);
    return handles;
  } catch (error) {
    console.error('Error inspecting active handles:', error);
    return [];
  }
}

function monitorEventLoop(callback) {
  const intervalId = setInterval(() => {
    const queue = require('libuv').getQueue();
    if (queue) {
      console.log('Event Loop Queue Length:', queue.length);
    } else {
      console.log('Event Loop Queue: Empty');
    }
    callback();
  }, 100); // Check every 100ms

  return () => {
    clearInterval(intervalId);
  };
}

function profilePerformance(callback) {
  const start = Date.now();
  console.log('Profiling started...');

  const end = () => {
    const elapsed = Date.now() - start;
    console.log(`Profiling finished. Elapsed time: ${elapsed}ms`);
    callback(elapsed);
  };

  // Simulate some work
  setTimeout(() => {
    console.log('Simulating work...');
    end();
  }, 1000);
}


module.exports = {
  inspectActiveHandles,
  monitorEventLoop,
  profilePerformance,
};
