```javascript
/**
 * @typedef {Object} KoaPluginOptions
 * @property {string} [tsCompilerPath] - Path to the TypeScript compiler (e.g., 'node_modules/.bin/tsc'). Defaults to 'tsc'.
 */

/**
 * Koa plugin for TypeScript support.
 *
 * @param {KoaPluginOptions} options - Configuration options for the plugin.
 * @returns {import('@koa/plugin').KoaPlugin} - The Koa plugin.
 */
function koaTs(options = {}) {
  const { tsCompilerPath = 'tsc' } = options;

  return async (app) => {
    app.use(async (context, next) => {
      try {
        // Find all TypeScript files in the request path
        const files = await findTsFiles(context.request.request.url);

        // Compile the TypeScript files
        const compiledFiles = await compileTsFiles(files, tsCompilerPath);

        // Replace the TypeScript files with the compiled JavaScript files
        for (const file of files) {
          const compiledFilePath = file.replace(/\.ts$/, '.js');
          if (compiledFiles[compiledFilePath]) {
            const content = compiledFiles[compiledFilePath];
            await context.request.request.write(content);
            await context.request.request.set('Content-Type', 'application/javascript');
            return;
          }
        }
      } catch (err) {
        console.error('TypeScript compilation error:', err);
        context.error(err);
      }
      await next();
    });
  };

  /**
   * Finds all TypeScript files in the given URL path.
   * @param {string} path - The URL path to search.
   * @returns {Promise<string[]>} - A promise that resolves to an array of TypeScript file paths.
   */
  async function findTsFiles(path) {
    const fs = require('fs').promises;
    const pathModule = require('path');

    try {
      const files = await fs.readdir(path);
      return files
        .filter(file => file.endsWith('.ts'))
        .map(file => pathModule.join(path, file));
    } catch (err) {
      console.error('Error reading directory:', err);
      throw err;
    }
  }

  /**
   * Compiles the given TypeScript files using the specified compiler path.
   * @param {string[]} files - An array of TypeScript file paths.
   * @param {string} compilerPath - The path to the TypeScript compiler.
   * @returns {Promise<Object>} - A promise that resolves to an object mapping compiled JavaScript file paths to their content.
   */
  async function compileTsFiles(files, compilerPath) {
    const { exec } = require('child_process');
    const fs = require('fs').promises;

    const compilePromises = files.map(async (file) => {
      const outputDir = file.replace(/\.ts$/, '.js');
      const command = `${compilerPath} ${file} -o ${outputDir}`;

      try {
        const { stdout, stderr } = await exec(command);
        if (stderr) {
          console.error(`Compilation error for ${file}: ${stderr}`);
          throw new Error(`Compilation error for ${file}: ${stderr}`);
        }
        const content = await fs.readFile(`${outputDir}.js`, 'utf8');
        return { [outputDir]: content };
      } catch (err) {
        console.error(`Error compiling ${file}: ${err}`);
        throw err;
      }
    });

    return Promise.all(compilePromises);
  }
}

module.exports = koaTs;
