import { createParser, createTransformer } from 'mdast';
import { GFMAutolink } from 'mdast-extension-autolink';

/**
 * Parses and serializes GFM autolink literals in Markdown.
 *
 * @param {string} markdown The Markdown string to parse and serialize.
 * @returns {string} The serialized Markdown string with GFM autolinks.
 */
function processGFMAutolinks(markdown) {
  const parser = createParser({
    extensions: [GFMAutolink],
  });

  const ast = parser.parse(markdown);

  const transformer = createTransformer({
    plugins: [GFMAutolink],
  });

  const transformedMarkdown = transformer.transform(ast);

  return transformedMarkdown;
}

export default processGFMAutolinks;
