```javascript
import { Buffer } from 'buffer';
import * as utf8 from 'utf8-js';

/**
 * Checks if a buffer contains valid UTF-8 encoded data.
 *
 * @param {Buffer} buffer The buffer to check.
 * @returns {boolean} True if the buffer contains valid UTF-8 data, false otherwise.
 * @throws {Error} If the input is not a Buffer.
 */
function isValidUtf8Buffer(buffer) {
  if (!(buffer instanceof Buffer)) {
    throw new Error("Input must be a Buffer.");
  }

  try {
    utf8.parse(buffer.toString(), (err, decoded) => {
      if (err) {
        return false;
      }
      return true;
    });
  } catch (e) {
    return false;
  }
}

export default isValidUtf8Buffer;
