```javascript
import { createPool } from 'sql-br/pool';
import { Pool } from 'sql-br';

async function convertPlaceholders(sqlText, params) {
  // This function takes SQL text with named placeholders and a set of parameters.
  // It returns the SQL text with unnamed compile-time placeholders and the parameters.

  // Example:
  // sqlText: "SELECT * FROM users WHERE id = :id AND name = :name",
  // params: { id: 123, name: 'John' }

  // The function replaces named placeholders (e.g., :id) with unnamed placeholders (e.g., $1).
  // It also ensures that the parameters are correctly mapped to the new placeholders.

  const placeholderMap = {};
  let newSql = sqlText;

  // Find all named placeholders in the SQL text.
  const placeholderRegex = /:(\w+)/g;
  let match;

  while ((match = placeholderRegex.exec(sqlText)) !== null) {
    const placeholderName = match[1];
    const placeholderIndex = newSql.indexOf(':'); // Find the index of the colon
    newSql = newSql.replace(match[0], '$' + (placeholderMap[placeholderName] || placeholderMap[Object.keys(placeholderMap).length + 1]));
    placeholderMap[placeholderName] = placeholderIndex;
  }

  return { newSql, params };
}


// Example Usage (requires a database connection)
async function main() {
  const pool = new Pool({
    user: 'your_user',
    host: 'your_host',
    database: 'your_database',
    password: 'your_password',
    port: 5432,
  });

  try {
    const sql = "SELECT * FROM users WHERE id = :id AND name = :name";
    const params = { id: 123, name: 'John' };

    const { newSql, params } = convertPlaceholders(sql, params);

    console.log("Original SQL:", sql);
    console.log("Converted SQL:", newSql);
    console.log("Parameters:", params);

    // Now you can use the newSql with your database driver.
    // For example, using sql-br:
    // const client = await pool.connect();
    // const result = await client.query(newSql, params);
    // client.release();
    // console.log(result.rows);

  } catch (error) {
    console.error("Error:", error);
  } finally {
    await pool.end();
  }
}

main();
