import watch from 'watch-iemobile';

/**
 * Watches globs and executes a function upon change, with intelligent defaults for debouncing and queueing.
 *
 * @param {string[]} globs An array of globs to watch.
 * @param {function} callback The function to execute when a glob changes.
 * @param {object} [options] Optional configuration object.
 * @param {number} [options.debounce=250] The debounce time in milliseconds.
 * @param {number} [options.queueSize=5] The maximum size of the queue.
 */
function watchGlobs(globs, callback, options = {}) {
  const { debounce = 250, queueSize = 5 } = options;

  const queue = [];

  watch(globs, (changes) => {
    changes.forEach((change) => {
      if (queue.length >= queueSize) {
        queue.shift(); // Remove oldest item if queue is full
      }
      queue.push(change);
    });

    if (queue.length > 0) {
      // Execute the callback after debounce
      setTimeout(() => {
        queue.forEach(change => {
          callback(change);
        });
        queue.length = 0; // Clear the queue after execution
      }, debounce);
    }
  });
}

export default watchGlobs;
```

