  title: 'MyComponent',
  component: MyComponent,
};

export const Default = () => <MyComponent name="John" age={30} />;
export const WithDifferentProps = () => <MyComponent name="Jane" age={25} />;
export const ErrorState = () => <MyComponent name="" age="-5" />; // Demonstrates error handling.



// src/components/MyComponent.test.js
import MyComponent from './MyComponent';

describe('MyComponent', () => {
  it('renders with default props', () => {
    const wrapper = render(<MyComponent name="John" age={30} />);
    expect(wrapper.text()).toContain('Hello, John!');
    expect(wrapper.text()).toContain('You are 30 years old.');
  });

  it('renders with different props', () => {
    const wrapper = render(<MyComponent name="Jane" age={25} />);
    expect(wrapper.text()).toContain('Hello, Jane!');
    expect(wrapper.text()).toContain('You are 25 years old.');
  });

  it('handles empty name prop', () => {
    const wrapper = render(<MyComponent name="" age={30} />);
    expect(wrapper.text()).toContain('Hello, !');
    expect(wrapper.text()).toContain('You are 30 years old.');
  });

  it('handles negative age prop', () => {
    const wrapper = render(<MyComponent name="John" age="-5" />);
    expect(wrapper.text()).toContain('Hello, John!');
    expect(wrapper.text()).toContain('You are -5 years old.');
  });

  it('renders without crashing', () => {
    render(<MyComponent name="Test" age={10} />);
  });
});
