  buckets: [0, 100, 1000, Infinity],
});

// Function to record a value to the histogram
function recordValue(value) {
  myHistogram.record(value);
}

// Function to record a counter
const myCounter = meter.addCounter('my_counter');

// Function to increment the counter
function incrementCounter() {
  myCounter.add(1);
}

// Function to record a gauge
const myGauge = meter.addGauge('my_gauge');

// Function to set the gauge value
function setGaugeValue(value) {
  myGauge.set(value);
}


// Example usage:
recordValue(50);
recordValue(150);
incrementCounter();
incrementCounter();
setGaugeValue(25);

// Export the metrics to Prometheus
async function startPrometheus() {
  const collector = new Collector({
    metrics: [meter],
    resource: new PrometheusResource(),
  });

  await collector.start();

  console.log('Prometheus metrics collector started.');

  // Keep the application running to allow metrics to be collected
  // In a real application, you would handle other application logic here.
  // For this example, we'll just keep the process running indefinitely.
  process.stdin.resume();
  process.stdin.setEncoding('utf8');
}

