```javascript
import * as steps from 'gherkin-js';

/**
 * Parses a Gherkin file and extracts feature, scenario, and step information.
 *
 * @param {string} filePath The path to the Gherkin file.
 * @returns {Promise<object[]>} An array of objects, where each object represents a scenario
 *                              and contains the feature, scenario, and steps.  Returns an empty array if parsing fails.
 * @throws {Error} If the file does not exist or is not a valid Gherkin file.
 */
async function parseGherkinFile(filePath) {
  try {
    const features = await steps.parse(filePath);
    const scenarios = [];

    for (const feature of features) {
      for (const scenario of feature.scenarios) {
        const stepsArray = scenario.steps;
        const scenarioData = {
          feature: feature.name,
          scenario: scenario.name,
          steps: stepsArray.map(step => ({
            step: step.statement,
            status: step.status,
            message: step.message,
          })),
        };
        scenarios.push(scenarioData);
      }
    }

    return scenarios;
  } catch (error) {
    console.error("Error parsing Gherkin file:", error);
    return []; // Return an empty array in case of error
  }
}


export default parseGherkinFile;
```

