/**
 * Parses and serializes GFM footnotes using the mdast extension.
 *
 * @param {string} markdown The markdown string containing footnotes.
 * @returns {string} The markdown string with footnotes parsed and serialized.
 */
function processFootnotes(markdown) {
  const parser = createMarkdownParser({
    extensions: [Footnote],
  });

  const ast = parser.parse(markdown);
  const serializedMarkdown = parser.stringify(ast);

  return serializedMarkdown;
}

export default processFootnotes;
