import { createSnapshot } from 'vue-snapshot';

/**
 * Saves a snapshot of a Vue component to a file.
 *
 * @param {Vue} Vue - The Vue instance.
 * @param {string} componentName - The name of the component.
 * @param {string} filePath - The path to save the snapshot to.
 * @param {object} options - Optional configuration options for snapshotting.
 *   - `includeUnusedNodes`: Whether to include unused nodes in the snapshot. Defaults to false.
 *   - `deep`: Whether to perform a deep comparison. Defaults to true.
 */
export function saveComponentSnapshot(Vue, componentName, filePath, options = {}) {
  createSnapshot({
    component: Vue.component(componentName),
    ...options,
  })
    .then((snapshot) => {
      const fs = require('fs');
      fs.writeFileSync(filePath, JSON.stringify(snapshot, null, 2));
      console.log(`Snapshot saved to ${filePath}`);
    })
    .catch((error) => {
      console.error(`Error saving snapshot: ${error}`);
    });
}
