/**
 * Creates a CloudEvent client.
 *
 * @param {string} eventSource - The CloudEvents source (e.g., 'bus', 'http').
 * @param {string} eventType - The CloudEvents type.
 * @param {string} eventSchema - The CloudEvents schema (e.g., 'https://www.cloudevents.io/spec/1.0/CloudEvent/json').
 * @returns {CloudEvents} - A CloudEvents client instance.
 * @throws {Error} - If eventSource is invalid.
 */
function createCloudEventsClient(eventSource, eventType, eventSchema) {
  if (!['bus', 'http'].includes(eventSource)) {
    throw new Error('Invalid eventSource. Must be "bus" or "http".');
  }

  const cloudEvents = new CloudEvents({
    source: eventSource,
    type: eventType,
    specversion: '1.0',
    schema: eventSchema,
  });

