// src/components/StripeCheckout.js
import React, { useState, useEffect } from 'react';
import StripeCheckout from 'stripe-checkout-react';

function StripeCheckout({ amount, currency, description, onSuccess, onCancel }) {
  const [loading, setLoading] = useState(false);

  const handleCheckout = async () => {
    setLoading(true);
    try {
      const result = await StripeCheckout.launch({
        amount: amount * 100, // Stripe expects amount in cents
        currency: currency,
        description: description,
        token: true,
        closeOnComplete: true,
        closeOnCancel: true,
        stripeKey: process.env.REACT_APP_STRIPE_SECRET_KEY, // Use environment variable
        onSuccess: (token) => {
          console.log('Checkout successful:', token);
          onSuccess(token);
        },
        onCancel: () => {
          console.log('Checkout cancelled');
          onCancel();
        },
      });
    } catch (error) {
      console.error('Error launching checkout:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <button onClick={handleCheckout} disabled={loading}>
      {loading ? 'Processing...' : `Pay ${amount} ${currency}`}
    </button>
  );
}

export default StripeCheckout;


