const { Performance } = require('webpack-perf');
const fs = require('fs');

/**
 * Measures and analyzes the speed of Webpack loaders and plugins using webpack-perf.
 *
 * @param {string} entry - The entry point of the Webpack configuration.
 * @param {string} output - The output directory of the Webpack configuration.
 * @param {string} configFilePath - The path to the Webpack configuration file.
 */
async function analyzeWebpackPerformance(entry, output, configFilePath) {
  try {
    const perf = new Performance({
      entry,
      output,
      config: require(configFilePath),
    });

    await perf.start();
    await perf.end();

    const stats = perf.getStats();

    console.log('Webpack Performance Stats:');
    console.log('--------------------------');

    // Calculate total time
    const totalTime = stats.total;
    console.log(`Total Time: ${totalTime}ms`);

    // Calculate overhead
    const overhead = stats.overhead;
    console.log(`Overhead: ${overhead}ms`);

    // Analyze loader and plugin performance
    console.log('\nLoader/Plugin Performance:');
    for (const loader of stats.loaders) {
      console.log(`  Loader: ${loader.name}`);
      console.log(`    Time: ${loader.time}ms`);
      console.log(`    Overhead: ${loader.overhead}ms`);
      console.log(`    Size Gap: ${loader.sizeGap}ms`);
    }

    for (const plugin of stats.plugins) {
      console.log(`  Plugin: ${plugin.name}`);
      console.log(`    Time: ${plugin.time}ms`);
      console.log(`    Overhead: ${plugin.overhead}ms`);
      console.log(`    Size Gap: ${plugin.sizeGap}ms`);
    }

    // Optionally, write the stats to a file
    fs.writeFileSync('webpack_performance_stats.json', JSON.stringify(stats, null, 2));
    console.log('\nPerformance stats written to webpack_performance_stats.json');

  } catch (error) {
    console.error('Error analyzing Webpack performance:', error);
  }
}


// Example usage (replace with your actual values)
// analyzeWebpackPerformance('./src/index.js', './dist', './webpack.config.js');
