import ExcelWorkbookManager from 'excel-workbook-manager';

/**
 * Reads an XLSX file and writes the data to a CSV file.
 * @param {string} xlsxFilePath - The path to the XLSX file.
 * @param {string} csvFilePath - The path to the output CSV file.
 * @param {string} sheetName - The name of the sheet to read (default: 'Sheet1').
 * @returns {Promise<void>}
 */
async function convertXlsxToCsv(xlsxFilePath, csvFilePath, sheetName = 'Sheet1') {
  try {
    const workbookManager = new ExcelWorkbookManager();
    const workbook = await workbookManager.open(xlsxFilePath);

    if (!workbook) {
      throw new Error(`Failed to open XLSX file: ${xlsxFilePath}`);
    }

    const sheet = workbook.getSheet(sheetName);

    if (!sheet) {
      throw new Error(`Sheet "${sheetName}" not found in XLSX file.`);
    }

    const data = sheet.getData();

    if (!data) {
      throw new Error(`No data found in sheet "${sheetName}".`);
    }

    const csv = workbookManager.toCsv(data);

    await workbookManager.save(csvFilePath, {
      encoding: 'utf8',
      // Optional: Add other save options as needed
    });

    console.log(`Successfully converted ${xlsxFilePath} to ${csvFilePath}`);

  } catch (error) {
    console.error(`Error converting XLSX to CSV: ${error.message}`);
    throw error; // Re-throw the error for handling upstream
  }
}


/**
 * Writes data to an XLSX file, including multiple worksheets.
 * @param {string} xlsxFilePath - The path to the output XLSX file.
 * @param {Array<Array<any>>} data - The data to write to the worksheets.  Each inner array represents a sheet.
 * @param {Array<string>} sheetNames - An array of sheet names.
 * @returns {Promise<void>}
 */
async function writeDataToXlsx(xlsxFilePath, data, sheetNames) {
  try {
    const workbookManager = new ExcelWorkbookManager();
    const workbook = await workbookManager.create();

    if (!workbook) {
      throw new Error("Failed to create new workbook");
    }

    for (let i = 0; i < data.length; i++) {
      const sheetData = data[i];
      const sheetName = sheetNames[i];

      if (!sheetData) {
        console.warn(`Skipping sheet ${sheetName} due to empty data.`);
        continue;
      }

      const sheet = workbook.createSheet(sheetName);
      const rowData = sheetData.map(item => {
        if (typeof item === 'number') {
          return item;
        } else if (typeof item === 'boolean') {
          return item;
        } else if (item === null || item === undefined) {
          return '';
        } else {
          return String(item);
        }
      });

      sheet.write(rowData);
    }

    await workbookManager.save(xlsxFilePath);
    console.log(`Successfully wrote data to ${xlsxFilePath}`);

  } catch (error) {
    console.error(`Error writing data to XLSX: ${error.message}`);
    throw error;
  }
}


// Example Usage (Illustrative - requires XLSX data)
async function runExample() {
  try {
    // Example: Convert a file
    // await convertXlsxToCsv('input.xlsx', 'output.csv', 'Sheet1');

    // Example: Write data to a new XLSX file with multiple sheets
    const data = [
      [1, 'Alice', 30],
      [2, 'Bob', 25],
      [3, 'Charlie', 35],
      [4, 'David', 28]
    ];
    const sheetNames = ['Sheet1', 'Sheet2'];
    const sheet2Data = [
      ['Product', 'Price'],
      ['Apple', 1.00],
      ['Banana', 0.50]
    ];

    await writeDataToXlsx('output.xlsx', data, sheetNames);
    await writeDataToXlsx('output.xlsx', sheet2Data, ['Sheet2']);

  } catch (error) {
    console.error("Example failed:", error);
  }
}

//runExample(); // Uncomment to run the example.
