```javascript
/** @type {import('storybook-addon-docs').AddonDecorator} */
export default {
  /**
   * Custom storiesOf method to allow prop editing in the story canvas.
   * @param {import('storybook-addon-docs').StoryObj} story
   * @param {object} props
   * @returns {import('storybook-addon-docs').StoryObj}
   */
  storiesOf: (story, props) => {
    const storyMeta = story.meta;

    if (storyMeta.args) {
      const args = storyMeta.args;

      const updateProps = (propertyName, newValue) => {
        const newArgs = { ...args };
        newArgs[propertyName] = newValue;
        return newArgs;
      };

      const renderEditControls = () => {
        let controls = '';
        for (const propName in args) {
          if (args.hasOwnProperty(propName)) {
            const propValue = args[propName];
            controls += `<div><label htmlFor="${propName}">${propName}:</label></div>`;

            if (typeof propValue === 'string') {
              controls += `<div><input type="text" id="${propName}" value="${propValue}" onChange={(e) => updateProps(propName, e.target.value)} /></div>`;
            } else if (typeof propValue === 'number') {
              controls += `<div><input type="number" id="${propName}" value="${propValue}" onChange={(e) => updateProps(propName, parseFloat(e.target.value))}/></div>`;
            } else if (typeof propValue === 'boolean') {
              controls += `<div><input type="checkbox" id="${propName}" checked="${propValue}" onChange={(e) => updateProps(propName, e.target.checked)} /></div>`;
            } else {
              controls += `<div><input type="text" id="${propName}" value="${propValue}" onChange={(e) => updateProps(propName, e.target.value)} /></div>`;
            }
          }
        }
        return controls;
      };

      const editControls = renderEditControls();

      story.component.wrapper.element.innerHTML += `<div class="prop-editor">${editControls}</div>`;
    }

    return story;
  },
};
