import { EditorView, EditorState } from '@prose/core';
import { createReusableEditor } from './ReusableEditor'; // Assuming you save the function in a separate file

/**
 * Creates a reusable editor component with customizable options.
 *
 * @param {string | HTMLElement} container - The DOM element to mount the editor into.  Can be a string (selector) or an HTMLElement.
 * @param {object} options - Configuration options for the editor.
 * @param {string} options.initialContent - The initial content of the editor.
 * @param {string} options.language - The language of the editor (e.g., 'markdown', 'gfm').
 * @param {object} options.extensions - An object containing ProseMirror extensions to apply.
 * @param {function} options.onChange - A callback function called when the editor content changes.
 * @returns {EditorView} - The ProseMirror EditorView instance.
 */
function createReusableEditor(container, options = {}) {
  const { initialContent, language = 'gfm', extensions = {}, onChange } = options;

  const editorView = new EditorView({
    container: container,
    state: EditorState.create({
      doc: {
        content: initialContent ? {
          type: 'block',
          content: [{
            type: 'text',
            content: initialContent
          }]
        } : null,
        meta: {}
      },
      parent: null,
    }),
    extensions: [
      // Add your desired extensions here
      // 'prose-mirror-link',
      // 'prose-mirror-code',
      // 'prose-mirror-tables',
    ],
    onChange: (state) => {
      if (onChange) {
        onChange(state.doc.content);
      }
    },
  });

  return editorView;
}

export { createReusableEditor };
