const datadog = require('datadog-api-client');

// Datadog API Key (replace with your actual API key)
datadog.apiKey = 'YOUR_DATADOG_API_KEY';

// Datadog App Key (replace with your actual App Key)
datadog.appKey = 'YOUR_DATADOG_APP_KEY';

// Initialize Datadog client
const client = datadog.Client({
  apiKey: datadog.apiKey,
  appKey: datadog.appKey,
  host: 'https://app.datadoghq.com', // Or your Datadog instance URL
  version: '2023-12-15' // Specify the API version
});


/**
 * Sends a metric to Datadog.
 * @param {string} metricName The name of the metric.
 * @param {number} value The value of the metric.
 * @param {string} tags An array of tags to associate with the metric.
 * @param {object} spanData (Optional) Span data to associate with the metric.
 * @returns {Promise<void>}
 */
async function sendMetric(metricName, value, tags, spanData = null) {
  try {
    const metric = {
      name: metricName,
      value: value,
      tags: tags,
      spanData: spanData
    };

    await client.metrics.send(metric);
    console.log(`Metric ${metricName} sent successfully.`);
  } catch (error) {
    console.error(`Error sending metric ${metricName}:`, error);
  }
}

/**
 * Sends a log event to Datadog.
 * @param {string} message The log message.
 * @param {string} severity The severity of the log (e.g., 'info', 'warn', 'error').
 * @param {object} tags An array of tags to associate with the log.
 * @returns {Promise<void>}
 */
async function sendLog(message, severity, tags = []) {
  try {
    const log = {
      message: message,
      severity: severity,
      tags: tags
    };

    await client.logs.send(log);
    console.log('Log sent successfully.');
  } catch (error) {
    console.error('Error sending log:', error);
  }
}

/**
 * Creates a dashboard in Datadog.
 * @param {string} dashboardTitle The title of the dashboard.
 * @param {Array<object>} widgets An array of widget objects. Each widget object should have a 'type' and 'options' property.
 * @returns {Promise<void>}
 */
async function createDashboard(dashboardTitle, widgets) {
  try {
    const dashboard = {
      title: dashboardTitle,
      widgets: widgets
    };

    await client.dashboards.create(dashboard);
    console.log(`Dashboard ${dashboardTitle} created successfully.`);
  } catch (error) {
    console.error(`Error creating dashboard ${dashboardTitle}:`, error);
  }
}


module.exports = {
  sendMetric,
  sendLog,
  createDashboard
};
