const fs = require('fs');
const sass = require('sass-js');

/**
 * Finds the dependencies of a Sass file.
 *
 * @param {string} filePath The path to the Sass file.
 * @returns {string[]} An array of dependency file paths.  Returns an empty array if no dependencies are found or if an error occurs.
 */
function getSassDependencies(filePath) {
  try {
    const fileContent = fs.readFileSync(filePath, 'utf8');
    const parsedSass = sass.parse(fileContent);

    if (parsedSass && parsedSass.dependencies) {
      return parsedSass.dependencies;
    } else {
      return []; // No dependencies found
    }
  } catch (error) {
