const fs = require('fs');

function getSassDependencies(filePath) {
  try {
    const fileContent = fs.readFileSync(filePath, 'utf8');
    const sassParser = require('sass-js').parse;
    const parsedSass = sassParser(fileContent);

    if (parsedSass && parsedSass.dependencies) {
      return parsedSass.dependencies;
    } else {
      return []; // Return an empty array if no dependencies are found
    }
  } catch (error) {
    console.error('Error:', error);
    return []; // Return an empty array in case of an error
  }
}

module.exports = getSassDependencies;
