```javascript
function babelTransform(code, options = {}) {
  const { presets = [], plugins = [], interactive } = options;

  const transforms = [];

  // Built-in transforms
  transforms.push(
    {
      name: 'parse',
      func: require('babel-parser').parse
    }
  );

  transforms.push(
    {
      name: 'traverse',
      func: require('babel-traverse').traverse
    }
  );

  transforms.push(
    {
      name: 'generate',
      func: require('babel-generator').generate
    }
  );

  // Preset transforms
  presets.forEach(preset => {
    const presetTransforms = require(`babel-preset-${preset}`).transforms;
    transforms.push(...presetTransforms);
  });

  // Plugin transforms
  plugins.forEach(plugin => {
    const pluginTransforms = require(`babel-plugin-${plugin}`).transforms;
    transforms.push(...pluginTransforms);
  });

  const ast = require('babel-parser').parse(code);

  const transformedAst = traverse(ast, {
    ...options,
    interactive: interactive
  });

  const code = generate(transformedAst, {
    ...options,
    sourceMap: false // Disable source maps for standalone
  });

  return code;

  function traverse(ast, context) {
    const traverseResult = {};

    function traverseNode(node) {
      if (node.type === 'Program') {
        node.body.forEach(statement => {
          if (statement.type === 'ExpressionStatement') {
            traverseNode(statement.expression);
          }
        });
      } else if (node.type === 'ExportDefaultDeclaration') {
        traverseNode(node.value);
      }
    }

    traverseNode(ast);
    return ast;
  }

  function generate(ast, context) {
    return require('babel-generator').generate(ast, {
      ...context,
      sourceMap: false // Disable source maps for standalone
    });
  }
}

// Example usage (for testing)
// const code = "const x = 1 + 2;";
// const transformedCode = babelTransform(code);
// console.log(transformedCode);
