import { Buffer } from 'buffer';
import { Varint } from '@protobuf-js/core';

/**
 * Creates a buffer containing n variable-length integers encoded using Protocol Buffers' varint format.
 *
 * @param {number} n The number of integers to encode.
 * @returns {Buffer} A buffer containing the encoded integers.
 * @throws {Error} If n is not a non-negative integer.
 */
function createVarintBuffer(n) {
  if (!Number.isInteger(n) || n < 0) {
    throw new Error("n must be a non-negative integer.");
  }

  const buffer = Buffer.alloc(0);

  for (let i = 0; i < n; i++) {
    const randomNumber = Math.floor(Math.random() * 256); // Generate a random integer between 0 and 255
    const varintBuffer = Varint.encode(randomNumber);
    buffer.concat(varintBuffer);
  }

  return buffer;
}
