/**
 * Exports traces to an OpenTelemetry Collector.
 *
 * @param {object} options Configuration options for the exporter.
 * @param {string} options.collectorEndpoint The address of the OpenTelemetry Collector endpoint.
 * @param {string} [options.serviceName='my-service'] The name of the service sending the traces.
 * @param {string} [options.traceId=null] The trace ID to use. If null, a new trace ID will be generated.
 * @param {string} [options.spanId=null] The span ID to use. If null, a new span ID will be generated.
 * @param {object} [options.context=null] The context to use for the trace.
 */
async function exportToCollector(options) {
  if (!options || !options.collectorEndpoint) {
    console.error("Collector endpoint is required.");
    return;
  }

  const { collectorEndpoint, serviceName = 'my-service', traceId = null, spanId = null, context = null } = options;

  const otelemetry = require('@opentelemetry/exporter-otlp');
  const otlpExporter = otelemetry.otlpExporter(
    {
      endpoint: collectorEndpoint,
      tls: {
        insecureSkipVerify: true, // Consider using proper TLS configuration in production
      },
    }
  );

  const trace = otelemetry.instrument({
    service: serviceName,
    traceId: traceId,
    spanId: spanId,
    context: context,
  });

  return otelemetry.export({
    exporter: otlpExporter,
    trace: trace,
  });
}


module.exports = exportToCollector;
