import { EditorState, Doc, Paragraph, Heading, List } from "@prosemirror/model";
import { createDoc } from "@prosemirror/doc";

function createExampleState() {
  const title = createDoc(
    new Heading(1, {
      children: "My Awesome Document",
    })
  );

  const body = createDoc(
    new Paragraph("This is the main body of the document.")
  );

  const listItems = [
    createDoc(new List({
      children: [
        createDoc(new Paragraph("Item 1")),
        createDoc(new Paragraph("Item 2")),
        createDoc(new Paragraph("Item 3")),
      ],
    })),
  ];

  const doc = createDoc(
    [title, body, ...listItems]
  );

  const schema = {
    nodes: {
      Heading: Heading.schema,
      Paragraph: Paragraph.schema,
      List: List.schema,
    },
  };

  return EditorState({
    doc,
    schema,
    selection: {
      from: { node: doc.begin, pos: 0 },
      to: { node: doc.begin, pos: 0 },
    },
  });
}

export default createExampleState;
