const EDITOR_COMMANDS = {
  bold: "bold",
  italic: "italic",
  strikethrough: "strikethrough",
  underline: "underline",
  highlight: "highlight",
};

const EDITOR_ACTION_MAP = {
  [EDITOR_COMMANDS.bold]: "setFormat",
  [EDITOR_COMMANDS.italic]: "setFormat",
  [EDITOR_COMMANDS.strikethrough]: "setFormat",
  [EDITOR_COMMANDS.underline]: "setFormat",
  [EDITOR_COMMANDS.highlight]: "setFormat",
};

const EDITOR_FORMAT_TYPES = {
  bold: "bold",
  italic: "italic",
  strikethrough: "strikethrough",
  underline: "underline",
  highlight: "highlight",
};


function useEditorCommands() {
  const dispatch = useDispatch();
  const store = useStore();

  const { editor } = useEditor();
  const focusedNode = useFocusedNode();
  const selection = useSelection();

  const handleFormatToggle = (format) => {
    const tr = editor.tr;
    const trSetFormat = tr.setFormat(focusedNode, EDITOR_FORMAT_TYPES[format], !focusedNode.trState.format[format]);
    tr.apply(editor);
  };

  const handleFormatClick = (format) => {
    const tr = editor.tr;
    const trSetFormat = tr.setFormat(focusedNode, EDITOR_FORMAT_TYPES[format], true);
    tr.apply(editor);
  };

  return {
    editor,
    focusedNode,
    selection,
    handleFormatToggle,
    handleFormatClick,
  };
}

export default useEditorCommands;
