```javascript
import TCP from 'tcp-kit';

/**
 * Establishes a TCP connection to a specified host and port, waiting for the port to open.
 *
 * @param {string} host The hostname or IP address of the server.
 * @param {number} port The port number to connect to.
 * @param {function} callback A callback function to be called when the connection is established or an error occurs.
 */
async function connectTcpWithWait(host, port, callback) {
  try {
    const client = new TCP.Client(host, port);

    client.on('connect', () => {
      console.log(`Connected to ${host}:${port}`);
      callback(null, client); // Pass the client object to the callback
    });

    client.on('error', (err) => {
      console.error(`Error connecting to ${host}:${port}: ${err.message}`);
      callback(err, null); // Pass the error to the callback
    });

    await new Promise((resolve, reject) => {
      client.on('open', () => {
        resolve();
      });
      client.on('error', (err) => {
        reject(err);
      });
    });

  } catch (error) {
    console.error(`An unexpected error occurred: ${error.message}`);
    callback(error, null);
  }
}

export default connectTcpWithWait;
```

