 */
function viteStorybook(options) {
  const { entry = 'src/index.ts', template = 'vue' } = options;

  return {
    name: 'vite-storybook',
    configResolved(config) {
      // Add the Storybook script to the Vite config.
      config.plugins.push({
        name: 'storybook-script',
        load() {
          return new Promise((resolve) => {
            const scriptContent = `
import { createStory } from '@storybook/js';
import { addDecorator } from '@storybook/addon-actions';
import { Story } from '@storybook/react';

addDecorator(action => console.log(action));

const story = createStory('src/index.tsx', () => {
  return <div style={{color: 'blue'}}>Hello Storybook!</div>;
});

export default story;
`;
            resolve(scriptContent);
          });
        },
      });
    },
    buildStart() {
      // Run Storybook in a separate process during build.
      const { exec } = require('child_process');

      exec(`yarn storybook --entry ${entry} --template ${template}`, (error, stdout, stderr) => {
        if (error) {
          console.error(`Error running Storybook: ${error}`);
          return;
        }
        if (stderr) {
          console.error(`Storybook stderr: ${stderr}`);
        }
        console.log(`Storybook started: ${stdout}`);
      });
    },
  };
}

export default viteStorybook;
```

