// 1. Create a Smithy client instance and set up a development environment.
import { Smithy } from '@smith.dev/smithy';

const smithy = new Smithy({
  apiKey: 'YOUR_API_KEY', // Replace with your actual API key
  baseUrl: 'YOUR_API_BASE_URL', // Replace with your API base URL
});

// 2. Fetch a list of all available APIs in a namespace.
async function listAPIs(namespace) {
  try {
    const response = await smithy.get(`/apis?namespace=${namespace}`);
    console.log('Available APIs:', response.data);
  } catch (error) {
    console.error('Error fetching APIs:', error);
  }
}

// 3. Create a new API.
async function createApi(namespace, name, description, httpMethod) {
  try {
    const api = {
      name: name,
      description: description,
      httpMethod: httpMethod,
    };
    const response = await smithy.post(`/apis?namespace=${namespace}`, api);
    console.log('API created:', response.data);
  } catch (error) {
    console.error('Error creating API:', error);
  }
}

// 4. Update an existing API.
async function updateApi(namespace, name, description, httpMethod) {
  try {
    const api = {
      name: name,
      description: description,
      httpMethod: httpMethod,
    };
    const response = await smithy.put(`/apis/${name}?namespace=${namespace}`, api);
    console.log('API updated:', response.data);
  } catch (error) {
    console.error('Error updating API:', error);
  }
}

// 5. Delete an existing API.
async function deleteApi(namespace, name) {
  try {
    const response = await smithy.delete(`/apis/${name}?namespace=${namespace}`);
    console.log('API deleted:', response.data);
  } catch (error) {
    console.error('Error deleting API:', error);
  }
}

// 6. Fetch a specific API.
async function getApi(namespace, name) {
  try {
    const response = await smithy.get(`/apis/${name}?namespace=${namespace}`);
    console.log('API details:', response.data);
  } catch (error) {
    console.error('Error fetching API:', error);
  }
}

// 7. Create a new operation for an API.
async function createOperation(namespace, apiName, name, description, requestSchema, responseSchema) {
  try {
    const operation = {
      name: name,
      description: description,
      requestSchema: requestSchema,
      responseSchema: responseSchema,
    };
    const response = await smithy.post(`/apis/${apiName}/operations?namespace=${namespace}`, operation);
    console.log('Operation created:', response.data);
  } catch (error) {
    console.error('Error creating operation:', error);
  }
}

// 8. Update an existing operation.
async function updateOperation(namespace, apiName, operationName, name, description, requestSchema, responseSchema) {
  try {
    const operation = {
      name: name,
      description: description,
      requestSchema: requestSchema,
      responseSchema: responseSchema,
    };
    const response = await smithy.put(`/apis/${apiName}/operations/${operationName}?namespace=${namespace}`, operation);
    console.log('Operation updated:', response.data);
  } catch (error) {
    console.error('Error updating operation:', error);
  }
}
