import {
  TracerProvider,
  SpanProcessor,
  Resource,
  BatchSpanProcessor,
  Span,
  Context,
  Attribute,
  SpanContext,
  SpanOptions,
  SpanStatus,
} from "@opentelemetry/api";
import {
  NodeHttpReceiver,
  NodeJaegerExporter,
} from "@opentelemetry/exporter-jaeger";
import {
  NodeConsoleExporter,
} from "@opentelemetry/exporter-console";

// Configure the resource
const resource = new Resource({
  attributes: [
    { key: "service.name", value: "my-microservice" },
    { key: "service.version", value: "1.0.0" },
  ],
});

// Create the span processor
const spanProcessor = new BatchSpanProcessor(
  new NodeJaegerExporter({
    endpoint: "localhost:16686",
  }),
  resource
);

// Create the tracer provider
const tracerProvider = new TracerProvider({
  resource,
  spanProcessor,
});

// Get the default tracer
const tracer = tracerProvider.getTracer("my-tracer");

// Example usage:
async function createAndStartSpan() {
  const span = tracer.startSpan("my-operation");

  span.setAttribute("http.method", "GET");
  span.setAttribute("http.url", "http://example.com");

  try {
    // Simulate some work
    await new Promise((resolve) => setTimeout(resolve, 100));
  } finally {
    span.end();
  }
}

// Start the tracer provider
tracerProvider.start();

// Example of starting a span
createAndStartSpan();

// To stop the tracer provider when done:
