import { fromEnvironment } from "@opentelemetry/api/log";
import {
  ConsoleExporter,
  LogSink,
  LogSinkOptions,
  LogProcessingPipeline,
} from "@opentelemetry/logs";

// Initialize OpenTelemetry logger
const logger = fromEnvironment();

// Configure log processing pipeline
const pipeline = new LogProcessingPipeline();

// Add log sink (e.g., to console)
const sinkOptions: LogSinkOptions = {};
const sink = new ConsoleExporter(sinkOptions);
pipeline.addSink(sink);

// Log messages at different severity levels
