// Create an OpenTelemetry logger instance
const otl = require("@opentelemetry/otlp").otl;

// Define a simple log processor
const logProcessor = {
  info: (message) => {
    console.log(`INFO: ${message}`);
  },
  warn: (message) => {
    console.warn(`WARNING: ${message}`);
  },
  error: (message) => {
    console.error(`ERROR: ${message}`);
  },
  critical: (message) => {
    console.error(`CRITICAL: ${message}`);
  },
};

// Create a log pipeline
const pipeline = {
  info: logProcessor.info,
  warn: logProcessor.warn,
  error: logProcessor.error,
  critical: logProcessor.critical,
};

// Create an OpenTelemetry logger
const logger = otl.createLogger({
  processor: pipeline,
});

// Log messages at different severity levels
logger.info("This is an informational message.");
logger.warn("This is a warning message.");
logger.error("This is an error message.");
logger.critical("This is a critical message.");

// Example of logging a message with context
const context = {
  userId: "12345",
  timestamp: new Date(),
};
logger.info("User logged in", { context });
