```javascript
/**
 * Minimalist Module Loader
 */
const moduleLoader = {};

/**
 * Registers a module.
 * @param {string} moduleName The name of the module.
 * @param {Function} moduleFunction The module function.  This function should return an object containing the module's exports.
 */
moduleLoader.register = function(moduleName, moduleFunction) {
  moduleLoader._modules[moduleName] = moduleFunction;
};

/**
 * Exports a module.
 * @param {string} moduleName The name of the module to export.
 * @returns {object} An object containing the module's exports.
 */
moduleLoader.export = function(moduleName) {
  if (moduleLoader._modules[moduleName]) {
    return moduleLoader._modules[moduleName]();
  }
  return {};
};

/**
 * Imports a module.
 * @param {string} moduleName The name of the module to import.
 * @returns {object} The module's exports.
 */
moduleLoader.import = function(moduleName) {
  if (moduleLoader._modules[moduleName]) {
    return moduleLoader._modules[moduleName]();
  }
  return {};
};


moduleLoader._modules = {};


// Example Usage (for testing)
if (typeof moduleLoader.register === 'function') {
  moduleLoader.register('myModule', function() {
    return {
      myFunction: function() {
        console.log('Hello from myModule!');
      }
    };
  });

  moduleLoader.register('anotherModule', function() {
    return {
      anotherFunction: function() {
        console.log('Hello from anotherModule!');
      }
    };
  });

  const myModuleExports = moduleLoader.import('myModule');
  if (myModuleExports) {
    myModuleExports.myFunction();
  }

  const anotherModuleExports = moduleLoader.import('anotherModule');
  if (anotherModuleExports) {
    anotherModuleExports.anotherFunction();
  }
}
