function parseHTMLtoJSON(htmlString) {
  const parser = require('rehype');
  const visiteurs = require('rehype-visitors');
  const generate = require('rehype-generate');

  const jsonOutput = [];

  const visitor = visiteurs.createVisitor({
    visitElement(node) {
      const data = {
        tagName: node.tagName,
        attributes: node.attributes || {},
        textContent: node.textContent || '',
        children: [],
      };

      if (node.children) {
        node.children.forEach(child => {
          this.visit(child);
          data.children.push(JSON.parse(JSON.stringify(child))); // Deep copy
        });
      }

      jsonOutput.push(data);
    },
  });

  rehype.parse(htmlString, { visitor: visitor }, (err, parsed) => {
    if (err) {
      console.error(err);
      return;
    }
    console.log(JSON.stringify(jsonOutput, null, 2));
  });
}

// Example usage:
// const html = '<div id="main" class="container"><p>Hello, world!</p><a href="https://example.com">Example</a></div>';
// parseHTMLtoJSON(html);

module.exports = parseHTMLtoJSON;
