```javascript
/**
 * MurmurHash for Node.js
 *
 * A fast and efficient non-cryptographic hash function.
 *
 * @module murmurhash
 */

const murmurhash32 = require('murmurhash-32');
const murmurhash128 = require('murmurhash-128');

/**
 * MurmurHash 32-bit implementation.
 * @param {string|Buffer} key The input key to hash.
 * @returns {number} The 32-bit hash value.
 */
function murmurHash32(key) {
  if (typeof key === 'string') {
    key = Buffer.from(key, 'utf8');
  }
  return murmurhash32(key);
}

/**
 * MurmurHash 128-bit implementation.
 * @param {string|Buffer} key The input key to hash.
 * @returns {number} The 128-bit hash value.
 */
function murmurHash128(key) {
  if (typeof key === 'string') {
    key = Buffer.from(key, 'utf8');
  }
  return murmurhash128(key);
}

/**
 * MurmurHash with custom range (e.g., 64-bit).
 * @param {string|Buffer} key The input key to hash.
 * @param {number} rangeSize The desired size of the hash value (e.g., 64).
 * @returns {number} The hash value within the specified range.
 */
function murmurHashCustomRange(key, rangeSize) {
  if (typeof key === 'string') {
    key = Buffer.from(key, 'utf8');
  }
  const hash = murmurhash128(key);
  return hash % rangeSize;
}

module.exports = {
  murmurHash32,
  murmurHash128,
  murmurHashCustomRange,
};
