```javascript
const http = require('http');
const basicAuth = require('basic-auth');
const digestAuth = require('digest-auth');

const users = {
  'user1': 'password123',
  'user2': 'securePass'
};

const protectedRoutes = [
  '/admin',
  '/secure'
];

function authenticateBasic(req, res) {
  const credentials = basicAuth(req);

  if (!credentials || !credentials.name || !credentials.pass) {
    return res.writeHead(401, { 'WWW-Authenticate': 'Basic' }).end('Authentication required');
  }

  const username = credentials.name;
  const password = credentials.pass;

  if (users[username] === password) {
    console.log('Basic authentication successful');
    return res.writeHead(200).end('Authentication successful');
  } else {
    return res.writeHead(401, { 'WWW-Authenticate': 'Basic' }).end('Authentication failed');
  }
}

function authenticateDigest(req, res) {
  const credentials = digestAuth(req);

  if (!credentials || !credentials.username || !credentials.password) {
    return res.writeHead(401, { 'WWW-Authenticate': 'Digest' }).end('Authentication required');
  }

  const username = credentials.username;
  const password = credentials.password;

  if (users[username] === password) {
    console.log('Digest authentication successful');
    return res.writeHead(200).end('Authentication successful');
  } else {
    return res.writeHead(401, { 'WWW-Authenticate': 'Digest' }).end('Authentication failed');
  }
}


const server = http.createServer((req, res) => {
  if (protectedRoutes.includes(req.url)) {
    if (req.headers.authorization === 'Basic ' || req.headers.authorization === 'Digest ') {
      if (req.headers.authorization.startsWith('Basic ')) {
        authenticateBasic(req, res);
      } else {
        authenticateDigest(req, res);
      }
    } else {
      res.writeHead(401, { 'WWW-Authenticate': 'Basic' });
      res.end('Authentication required');
      return;
    }
  } else {
    res.writeHead(200).end('Hello World!');
  }
});

const port = 3000;
server.listen(port, () => {
  console.log(`Server listening on port ${port}`);
});
```

