import { parse } from 'vue-cli-plugin-parser';

/**
 * Parses Vue component files and extracts information for documentation.
 *
 * @param {string} filePath - The path to the Vue component file.
 * @returns {Promise<object | null>} - A promise that resolves to an object containing
 *   component information, or null if parsing fails.
 */
async function parseVueComponent(filePath) {
  try {
    const parsed = await parse(filePath);

    if (!parsed) {
      console.warn(`Failed to parse ${filePath}`);
      return null;
    }

    const componentInfo = {
      name: parsed.name,
      template: parsed.template,
      script: parsed.script,
      styles: parsed.styles,
    };

    return componentInfo;
  } catch (error) {
    console.error(`Error parsing ${filePath}:`, error);
    return null;
  }
}

export default parseVueComponent;
