// React Native (Client)
import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Button, FlatList } from 'react-native';
import Pusher from 'pusher-js';

const pusher = new Pusher({
  appId: 'YOUR_APP_ID',
  key: 'YOUR_API_KEY',
  cluster: 'YOUR_CLUSTER'
});

const channel = pusher.subscribe('my-channel');

const App = () => {
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');

  useEffect(() => {
    channel.bind('my-event', (data) => {
      setMessages([...messages, data]);
    });
  }, [channel]);

  const sendMessage = () => {
    channel.trigger('my-event', { message: newMessage });
    setNewMessage('');
  };

  return (
    <View>
      <Text>Messages:</Text>
      <FlatList
        data={messages}
        keyExtractor={(item) => item.timestamp}
        renderItem={({ item }) => (
          <Text>{item.message}</Text>
        )}
      />
      <TextInput
        style={{ height: 40, borderColor: 'gray', borderWidth: 1 }}
        onChangeText={setNewMessage}
        value={newMessage}
        placeholder="Enter message"
      />
      <Button title="Send" onPress={sendMessage} />
    </View>
  );
};

export default App;

// Web Worker (Optional - for background tasks)
// (Example:  Processing messages, managing user sessions)
// This would be a separate file (e.g., worker.js)
// and imported into the React Native app.
// See Pusher documentation for details on using web workers.
