const showdown = require("showdown");
const converter = new showdown.Converter();

// Real-time collaboration features
const autoSavePlugin = Plugin({
  name: "autosave",
  configure({ editor }) {
    editor.schema.setAttr("autosave", true);
  },
});

const historyPlugin = Plugin({
  name: "history",
  configure({ editor }) {
    editor.plugins.add(editor.schema.history());
  },
});

const collaboratorPlugin = Plugin({
  name: "collaborator",
  configure({ editor }) {
    editor.plugins.add(editor.schema.collaborator());
  },
});


// ProseMirror editor instance
const editor = Editor({
  schema: {
    nodes: {
      text: {
        group: "block",
        content: "inline*",
      },
    },
  },
  plugins: [
    TextPlugin,
    MarkdownPlugin({ converter }),
    autoSavePlugin,
    historyPlugin,
    collaboratorPlugin,
  ],
});

export default editor;
```

