/**
 * @module browserstack-tunnel
 *
 * A Node.js module that creates a tunnel to a BrowserStack Local server.
 *
 * @requires browserstack-local-client
 */

const { BrowserStackLocalClient } = require('browserstack-local-client');

/**
 * Sets up a tunnel to a BrowserStack Local server.
 *
 * @param {string} browserstackLocalUrl The URL of the BrowserStack Local server.
 * @param {string} browserName The name of the browser to use (e.g., 'chrome', 'firefox').
 * @param {string} browserVersion The version of the browser to use (e.g., 'latest', '100.0').
 * @param {string} os The operating system of the BrowserStack Local machine (e.g., 'windows', 'mac', 'linux').
 * @returns {Promise<BrowserStackLocalClient>} A promise that resolves with a BrowserStackLocalClient instance.
 * @throws {Error} If the BrowserStackLocalClient cannot be created.
 */
async function setupTunnel(browserstackLocalUrl, browserName, browserVersion, os) {
  try {
    const client = new BrowserStackLocalClient({
      url: browserstackLocalUrl,
      browser: browserName,
      version: browserVersion,
      os: os,
    });
    return client;
  } catch (error) {
    throw new Error(`Failed to create BrowserStackLocalClient: ${error.message}`);
  }
}

module.exports = { setupTunnel };
