import { Widget } from '@tiptap/core';
import { Editor } from '@tiptap/editor';

export default function Link({ widget }) {
  return {
    name: 'link',
    render() {
      const { url, text, ...attrs } = this.props;

      if (!url || !text) {
        return null;
      }

      return (
        <span {...attrs}>
          {text}
          <tiptap-tooltip content={url} />
        </span>
      );
    },
    parse(node) {
      const { url, text, ...attrs } = node.data;
      return {
        type: 'link',
        url,
        text,
        ...attrs,
      };
    },
    commands: {
      toggleLink: (event) => {
        const { contentState } = event.detail;
        const { fold } = widget;

        if (contentState.node.type === 'text') {
          fold({
            insert: {
              type: 'link',
              url: prompt('Enter URL:'),
              text: contentState.node.text,
            },
          });
        }
      },
    },
  };
}
