// ace-editor.js
const AceEditor = require('ace-editor');

/**
 * Creates an Ace Editor instance.
 * @param {string} elementId The ID of the HTML element to contain the editor.
 * @param {object} options Editor configuration options.
 * @returns {AceEditor} The AceEditor instance.
 */
function createAceEditor(elementId, options = {}) {
  const element = document.getElementById(elementId);
  if (!element) {
    throw new Error(`Element with ID '${elementId}' not found.`);
  }

  const editor = new AceEditor(element, {
    ...options,
    mode: 'text', // Default mode
    theme: 'ace/theme/monokai' // Default theme
  });

  return editor;
}

module.exports = createAceEditor;
