import { parse } from 'json-stringify-to-json';
import { generateSourceMap } from 'json-pointer';

/**
 * Parses a JSON string and generates a source map for JSON Pointers.
 *
 * @param {string} jsonString The JSON string to parse.
 * @returns {{data: any, sourceMap: string}} An object containing the parsed JSON data and the source map.
 * @throws {Error} If the input is not a valid JSON string.
 */
function parseJsonWithSourceMap(jsonString) {
  try {
    const data = parse(jsonString);
    const sourceMap = generateSourceMap(data);
    return { data, sourceMap };
  } catch (error) {
    throw new Error(`Invalid JSON string: ${error.message}`);
  }
}

export default parseJsonWithSourceMap;
