  prompt: () => {
    // Define prompts for user input (e.g., project name, template path, dependencies)
    return {
      projectName: {
        type: 'input',
        message: 'Project Name:',
      },
      templatePath: {
        type: 'input',
        message: 'Path to Custom Template:',
      },
      dependencies: {
        type: 'input',
        message: 'Dependencies (comma-separated):',
      },
    };
  },
  ask: (options) => {
    // Access user input from prompts
    const projectName = options.projectName;
    const templatePath = options.templatePath;
    const dependencies = options.dependencies.split(',').map(dep => dep.trim()); // Split and trim dependencies

    // Create the project directory
    const projectDir = projectName;
    fs.mkdirSync(projectDir, { recursive: true }); //recursive: true creates parent directories if they don't exist

    // Copy the custom template
    fs.copyFileSync(templatePath, `${projectDir}/template.json`); // Assuming template is a JSON file

    // Install dependencies
    if (dependencies.length > 0) {
      exec(`npm install ${dependencies.join(' ')} --prefix ${projectDir}`, (err) => {
        if (err) {
          console.error('Error installing dependencies:', err);
        } else {
          console.log('Dependencies installed successfully.');
        }
      });
