import idna from 'idna-js';

function toAsciiCompatible(domain) {
  try {
    const labels = domain.split('.');
    const asciiLabels = labels.map(label => {
      const normalizedLabel = idna.toLabelunnable(label);
      const asciiLabel = idna.toASCII(normalizedLabel);
      return asciiLabel;
    });
    return asciiLabels.join('.');
  } catch (error) {
    console.error("Error during IDNA processing:", error);
    return domain; // Return original domain on error
  }
}

export default toAsciiCompatible;
```

