class ECMAScriptParser {

    /**
     * Parses ECMAScript code using acorn.
     * @param {string} code The ECMAScript code to parse.
     * @returns {object | null} The Abstract Syntax Tree (AST) if parsing is successful, null otherwise.
     */
    parseAcorn(code) {
        try {
            return acorn.parse(code, { ecmaVersion: 'latest' });
        } catch (error) {
            console.error("Acorn parsing error:", error);
            return null;
        }
    }

    /**
     * Parses ECMAScript code using Babel parser.
     * @param {string} code The ECMAScript code to parse.
     * @returns {object | null} The Abstract Syntax Tree (AST) if parsing is successful, null otherwise.
     */
    parseBabel(code) {
        try {
            return parse(code, {
                parseOptions: {
                    sourceType: 'script' // or 'module'
                }
            });
        } catch (error) {
            console.error("Babel parsing error:", error);
            return null;
        }
    }

    /**
     * Parses ECMAScript code using TypeScript parser.
     * @param {string} code The ECMAScript code to parse.
     * @returns {object | null} The Abstract Syntax Tree (AST) if parsing is successful, null otherwise.
     */
    parseTypescript(code) {
        try {
            const result = tsParse(code, {
                language: tsParse.Language.ESNext,
                module: tsParse.ModuleKind.CommonJS // or other module kind
            });
            return result;
        } catch (error) {
            console.error("TypeScript parsing error:", error);
            return null;
        }
    }
}


export default ECMAScriptParser;
```

```javascript
import * as ts from 'typescript';
import { estree } from 'estree';

/**
 * Parses TypeScript source code and converts it to ESTree format.
 * @param {string} tsSource - The TypeScript source code as a string.
 * @returns {ESTreeNode} The ESTree node representing the parsed TypeScript code.
 * @throws {Error} If the TypeScript source code is invalid.
 */
function typescriptToEstree(tsSource: string): ESTreeNode {
  try {
    const sourceFile = ts.createSourceFile(
      'temp.ts', // Temporary file name
      tsSource,
      ts.ScriptTarget.ESNext,
      true
    );

    const root = ts.parse(sourceFile);

    const estreeRoot = estree.createModule(
      ts.getModuleDeclaration(root),
      {
        file: 'temp.ts',
        source: tsSource,
      }
    );

    function visit(node: ts.Node, parent: ESTreeNode) {
      if (ts.isProgram(node)) {
        for (const element of node.elements) {
          visit(element, parent);
        }
      } else if (ts.isModuleDeclaration(node)) {
        // Already handled by estree.createModule
      } else if (ts.isClassDeclaration(node)) {
        const classNode = estree.createClass(
          node.name.text,
          node.commentText,
          node.decorators?.map(decorator => estree.createdecorators(decorator.expression)),
          node.modifiers?.map(modifier => estree.createkey(modifier.text)),
          node.functionDeclaration?.body?.statements.map(statement => visit(statement, estree.createBlockStatement())),
          node.body?.statements.map(statement => visit(statement, parent))
        );
        if (parent) {
          parent.children.push(classNode);
        }
      } else if (ts.isFunctionDeclaration(node)) {
        const functionNode = estree.createFunction(
          node.name.text,
          node.commentText,
          node.decorators?.map(decorator => estree.createdecorators(decorator.expression)),
          node.modifiers?.map(modifier => estree.createkey(modifier.text)),
          node.parameters?.map(param => estree.createVariableDeclaration(param.name.text, undefined)),
          node.body?.statements.map(statement => visit(statement, estree.createBlockStatement()))
        );
        if (parent) {
          parent.children.push(functionNode);
        }
      } else if (ts.isVariableDeclaration(node)) {
        const variableNode = estree.createVariableDeclaration(
          node.name.text,
          node.initializers?.map(initializer => visit(initializer, estree.createExpression(initializer.expression)))
        );
        if (parent) {
          parent.children.push(variableNode);
        }
      } else if (ts.isExpressionStatement(node)) {
        visit(node.expression, parent);
      } else if (ts.isBlock(node)) {
        const block = estree.createBlockStatement();
        for (const statement of node.statements) {
          visit(statement, block);
        }
        if (parent) {
          parent.children.push(block);
        }
      }
    }

    visit(root, estreeRoot);

    return estreeRoot;

  } catch (error) {
    console.error("Error parsing TypeScript:", error);
    throw error;
  }
}

export default typescriptToEstree;
```

