```javascript
const babel = require("babel-core");
const walk = require("babel-parser").walk;

function simplifyAccess(code) {
  const ast = babel.parse(code);

  function traverse(node) {
    if (node.type === "MemberExpression") {
      if (node.object.type === "Identifier" && node.property.type === "Identifier") {
        node.property = node.property.name;
        return;
      }
    } else if (node.type === "Property") {
      if (node.key.type === "Identifier" && node.value.type === "Identifier") {
        node.key = node.key.name;
        return;
      }
    }

    for (const key in node) {
      if (typeof node[key] === "object" && node[key] !== null) {
        if (Array.isArray(node[key])) {
          node[key].forEach(traverse);
        } else {
          traverse(node[key]);
        }
      }
    }
  }

  traverse(ast);

  return babel.stringify(ast, {
    sourceMap: { generate: true },
    compact: false,
  });
}

module.exports = simplifyAccess;
