```javascript
import * as esprima from 'esprima';
import * as estree from 'estree';

/**
 * Checks JavaScript code for a specified pattern using an AST-based approach.
 *
 * @param {string} code The JavaScript code to check.
 * @param {function} patternCheck Function that takes a node and returns true if the pattern is matched, false otherwise.
 * @returns {boolean} True if the pattern is found, false otherwise.
 */
function checkPattern(code, patternCheck) {
  try {
    const ast = esprima.parseScript(code); // or esprima.parseModule(code) for modules
    return traverseAst(ast, patternCheck);
  } catch (error) {
    console.error("Error parsing JavaScript code:", error);
    return false; // Or throw the error, depending on desired behavior
  }
}


/**
 * Traverses the AST and checks for the pattern.
 *
 * @param {estree.AST} ast The AST to traverse.
 * @param {function} patternCheck Function that takes a node and returns true if the pattern is matched, false otherwise.
 * @returns {boolean} True if the pattern is found, false otherwise.
 */
function traverseAst(ast, patternCheck) {
  if (ast) {
    if (patternCheck(ast)) {
      return true;
    }

    if (ast.type === 'Program') {
      if (ast.body) {
        ast.body.forEach(node => {
          if (traverseAst(node, patternCheck)) {
            return true;
          }
        });
      }
    }
  }
  return false;
}


// Example pattern check:  Check for a variable declaration
function variableDeclarationPattern(node) {
  return node.type === 'VariableDeclaration' && node.kind === 'const' || node.type === 'VariableDeclaration' && node.kind === 'let' || node.type === 'VariableDeclaration' && node.kind === 'var';
}


// Example usage:
const code1 = `
  const x = 10;
  let y = 20;
  var z = 30;
  function foo() {
    const a = 40;
  }
`;

const code2 = `
  console.log("Hello");
`;

console.log("Code 1 contains variable declaration:", checkPattern(code1, variableDeclarationPattern)); // true
console.log("Code 2 contains variable declaration:", checkPattern(code2, variableDeclarationPattern)); // false
