```javascript
function correctSpdxExpression(expression) {
  try {
    const spdx = require('spdx-expression');
    const parsed = spdx.parse(expression);

    if (!parsed) {
      throw new Error("Invalid SPDX expression: Could not parse.");
    }

    const corrected = spdx.correct(parsed);

    if (!corrected) {
      throw new Error("Invalid SPDX expression: Could not correct.");
    }

    return spdx.stringify(corrected);

  } catch (error) {
    throw new Error(`Invalid SPDX expression: ${error.message}`);
  }
}
