import * as wtf from 'wtf_js';

/**
 * Prints text with specified formatting using WebAssembly Text Format.
 *
 * @param {string} text The text to print.
 * @param {object} options An object containing formatting options.
 * @param {string} options.font The font to use (e.g., 'Courier New').
 * @param {string} options.color The text color (e.g., 'red', 'blue', '#00FF00').
 * @param {string} options.style The text style (e.g., 'bold', 'italic').
 * @param {string} options.alignment The text alignment (e.g., 'left', 'center', 'right').
 * @param {number} [options.width=80] The width of the output area.
 * @returns {string} The formatted text as a string.
 * @throws {Error} If required options are missing or invalid.
 */
function printFormattedText(text, options = {}) {
  const { font = 'Courier New', color = 'black', style = '', alignment = 'left', width = 80 } = options;

  if (typeof text !== 'string') {
    throw new Error('Text must be a string.');
  }

  if (typeof font !== 'string' || font.trim() === '') {
    throw new Error('Font must be a non-empty string.');
  }

  if (typeof color !== 'string') {
    throw new Error('Color must be a string.');
  }

  if (typeof style !== 'string') {
    throw new Error('Style must be a string.');
  }

  if (typeof alignment !== 'string') {
    throw new Error('Alignment must be a string.');
  }

  if (typeof width !== 'number' || width <= 0) {
    throw new Error('Width must be a positive number.');
  }

  const wtfOptions = {
    font: font,
    color: color,
    style: style,
    alignment: alignment,
    width: width,
  };

  try {
    const formattedText = wtf.format(text, wtfOptions);
    return formattedText;
  } catch (error) {
    console.error("Error during formatting:", error);
    throw new Error("Failed to format text.");
  }
}

export default printFormattedText;
