 *
 * @param {RegExp} esNextRegex The ESNext regular expression to compile.
 * @returns {RegExp} An ES5 compatible regular expression.
 * @throws {Error} If the input is not a RegExp object.
 */
function compileEsNextRegexToEs5(esNextRegex) {
