import { ErrorJS } from 'error-js';

class EnhancedError extends Error {
  constructor(message, name, stack) {
    super(message);
    this.name = name;
    this.stack = stack;
    ErrorJS.create(this);
  }
}

function enhanceError(error) {
  const enhancedError = new EnhancedError(
    error.message,
    error.name,
    error.stack
  );
  console.error(enhancedError);
  return enhancedError;
}

// Example usage:
try {
  function divide(a, b) {
    if (b === 0) {
      throw new Error("Division by zero");
    }
    return a / b;
  }

  divide(10, 0);
} catch (error) {
  const enhanced = enhanceError(error);
  console.log("Enhanced Error Details:");
  console.log("Name:", enhanced.name);
  console.log("Message:", enhanced.message);
  console.log("Stack Trace:", enhanced.stack);
}
