```javascript
/**
 * ASN.1 BER Parser and Serializer Module
 */
const asn1ber = {

  /**
   * Parses ASN.1 BER encoded data.
   * @param {Buffer} berData The BER encoded data as a Buffer.
   * @returns {object|null} The parsed ASN.1 data as an object, or null if parsing fails.
   * @throws {Error} If the input is not a Buffer.
   */
  parse: (berData) => {
    if (!(berData instanceof Buffer)) {
      throw new Error("Input must be a Buffer");
    }

    try {
      const decoder = require('asn1-js').createDecoder('BER');
      const parsedData = decoder.decode(berData);
      return parsedData;
    } catch (error) {
      console.error("Error parsing ASN.1 BER data:", error);
      return null;
    }
  },

  /**
   * Serializes ASN.1 data to BER format.
   * @param {object} asnData The ASN.1 data as an object.
   * @returns {Buffer} The BER encoded data as a Buffer.
   * @throws {Error} If the input is not an object.
   */
  serialize: (asnData) => {
    if (typeof asnData !== 'object' || asnData === null) {
      throw new Error("Input must be an object");
    }

    try {
      const encoder = require('asn1-js').createEncoder('BER');
      const berData = encoder.encode(asnData);
      return berData;
    } catch (error) {
      console.error("Error serializing ASN.1 data:", error);
      return null;
    }
  },

  /**
   * Example usage (can be removed for production)
   */
  example: () => {
    // Example ASN.1 data (replace with your actual data)
    const exampleData = {
      version: 2,
      messageId: 123,
      payload: "Hello, ASN.1!"
    };

    // Serialize the data
    const berEncodedData = asn1ber.serialize(exampleData);

    if (berEncodedData) {
      console.log("Serialized BER data:", berEncodedData.toString('hex'));
    }

    // Parse the data
    const parsedData = asn1ber.parse(berEncodedData);

    if (parsedData) {
      console.log("Parsed data:", parsedData);
    }
  }
};

module.exports = asn1ber;
```

