const lexer = require('@istanbul/lexer');
const visitor = {
  ExportDefaultDeclaration(node) {
   const name = node.declaration.name;
   return { type: 'ExportNamed', name };
  },
  ExportNamedDeclaration(node) {
   const name = node.name;
   return { type: 'ExportNamed', name };
  }
