response_prompt:
```javascript
const lexer = require('@istanbul/lexer');

function getExports(module) {
  const ast = lexer.parse(module);

  const visitor = {
    ExportDefaultDeclaration(node) {
      return { type: 'ExportDefault', name: node.declaration.name };
    },
    ExportNamedDeclaration(node) {
      return { type: 'ExportNamed', name: node.name.name };
    },
  };

  const exports = {};
  visitor.visit(ast).forEach(node => {
    if (node.type === 'ExportDefault') {
      exports.default = node.name;
    } else if (node.type === 'ExportNamed') {
      exports[node.name.name] = node.name;
    }
  });

  return exports;
}

module.exports = getExports;
```

```javascript
function analyzeCoverage(coverageFiles) {
  const coverageStats = {};

  for (const file of coverageFiles) {
    try {
      const stats = require('v8-coverage-stats').parse(file);

      let totalLines = 0;
      let coveredLines = 0;
      let missedLines = 0;

      for (const line of stats.lines) {
        totalLines++;
        if (line.covered) {
          coveredLines++;
        } else {
          missedLines++;
        }
      }

      const coveragePercentage = (coveredLines / totalLines) * 100;

      coverageStats[file] = {
        totalLines: totalLines,
        coveredLines: coveredLines,
        missedLines: missedLines,
        coveragePercentage: coveragePercentage
      };
    } catch (error) {
      console.error(`Error processing file ${file}: ${error.message}`);
      coverageStats[file] = {
        error: error.message
      };
    }
  }

  return coverageStats;
}

// Example Usage (replace with your coverage file paths)
const coverageFiles = ['coverage/index.1.json', 'coverage/my_module.1.json'];
const stats = analyzeCoverage(coverageFiles);

console.log(JSON.stringify(stats, null, 2));
