 * @param {string} options.region - The default AWS region.
 * @param {string} options.profile - The default AWS profile.
 * @returns {object} - The configured AWS credential provider.
 */
export function configureAwsCredentialsProvider(options = {}) {
  const { region = 'us-east-1', profile = 'default' } = options;

  const credentials = new AWSProvider({
    region: region,
    profile: profile,
