```javascript
const fs = require('fs');
const { generateKeyPair } = require('keytool');

async function generateSelfSignedCertificate(algorithm, keySize, commonName, outputDir) {
  try {
    const keyPair = await generateKeyPair(algorithm, keySize);

    const privateKey = keyPair.getPrivateKey();
    const publicKey = keyPair.getPublicKey();

    const certificate = {
      subject: {
        commonName: commonName,
      },
      key: publicKey,
      signature: privateKey.toBuffer(), // Use private key to sign the certificate
    };

    const certificatePEM = fs.readFileSync(
      `${outputDir}/certificate.pem`,
      'utf8'
    );
    fs.writeFileSync(
      `${outputDir}/certificate.pem`,
      certificatePEM,
      'utf8'
    );

    const privateKeyPEM = fs.readFileSync(
      `${outputDir}/private.key`,
      'utf8'
    );
    fs.writeFileSync(
      `${outputDir}/private.key`,
      privateKeyPEM,
      'utf8'
    );

    const publicKeyPEM = fs.readFileSync(
      `${outputDir}/public.key`,
      'utf8'
    );
    fs.writeFileSync(
      `${outputDir}/public.key`,
      publicKeyPEM,
      'utf8'
    );

    console.log('Self-signed certificate and keys generated successfully.');
    console.log(`Certificate saved to: ${outputDir}/certificate.pem`);
    console.log(`Private key saved to: ${outputDir}/private.key`);
    console.log(`Public key saved to: ${outputDir}/public.key`);

  } catch (error) {
    console.error('Error generating certificate and keys:', error);
  }
}

// Example usage:
const algorithm = 'rsa';
const keySize = 2048;
const commonName = 'localhost';
const outputDir = 'certs';

generateSelfSignedCertificate(algorithm, keySize, commonName, outputDir);
