```javascript
const { SSOLogin } = require('node-sso-login');
const AWS = require('aws-sdk');
const fs = require('fs');

/**
 * Creates an AWS credential provider that reads a resolved SSO login token file
 * and returns temporary AWS credentials.
 *
 * @param {string} tokenFilePath - The path to the resolved SSO login token file.
 * @param {string} region - The AWS region to use.
 * @returns {function} - A function that returns AWS credentials.
 * @throws {Error} - If the token file does not exist or is invalid.
 */
function createSSOCredentialProvider(tokenFilePath, region) {
  return async () => {
    try {
      // Read the SSO login token file
      const tokenContent = fs.readFileSync(tokenFilePath, 'utf-8');

      // Validate the token content (basic check - can be enhanced)
      if (!tokenContent) {
        throw new Error('SSO token file is empty.');
      }

      // Initialize SSOLogin
      const ssoLogin = new SSOLogin();

      // Authenticate using the token
      const authInfo = await ssoLogin.authenticate(tokenContent, region);

      // Configure AWS SDK with the credentials
      AWS.config.update({
        region: region,
        credentials: authInfo,
      });

      // Return the AWS credentials
      return AWS.config.credentials;

    } catch (error) {
      console.error('Error creating SSO credential provider:', error);
      throw error; // Re-throw the error to be handled by the caller
    }
  };
}

module.exports = createSSOCredentialProvider;
```

