import { isCircular } from 'circular-dependency-checker';

/**
 * Middleware function to detect recursion in AWS SDK clients.
 *
 * @param {object} next The next middleware function.
 * @returns {function} The middleware function.
 */
function detectRecursionMiddleware(next) {
  return async (context, req, res, next) => {
    try {
      // Check for circular references in the request object.
      if (isCircular(req.request)) {
        throw new Error('Recursion detected in request object. Potential infinite loop.');
      }

      await next();
    } catch (err) {
      console.error('Error in detectRecursionMiddleware:', err);
      res.status(500).send('Internal Server Error');
    }
  };
}

export default detectRecursionMiddleware;
