```javascript
const merge = require('postcss-merge');
const fs = require('fs');

/**
 * Merges CSS rules from multiple files into a single file, removing duplicates and optimizing for production.
 *
 * @param {string[]} inputFiles An array of paths to the CSS files to merge.
 * @param {string} outputFile The path to the output CSS file.
 */
function mergeCSSFiles(inputFiles, outputFile) {
  const cssRules = [];

  for (const inputFile of inputFiles) {
    try {
      const css = fs.readFileSync(inputFile, 'utf8');
      const parsed = require('postcss').parse(css);
      const rules = parsed.root.nodes.filter(node => node.type === 'Rule');

      rules.forEach(rule => {
        cssRules.push(rule.toSource());
      });
    } catch (error) {
      console.error(`Error reading or parsing file ${inputFile}:`, error);
      return; // Exit if any file fails to load/parse
    }
  }

  const mergedCSS = merge(cssRules);

  fs.writeFileSync(outputFile, mergedCSS.toString(), 'utf8');
  console.log(`Successfully merged CSS files into ${outputFile}`);
}


// Example Usage (replace with your actual file paths)
const inputFiles = ['style1.css', 'style2.css', 'style3.css'];
const outputFile = 'merged.css';

mergeCSSFiles(inputFiles, outputFile);
```



The code reads CSS files, parses them using `postcss`, extracts the CSS rules, merges them using `postcss-merge`, and writes the merged CSS to an output file.  Error handling is included to catch issues with file reading or parsing.  The `require('postcss').parse` is used to parse the CSS string into a PostCSS root object. The `filter` method is used to extract only the CSS rules from the parsed CSS. The `toSource()` method converts each rule to its CSS string representation.  The `merge` function from `postcss-merge` combines these CSS strings, removing duplicates. Finally, the merged CSS is written to the specified output file.  The example usage shows how to call the function with an array of input files and an output file name.

```javascript
function mergeCSSFiles(inputFiles, outputFile) {
  const fs = require('fs');
  const postcss = require('postcss');
  const postcssMerge = require('postcss-merge');

  if (!Array.isArray(inputFiles) || inputFiles.length === 0) {
    console.error("Error: inputFiles must be a non-empty array.");
    return;
  }

  if (typeof outputFile !== 'string' || outputFile.trim() === '') {
    console.error("Error: outputFile must be a valid string.");
    return;
  }

  fs.readFile(outputFile, 'utf8', (err, existingCSS) => {
    if (err) {
      if (err.code === 'ENOENT') {
        // File doesn't exist, create it
        fs.writeFile(outputFile, '', (err2) => {
          if (err2) {
            console.error("Error creating output file:", err2);
            return;
          }
          const postcssOptions = {};
          const pipeline = postcss([
            postcssMerge({
              mergeConflict: 'keep-first', // Or 'keep-last' or 'merge'
            }),
          ]).process(existingCSS, postcssOptions);
          fs.writeFile(outputFile, pipeline.css, (err3) => {
            if (err3) {
              console.error("Error writing to output file:", err3);
            } else {
              console.log(`CSS files merged and saved to ${outputFile}`);
            }
          });
        });
      } else {
        console.error("Error reading output file:", err);
        return;
      }
    } else {
      const postcssOptions = {};
      const pipeline = postcss([
        postcssMerge({
          mergeConflict: 'keep-first', // Or 'keep-last' or 'merge'
        }),
      ]).process(existingCSS, postcssOptions);
      fs.writeFile(outputFile, pipeline.css, (err3) => {
        if (err3) {
          console.error("Error writing to output file:", err3);
        } else {
          console.log(`CSS files merged and saved to ${outputFile}`);
        }
      });
    }
  });
}


// Example Usage (replace with your actual file paths)
const inputFiles = ['file1.css', 'file2.css', 'file3.css'];
const outputFile = 'merged.css';

mergeCSSFiles(inputFiles, outputFile);
```

