```javascript
function transformCssToShorthand(cssFilePath, outputFilePath) {
  const fs = require('fs');
  const postcss = require('postcss');

  fs.readFile(cssFilePath, 'utf8', (err, cssContent) => {
    if (err) {
      console.error('Error reading CSS file:', err);
      return;
    }

    const postcssOptions = {
      plugins: [
        require('postcss-shorthand')({
          longhand: true,
        }),
      ],
    };

    postcss.parse(cssContent, postcssOptions)
      .then((result) => {
        const transformedCss = result.css;
        fs.writeFile(outputFilePath, transformedCss, 'utf8', (err) => {
          if (err) {
            console.error('Error writing transformed CSS file:', err);
          } else {
            console.log('CSS transformed to shorthand and saved to:', outputFilePath);
          }
        });
      })
      .catch((error) => {
        console.error('Error processing CSS:', error);
      });
  });
}

// Example usage:
// transformCssToShorthand('input.css', 'output.css');
