```javascript
import { unist } from 'unist-util';

/**
 * Serializes a node, position, or point as a human-readable location string.
 *
 * @param {object|array|string} data The data to serialize.  Can be a node, position, or point.
 * @returns {string} A human-readable location string.
 */
function serializeLocation(data) {
  if (!data) {
    return '';
  }

  if (typeof data === 'object' && data !== null) {
    if (data.type === 'node') {
      return unist(data).toString();
    } else if (data.type === 'position') {
      return `Position: ${data.x}, ${data.y}`;
    } else if (data.type === 'point') {
      return `Point: ${data.x}, ${data.y}`;
    }
  }

  return String(data);
}

export default serializeLocation;
