```javascript
const fs = require('fs');
const { Readable } = require('stream');
const jsonStream = require('json2stream');

/**
 * Creates a JSON streaming parser for Node.js.
 *
 * @param {Readable} stream - A Readable stream containing JSON data.
 * @param {function} onComplete - Callback function called when the stream is finished.
 * @param {function} onParse - Callback function called for each parsed JSON element.
 * @param {function} onError - Callback function called if an error occurs.
 */
function jsonStreamParser(stream, onComplete, onParse, onError) {
  stream.on('data', (chunk) => {
    jsonStream.parse(chunk, {
      objectMode: true,
    }, (err, result) => {
      if (err) {
        onError(err);
        return;
      }
      onParse(result);
    });
  });

  stream.on('end', () => {
    onComplete();
  });

  stream.on('error', (err) => {
    onError(err);
  });
}

module.exports = jsonStreamParser;
```

