import crc32 from 'pure-js-crc32';

/**
 * Calculates the CRC-32 checksum of a given string.
 *
 * @param {string} data The string to calculate the checksum for.
 * @returns {string} The CRC-32 checksum as a hexadecimal string.
 * @throws {Error} If the input is not a string.
 */
function calculateCrc32Checksum(data) {
  if (typeof data !== 'string') {
    throw new Error('Input must be a string.');
  }

  const checksum = crc32(data);
  return checksum.toString(16).toUpperCase();
}

export default calculateCrc32Checksum;
