```javascript
import { Duplex, PassThrough } from 'streams3';

/**
 * Creates a duplexer-like stream using Streams3.
 *
 * @param {ReadableStream} readableStream The readable stream to be paired.
 * @param {WritableStream} writableStream The writable stream to be paired.
 * @returns {Duplex} A duplex stream that forwards data between the readable and writable streams.
 * @throws {TypeError} If either input is not a ReadableStream or WritableStream.
 */
function createDuplexer(readableStream, writableStream) {
  if (!(readableStream instanceof ReadableStream)) {
    throw new TypeError("readableStream must be a ReadableStream");
  }
  if (!(writableStream instanceof WritableStream)) {
    throw new TypeError("writableStream must be a WritableStream");
  }

  const duplexStream = new Duplex();

  duplexStream.readable = readableStream;
  duplexStream.writable = writableStream;

  return duplexStream;
}

export { createDuplexer };
```

