      sourceType: 'CSS'
    });
    const transformedCss = estring.stringify(ast, {
      wrap: true
    });
    return transformedCss;
  } catch (error) {
    console.error("Error parsing or stringifying CSS:", error);
    return null; // Or handle the error as appropriate
  }
}

module.exports = cssTransform;
