import * as hastUtil from 'hast-util';
import * as acorn from 'acorn';
import * as babel from 'babel-core';

/**
 * Transforms a HAST to a Babel AST, supporting JSX.
 *
 * @param {object} hast The HAST to transform.
 * @returns {object} The Babel AST.
 */
function hastToBabel(hast) {
  const babelAst = {
    type: 'Program',
    children: [],
  };

  function traverse(node) {
    if (node.type === 'JSXElement') {
      const jsx = hastUtil.visitJSXElement(node, {
        babelAst,
      });
      babelAst.children.push(jsx);
    } else if (node.type === 'JSXFragment') {
      const fragment = hastUtil.visitJSXFragment(node, {
        babelAst,
      });
      babelAst.children.push(fragment);
    } else if (node.type === 'JSXText') {
      const text = hastUtil.visitJSXText(node, {
        babelAst,
      });
      babelAst.children.push(text);
    } else {
      // Handle other HAST node types as needed.  For simplicity, we'll just ignore them.
      // You might need to add more specific handling for attributes, etc.
      console.warn(`Unhandled HAST node type: ${node.type}`);
    }
  }

  traverse(hast);

  try {
    const result = babel.parse(babelAst);
    return result.ast;
  } catch (error) {
    console.error("Babel parsing error:", error);
    return babelAst; // Return the potentially incomplete AST in case of parsing errors.
  }
}


export default hastToBabel;
```

```javascript
import * as hastUtil from 'hast-util';

/**
 * Transforms a HAST (HTML Abstract Syntax Tree) to a Babel AST (JavaScript Syntax Tree)
 * supporting JSX.
 *
 * @param {object} hastRoot The root of the HAST.
 * @returns {object} The root of the Babel AST.
 */
function hastToBabel(hastRoot) {
  if (!hastRoot) {
    return null;
  }

  const babelRoot = {
    type: 'Program',
    children: [],
  };

  function traverse(node, parent) {
    if (!node) {
      return;
    }

    const babelNode = {
      type: node.type,
      children: [],
    };

    if (node.type === 'JSXElement') {
      const attributes = {};
      const attributesArray = node.attributes.map(attr => ({
        type: attr.type,
        value: attr.value,
      }));
      attributes.attributes = attributesArray;

      const children = node.children.map(child => {
        if (child.type === 'JSXText') {
          return {
            type: 'StringLiteral',
            value: child.value,
          };
        } else if (child.type === 'JSXElement') {
          return traverse(child, babelNode);
        } else if (child.type === 'JSXFragment') {
          return traverse(child, babelNode);
        }
        // Handle other JSX node types as needed
        else {
          return null; // Or handle differently
        }
      }).filter(child => child !== null);

      babelNode.JSXElement = {
        attributes: attributes,
        children: children,
      };
      parent.children.push(babelNode);
    } else if (node.type === 'Text') {
      babelNode.type = 'StringLiteral';
      babelNode.value = node.value;
      parent.children.push(babelNode);
    } else if (node.type === 'Comment') {
      babelNode.type = 'Program';
      babelNode.children = [{
        type: 'Комментарий',
        value: node.value
      }];
      parent.children.push(babelNode);
    } else {
      // Handle other HAST node types as needed
      babelNode.type = node.type;
      babelNode.value = node.value;
      parent.children.push(babelNode);
    }
  }

  traverse(hastRoot, babelRoot);
  return babelRoot;
}

export default hastToBabel;
```

