    await semanticTracer.endSpan('doSomething');
  } catch (error) {
    await semanticTracer.endSpan('doSomething', { error: error.message });
    console.error('doSomething failed:', error);
  }
}

doSomething();


// Example usage: Metrics
semanticMetrics.recordCounter('my-counter', 10);
semanticMetrics.recordGauge('my-gauge', 50);
semanticMetrics.recordHistogram('my-histogram', 100);

