import { createClient } from 'github-auth-api';

/**
 * Obtains a GitHub access token using the GitHub OAuth API.
 *
 * @param {string} clientId - Your GitHub OAuth client ID.
 * @param {string} clientSecret - Your GitHub OAuth client secret.
 * @param {string} redirectUri - The redirect URI configured in your GitHub app.
 * @param {string} scopes - A space-separated string of scopes requested (e.g., 'repo', 'user').
 * @returns {Promise<string | null>} - A promise that resolves with the access token or null on error.
 */
async function getGitHubAccessToken(clientId, clientSecret, redirectUri, scopes) {
  try {
    const auth = createClient({
      clientId: clientId,
      clientSecret: clientSecret,
      redirectUri: redirectUri,
      scopes: scopes,
    });

    const token = await auth.getAccessToken();
    return token;
  } catch (error) {
    console.error('Error obtaining access token:', error);
    return null;
  }
}

export default getGitHubAccessToken;
