```javascript
// build.js
import * as fs from 'fs/promises';
import * as path from 'path';
import { readFileSync } from 'readFileSync';
import { exec } from 'child_process';
import { glob } from 'glob';
import { minify } from 'terser'; // Example plugin - can be replaced with other bundlers/optimizations

/**
 * Builds and bundles ES modules.
 * @param {string} entry - The entry point module.
 * @param {string} output - The output directory.
 * @param {object} options - Build options.
 */
async function build(entry, output, options = {}) {
  try {
    // 1. Read modules
    const modules = await glob(
      '**/*.{js,jsx,ts,tsx}',
      { cwd: process.cwd() }
    );

    // 2. Process modules
    const processedModules = [];
    for (const module of modules) {
      try {
        const moduleContent = await fs.readFile(module, 'utf-8');
        // Apply plugins/transformations here.  Example:
        // const transformedContent = await transformModule(moduleContent);
        const processedModule = {
          module: module,
          content: moduleContent,
        };
        processedModules.push(processedModule);
      } catch (err) {
        console.error(`Error processing module ${module}:`, err);
      }
    }

    // 3. Bundle modules (using a simple concatenation for now)
    const bundledContent = processedModules.map(m => m.content).join('\n\n');

    // 4. Minify (example using terser)
    if (options.minify) {
      try {
        const minifiedContent = await minify(bundledContent);
        console.log('Minified successfully.');
        bundledContent = minifiedContent.code;
      } catch (err) {
        console.error('Minification failed:', err);
      }
    }

    // 5. Write output
    await fs.writeFile(path.join(output, 'bundle.js'), bundledContent, 'utf-8');
    console.log(`Successfully built bundle.js in ${output}`);

  } catch (err) {
    console.error('Build failed:', err);
  }
}

/**
 * CLI interface.
 */
async function main() {
  const args = process.argv.slice(2);

  if (args.length < 2) {
    console.error('Usage: build <entry> <output> [--minify]');
    process.exit(1);
  }

  const entry = args[0];
  const output = args[1];
  const minify = args.includes('--minify');

  await build(entry, output, { minify });
}

main();

export { build };
```

