/**
 * Parses a Yarn lockfile and stringifies it back.
 * @param {string} lockfileContent The content of the Yarn lockfile.
 * @returns {Promise<string>} The stringified Yarn lockfile content.
 * @throws {Error} If the lockfile content is invalid.
 */
async function processYarnLockfile(lockfileContent) {
  try {
    const parsedLockfile = parseYarnLockfile(lockfileContent);
    const stringifiedLockfile = stringifyYarnLockfile(parsedLockfile);
    return stringifiedLockfile;
  } catch (error) {
    console.error("Error processing Yarn lockfile:", error);
    throw error; // Re-throw the error to be handled by the caller
  }
}


