```javascript
/**
 * OpenTelemetry API for Node.js
 *
 * This API provides a simplified interface for integrating OpenTelemetry into Node.js applications.
 * It allows for the collection of traces, metrics, and logs from various sources.
 */

class OpenTelemetry {
  /**
   * Initializes the OpenTelemetry SDK.
   * @param {object} config - Configuration object for OpenTelemetry.
   */
  constructor(config = {}) {
    this.tracer = null;
    this.metrics = null;
    this.exporter = null;
    this.vendor = config.vendor || 'open-telemetry'; // Default vendor
    this.serviceName = config.serviceName || 'node-app'; // Default service name

    try {
      this.tracer = this.initializeTracer(config);
      this.metrics = this.initializeMetrics(config);
      this.exporter = this.initializeExporter(config);
    } catch (error) {
      console.error("OpenTelemetry initialization failed:", error);
      throw error; // Re-throw to signal initialization failure
    }
  }

  /**
   * Initializes the OpenTelemetry tracer.
   * @param {object} config - Configuration object for the tracer.
   * @returns {Promise<object>} - The initialized tracer.
   */
  async initializeTracer(config) {
    const { otlp } = config;
    if (!otlp) {
      throw new Error("OTLP configuration is required for the tracer.");
    }

    const { pipeline } = await this.createOTLPProvider(otlp);
    return pipeline;
  }

  /**
   * Initializes the OpenTelemetry metrics.
   * @param {object} config - Configuration object for the metrics.
   * @returns {object} - The initialized metrics object.
   */
  async initializeMetrics(config) {
    const { metrics } = config;
    if (!metrics) {
      throw new Error("Metrics configuration is required.");
    }
    return this.metricsProvider(metrics);
  }

  /**
   * Initializes the OpenTelemetry exporter.
   * @param {object} config - Configuration object for the exporter.
   * @returns {object} - The initialized exporter.
   */
  async initializeExporter(config) {
    const { exporter } = config;
    if (!exporter) {
      throw new Error("Exporter configuration is required.");
    }
    return this.createExporter(exporter);
  }

  /**
   * Creates an OTLP provider.
   * @param {object} otlpConfig - OTLP configuration.
   * @returns {Promise<object>} - The OTLP provider.
   */
  async createOTLPProvider(otlpConfig) {
    const { endpoint, protocol = 'grpc' } = otlpConfig;

    const { Jaeger } = await import('@opentelemetry/sdk-js/build/providers/jaeger');
    const pipeline = new Jaeger({
      endpoint: endpoint,
      protocol: protocol,
      serviceName: this.serviceName,
    });
    return { pipeline };
  }

  /**
   * Creates a metrics provider.
   * @param {object} metricsConfig - Metrics configuration.
   * @returns {object} - The metrics provider.
   */
  metricsProvider(metricsConfig) {
    const { api } = import('@opentelemetry/sdk-js/build/metrics');
    return api;
  }

  /**
   * Creates an exporter.
   * @param {object} exporterConfig - Exporter configuration.
   * @returns {object} - The exporter.
   */
  createExporter(exporterConfig) {
    const { attributes } = import('@opentelemetry/sdk-js/build/exporters');
    return attributes;
  }


  /**
   * Starts a new trace.
   * @param {string} traceName - The name of the trace.
   * @returns {Promise<object>} - The trace object.
   */
  async startTrace(traceName) {
    if (!this.tracer) {
      throw new Error("OpenTelemetry not initialized.");
    }
    return this.tracer.start(traceName);
  }

  /**
   * Records a span.
   * @param {object} span - The span object.
   */
  async recordSpan(span) {
    if (!this.tracer) {
      throw new Error("OpenTelemetry not initialized.");
    }
    this.tracer.record(span);
  }

  /**
   * Records a metric.
   * @param {object} metric - The metric object.
   */
  async recordMetric(metric) {
    if (!this.metrics) {
      throw new Error("OpenTelemetry metrics not initialized.");
    }
    this.metrics.record(metric);
  }

  /**
   * Records a log.
   * @param {string} message - The log message.
   * @param {string} level - The log level (e.g., 'info', 'warn', 'error').
   */
  async recordLog(message, level = 'info') {
    if (!this.metrics) {
      throw new Error("OpenTelemetry metrics not initialized.");
    }
    this.metrics.log(message, level);
  }

  /**
   * Stops the current trace.
   */
  async stopTrace() {
    if (!this.tracer) {
      throw new Error("OpenTelemetry not initialized.");
    }
    this.tracer.stop();
  }

  /**
   *  Get the current metrics API
   * @returns {object} - The metrics API
   */
  getMetrics() {
    return this.metrics;
  }

  /**
   * Get the current tracer
   * @returns {object} - The tracer
   */
  getTracer() {
    return this.tracer;
  }
}

export default OpenTelemetry;
```

