import { parse } from 'unist-parser';

/**
 * Calculates the start and end positions of a node in a document, relative to the root.
 *
 * @param {string} markdown - The markdown document as a string.
 * @param {string} nodeType - The type of node to find (e.g., 'paragraph', 'heading').
 * @returns {object | null} - An object with 'start' and 'end' properties, or null if the node is not found.
 */
function getNodePosition(markdown, nodeType) {
  const root = parse(markdown);
  let nodePosition = null;

  for (const node of root) {
    if (node.type === nodeType) {
      nodePosition = {
        start: node.value.start,
        end: node.value.end,
      };
      break;
    }
  }

  return nodePosition;
}

export default getNodePosition;
