```javascript
import * as unist from 'unist-util-unist';

/**
 * Gets the position of a node in a tree, relative to the root node.
 *
 * @param {Array<unist.Node>} tree The document as a list of nodes.
 * @param {unist.Node} node The node to get the position of.
 * @returns {{start: number, end: number}} An object with the start and end positions of the node.
 */
function getNodePosition(tree, node) {
  let position = 0;

  function traverse(nodes) {
    for (let i = 0; i < nodes.length; i++) {
      if (nodes[i] === node) {
        // Calculate the start position
        let start = position;
        // Calculate the end position
        let end = position + node.value.length;
        return { start, end };
      }
      if (nodes[i].children) {
        traverse(nodes[i].children);
      }
      position += nodes[i].value.length;
    }
    return null;
  }

  const result = traverse(tree);
  if (result) {
    return result;
  } else {
    return null;
  }
}
