```javascript
function checkAndNotifyUpdates() {
  try {
    const packageJsonPath = './package.json';
    const packageJson = require(packageJsonPath);

    if (!packageJson) {
      console.error('Error: package.json not found.');
      return;
    }

    const dependencies = packageJson.dependencies || {};
    const devDependencies = packageJson.devDependencies || {};

    const outdated = {};

    for (const packageName in dependencies) {
      try {
        const currentVersion = dependencies[packageName];
        const latestVersion = getLatestVersion(packageName);

        if (latestVersion && latestVersion > currentVersion) {
          outdated[packageName] = {
            currentVersion: currentVersion,
            latestVersion: latestVersion,
          };
        }
      } catch (error) {
        console.error(`Error checking version for ${packageName}: ${error.message}`);
      }
    }

    for (const packageName in devDependencies) {
      try {
        const currentVersion = devDependencies[packageName];
        const latestVersion = getLatestVersion(packageName);

        if (latestVersion && latestVersion > currentVersion) {
          outdated[packageName] = {
            currentVersion: currentVersion,
            latestVersion: latestVersion,
          };
        }
      } catch (error) {
        console.error(`Error checking version for ${packageName}: ${error.message}`);
      }
    }

    if (Object.keys(outdated).length === 0) {
      console.log('All dependencies are up to date.');
      return;
    }

    displayNotifications(outdated);

  } catch (error) {
    console.error('An error occurred:', error.message);
  }
}

function getLatestVersion(packageName) {
  try {
    const command = `npm view ${packageName} version`;
    const { stdout } = require('child_process').exec(command, { stdio: '']].catch(err => {
      console.error(`Error executing npm view command for ${packageName}: ${err.message}`);
      return null;
    });

    if (stdout) {
      return stdout.trim();
    } else {
      return null;
    }
  } catch (error) {
    console.error(`Error getting latest version for ${packageName}: ${error.message}`);
    return null;
  }
}

function displayNotifications(outdated) {
  console.log('\nOutdated dependencies found:');
  for (const packageName in outdated) {
    console.log(`- ${packageName}:`);
    console.log(`  Current version: ${outdated[packageName].currentVersion}`);
    console.log(`  Latest version: ${outdated[packageName].latestVersion}`);
    console.log('  Update command: npm install ' + packageName + '@latest');
    console.log('');
  }
  console.log('You can update your dependencies using the command above.');
}

// Run the check when the script is executed
checkAndNotifyUpdates();
