```javascript
// 1. Event stream from readable stream to JSON
const { Readable, Transform } = require('stream');
const { JSONStream } = require('json2stream');

class EventToJsonStream extends Transform {
  constructor(options = {}) {
    super(options);
    this.decoder = JSONStream.fromObject({
      objectMode: true,
      // You can add custom encoding options here if needed
    });
  }

  _transform(chunk, encoding, callback) {
    try {
      const json = JSON.parse(chunk.toString());
      this.push(json);
    } catch (err) {
      callback(err);
      return;
    }
  }
}

// Example usage:
// const readableStream = Readable.from([JSON.stringify({ id: 1, name: 'Alice' }), JSON.stringify({ id: 2, name: 'Bob' })]);
// const jsonStream = new EventToJsonStream();
// readableStream.pipe(jsonStream).on('data', (event) => console.log(event));



// 2. Duplex stream for concatenating two event streams
const { Duplex } = require('stream');

class ConcatenateStream extends Duplex {
  constructor(stream1, stream2) {
    super();
    this.stream1 = stream1;
    this.stream2 = stream2;
    this.closed = false;
  }

  _write(chunk, encoding, callback) {
    if (!this.closed) {
      this.stream1.write(chunk, (err) => {
        if (err) {
          callback(err);
          return;
        }
        callback();
      });
    } else {
      callback(null, 'END');
    }
  }

  _drain(callback) {
    if (!this.closed) {
      this.stream2.drain(callback);
    } else {
      callback();
    }
  }

  close() {
    this.closed = true;
    this.stream1.close();
    this.stream2.close();
  }
}

// Example usage:
// const stream1 = Readable.from([JSON.stringify({ id: 1, name: 'Alice' })]);
// const stream2 = Readable.from([JSON.stringify({ id: 2, name: 'Bob' })]);
// const concatStream = new ConcatenateStream(stream1, stream2);
// concatStream.pipe(process.stdout);



// 3. Codec for JavaScript objects and Protocol Buffers
const protobuf = require('protobufjs');

class JsonToProtobufCodec {
  encode(obj) {
    return protobuf.message.encode(obj);
  }

  decode(buffer) {
    return protobuf.message.decode(buffer);
  }
}

// Example usage:
// const codec = new JsonToProtobufCodec();
// const jsObject = { name: 'Charlie', age: 30 };
