// 4. Transform stream for decoding Protocol Buffer messages
const { Transform } = require('stream');
const protobuf = require('protobufjs');

class ProtobufToJsStream extends Transform {
  constructor(schema) {
    super();
    this.decoder = protobuf.decoder(schema);
  }

  _transform(chunk, encoding, callback) {
    try {
      const jsObject = this.decoder.decode(chunk);
      this.push(jsObject);
    } catch (err) {
      callback(err);
      return;
    }
  }
}

// Example usage:
