// 5. Transform stream for encoding JavaScript objects into Protocol Buffer messages
const { Transform } = require('stream');
const protobuf = require('protobufjs');

class JsToProtobufStream extends Transform {
  constructor(schema) {
    super();
    this.encoder = protobuf.encoder(schema);
  }

  _transform(chunk, encoding, callback) {
    try {
      const buffer = this.encoder.encode(chunk);
      this.push(buffer);
    } catch (err) {
      callback(err);
      return;
    }
  }
}

