import dns_sd from 'dns-sd';

/**
 * Encodes a DNS-SD TXT record RDATA field.
 *
 * @param {string} text The text to encode.
 * @returns {Buffer} The encoded buffer.
 * @throws {Error} If the input is not a string.
 */
function encodeTxtRecord(text) {
  if (typeof text !== 'string') {
    throw new Error('Input must be a string.');
  }

  const encoded = Buffer.from(text, 'utf8');
  return encoded;
}

/**
 * Decodes a DNS-SD TXT record RDATA field.
 *
 * @param {Buffer} buffer The encoded buffer.
 * @returns {string} The decoded text.
 * @throws {Error} If the input is not a Buffer.
 */
function decodeTxtRecord(buffer) {
  if (!(buffer instanceof Buffer)) {
    throw new Error('Input must be a Buffer.');
  }

  return buffer.toString('utf8');
}


// Example Usage (for testing)
async function testEncodingDecoding() {
  const text = "This is a test TXT record.";

  const encoded = encodeTxtRecord(text);
  console.log("Encoded:", encoded);

  const decoded = decodeTxtRecord(encoded);
  console.log("Decoded:", decoded);

  if (text === decoded) {
    console.log("Encoding and decoding successful!");
  } else {
    console.error("Encoding and decoding failed.");
  }
}

//testEncodingDecoding(); // Uncomment to run the test
export { encodeTxtRecord, decodeTxtRecord };
```

```javascript
const browserSupport = require('browser-support-check');

/**
 * Checks if the current browser supports the features specified in the package.json's 'browser' field.
 *
 * @param {object} packageJson - The package.json object.
 * @returns {Promise<object>} - An object containing the browser support results.
 */
async function checkBrowserSupport(packageJson) {
  try {
    const supportedBrowsers = packageJson.browser || [];

    if (!Array.isArray(supportedBrowsers)) {
      console.warn("The 'browser' field in package.json is not an array.  Ignoring browser support check.");
      return { success: true, results: [] }; // Or handle the error as needed
    }

    const currentBrowser = await browserSupport();

    const results = {};
    for (const browser of supportedBrowsers) {
      if (currentBrowser.matches(browser)) {
        results[browser] = { supported: true };
      } else {
        results[browser] = { supported: false };
      }
    }

    return { success: true, results };

  } catch (error) {
    console.error("Error checking browser support:", error);
    return { success: false, results: { error: error.message } };
  }
}


module.exports = checkBrowserSupport;
```

