```javascript
import { createServer } from 'http';
import { SsecMiddleware } from 'middleware-ssec';
import { S3Client, encrypt } from '@aws-sdk/client-s3';

/**
 * Middleware function to add AWS SSE-C encryption to HTTP requests.
 *
 * @param {object} options - Configuration options for the S3 client.
 * @returns {createServer} - A function that creates an HTTP server with the middleware.
 */
export function sseccMiddleware(options) {
  const s3Client = new S3Client(options);

  return async (req, res, next) => {
    try {
      const encryptedData = await encrypt(req.body, s3Client);
      res.setHeader('Content-Type', 'application/octet-stream');
      res.setHeader('Content-Disposition', 'attachment; filename="encrypted.txt"');
      res.setHeader('X-Amz-Server-Side-Encryption', 'aws:kms');
      res.setHeader('X-Amz-Server-Side-Encryption-Key', 'arn:aws:kms:YOUR_REGION:YOUR_ACCOUNT_ID:key/YOUR_KEY_ID'); // Replace with your KMS key ARN
      res.send(encryptedData);
    } catch (error) {
      console.error('Error encrypting data:', error);
      res.status(500).send('Error encrypting data');
    }
  };
}
```

