/**
 * remark-mdx Plugin for JSX support
 *
 * This plugin enables the use of JSX within Markdown files processed by Remark.
 * It transforms JSX elements into React components and renders them as HTML.
 */
module.exports = function(mdx, options) {
  const { transform } = require('mdx-js');

  return {
    /**
     * Transforms MDX content, handling JSX elements.
     * @param {string} content The MDX content to transform.
     * @returns {Promise<string>} A promise that resolves to the transformed HTML content.
     */
    async transform(content) {
      try {
        const { html, components } = await transform(content, options);
        return html;
      } catch (error) {
        console.error('Error transforming MDX:', error);
        return `<div>Error rendering MDX: ${error.message}</div>`; // Or handle the error differently
      }
    },
  };
};
