```javascript
import Backoff from 'segmentio-backoff';

/**
 * Makes a request with backoff retry logic.
 * @param {function} requestFunction - The function that performs the request.  Should return a Promise.
 * @param {object} options - Configuration options for the backoff strategy.
 * @returns {Promise} - A promise that resolves with the result of the request or rejects if all retries fail.
 */
async function makeRequestWithBackoff(requestFunction, options = {}) {
  const { maxRetries = 3, baseDelay = 100 } = options;

  try {
    return await Backoff.Retry(requestFunction, {
      maxRetries,
      baseDelay,
      randomJitter: 50, // Add some randomness to the delay
    });
  } catch (error) {
    // If all retries fail, re-throw the error.
    throw error;
  }
}

export default makeRequestWithBackoff;
```

