/**
 * Sentry Performance Monitoring Package - JavaScript
 *
 * This code provides a basic framework for integrating Sentry Performance Monitoring into your JavaScript application.
 * It includes installation instructions, code snippets, and configuration options.
 */

/**
 * Installation Instructions:
 *
 * 1.  Install the Sentry Performance SDK:
 *     npm install sentry-performance
 *
 * 2.  Initialize Sentry with your project key:
 *     (See Configuration section below)
 */

/**
 * Configuration Settings:
 *
 *  - `sentry.dsn`: Your Sentry DSN (Data Source Name).  Obtain this from your Sentry project settings.
 *  - `sentry.environment`:  The environment of your application (e.g., 'development', 'staging', 'production').
 *  - `sentry.level`: The minimum Sentry level to report (e.g., 'error', 'warning', 'info').
 *  - `sentry.performance.sample_rate`: The percentage of requests to sample for performance monitoring (0-100).  Defaults to 100.
 *  - `sentry.performance.capture_resource`: Whether to capture resource information (e.g., CPU, memory) with performance events. Defaults to true.
 *  - `sentry.performance.capture_tags`:  An array of tags to include with performance events.
 */

// Example Configuration (replace with your actual values)
const config = {
  dsn: 'YOUR_SENTRY_DSN',
  environment: 'development',
  level: 'error',
  performance: {
    sample_rate: 100,
    capture_resource: true,
    capture_tags: ['my-custom-tag']
  }
};


/**
 * Initialize Sentry Performance
 */
import { Performance } from '@sentry/performance';

const sentry = new Performance(config.dsn, {
  environment: config.environment,
  level: config.level,
  performance: config.performance
});


/**
 * Code Snippet Example:  Capture a performance event
 */
async function capturePerformanceEvent(operationName, duration, tags = []) {
  try {
    await sentry.capture({
      name: operationName,
      duration: duration,
      tags: tags,
    });
    console.log(`Performance event captured: ${operationName} (${duration}ms)`);
  } catch (error) {
    console.error('Error capturing performance event:', error);
  }
}


/**
 * Code Snippet Example:  Capture a custom performance event with resource data
 */
async function captureCustomPerformanceEvent(operationName, duration, cpuUsage, memoryUsage, tags = []) {
  try {
    await sentry.capture({
      name: operationName,
      duration: duration,
      cpu: cpuUsage,
      memory: memoryUsage,
      tags: tags,
    });
    console.log(`Custom performance event captured: ${operationName} (${duration}ms)`);
  } catch (error) {
    console.error('Error capturing custom performance event:', error);
  }
}


/**
 *  Example Usage (replace with your actual values)
 */
async function runExample() {
  // Simulate a long-running operation
  await new Promise(resolve => setTimeout(resolve, 100)); // 100ms
  await capturePerformanceEvent('myLongOperation', 100);

  await new Promise(resolve => setTimeout(resolve, 50)); // 50ms
  await captureCustomPerformanceEvent('anotherOperation', 50, 20, 5);
}

//runExample(); // Uncomment to run the example.  Remember to replace YOUR_SENTRY_DSN.



/**
 *  Error Handling:
 *
 *  -  Ensure your Sentry DSN is correctly configured.
 *  -  Handle potential errors during event capture.
 *  -  Consider using a try/catch block around your performance event capture calls.
 */
