```javascript
import * as protobuf from '@protobuf-js/core';

/**
 * Serializes a protobuf message to a JSON string.
 * @param {protobuf.Message} message The protobuf message to serialize.
 * @returns {string} The JSON string representation of the message.
 * @throws {Error} If the message is not a protobuf message.
 */
function serializeProto3ToJson(message) {
  if (!(message instanceof protobuf.Message)) {
    throw new Error("Input must be a protobuf message.");
  }

  return JSON.stringify(message);
}

/**
 * Deserializes a JSON string to a protobuf message.
 * @param {string} jsonString The JSON string to deserialize.
 * @param {string} typeName The name of the protobuf message type.
 * @returns {protobuf.Message} The protobuf message object.
 * @throws {Error} If the JSON string is not valid or the message type is not found.
 */
function deserializeJsonToProto3(jsonString, typeName) {
  try {
    const message = protobuf.Message.from(jsonString, typeName);
    return message;
  } catch (error) {
    throw new Error(`Invalid JSON string or message type not found: ${error.message}`);
  }
}
