// 2. Instrument a function to track execution time
function myFunction(arg) {
  const start = performance.now();
  try {
    // Simulate some work
    for (let i = 0; i < 1000000; i++) {
      // do nothing
    }
    const result = arg * 2;
    const end = performance.now();
    const duration = end - start;

    // Add annotation to the span
    tracing.getTracer().getSpan(
      'myFunction',
      { tags: { arg: arg } }
    ).addSpanInformation('execution_time', duration);
    return result;
