```javascript
class Logger {
  constructor(level = 'info', format = '%d %H:%M:%S %l %m %f', destination = 'console') {
    this.level = level;
    this.format = format;
    this.destination = destination;
    this.logData = [];
  }

  setLevel(level) {
    this.level = level;
  }

  setFormat(format) {
    this.format = format;
  }

  setDestination(destination) {
    this.destination = destination;
  }

  log(message) {
    const timestamp = new Date().toISOString();
    const logEntry = `${timestamp} ${this.level} ${this.format.replace('%d', timestamp)} ${message}`;
    this.logData.push(logEntry);

    this.sendLog(logEntry);
  }

  sendLog(logEntry) {
    switch (this.destination) {
      case 'console':
        console.log(logEntry);
        break;
      case 'file':
        this.writeToFile(logEntry);
        break;
      case 'azure':
        this.sendToAzure(logEntry);
        break;
      default:
        console.warn(`Unknown destination: ${this.destination}.  Logging to console instead.`);
        console.log(logEntry);
    }
  }

  writeToFile(logEntry) {
    const fs = require('fs');
    fs.appendFile('app.log', logEntry + '\n', (err) => {
      if (err) {
        console.error('Error writing to file:', err);
      }
    });
  }

  sendToAzure(logEntry) {
    // Placeholder for Azure logging implementation.  Requires Azure SDK.
    console.log('Sending to Azure:', logEntry);
    // Example using Azure SDK (requires installation: npm install azure-monitor-ingestion)
    // const { ActivitySource } = require("@azure/activity-source");
    // const activitySource = new ActivitySource('MyLogger', 'MyApplication');
    // activitySource.sendActivity({
    //   operation_name: 'LogMessage',
    //   category: 'Application',
    //   log_data: {
    //     message: logEntry
    //   }
    // });
  }

  getLogs() {
    return this.logData;
  }
}

module.exports = Logger;
