import * as libSass from 'libsass';

/**
 * Compiles Sass code into CSS.
 *
 * @param {string} sassCode The Sass code to compile.
 * @param {object} options (Optional) An object containing options for the compilation process.
 * @param {string} [options.style='expanded'] The output style of the CSS (e.g., 'expanded', 'compact', 'compressed'). Defaults to 'expanded'.
 * @param {boolean} [options.sourceMap=false] Whether to generate a source map. Defaults to false.
 * @returns {Promise<string>} A promise that resolves with the compiled CSS string.
 * @throws {Error} If the Sass code is invalid or if there is an error during compilation.
 */
async function compileSass(sassCode, options = {}) {
  try {
    const { style = 'expanded', sourceMap = false } = options;

    const result = await libSass.compile(sassCode, {
      style: style,
      sourceMap: sourceMap,
    });

    return result.css;
  } catch (error) {
    throw new Error(`Sass compilation failed: ${error.message}`);
  }
}

export default compileSass;
