/**
 * Streams HTML form data and emits events for each field.
 *
 * @param {string} htmlString The HTML string containing the form data.
 * @param {function} callback A callback function that is called when parsing is complete.
 */
function streamFormParser(htmlString, callback) {
  const parser = new htmlparser.Parser({
    onopentag: (name, attributes) => {
      if (attributes.name === 'input' || attributes.name === 'textarea' || attributes.name === 'select') {
        emitField(name, attributes);
      }
    },
    ontext: (text) => {
      // Ignore text content for simplicity.  Could be extended to handle it.
    },
    onclosetag: (name) => {
      // Ignore closing tags for simplicity.
    },
    onend: () => {
      callback();
    },
    onerror: (error) => {
      console.error("Error parsing HTML:", error);
      callback(error);
    }
  });

  parser.write(htmlString);
  parser.end();

  function emitField(name, attributes) {
    console.log(`Field: ${name}, Attributes: ${JSON.stringify(attributes)}`);
    // You can emit a custom event here if needed.
    // For example:
    // emitter.emit('field', { name: name, attributes: attributes });
  }
}

module.exports = streamFormParser;
