```javascript
const sassParse = require('sass-parse');

function buildImportGraph(sassFilePath) {
  try {
    const ast = sassParse.parse(sassFilePath);
    const importNodes = [];

    function traverse(node) {
      if (node.type === 'use') {
        const importNode = {
          name: node.value.value,
          dependencies: [],
        };
        importNodes.push(importNode);

        if (node.value.params && node.value.params.value) {
          if (Array.isArray(node.value.params.value)) {
            node.value.params.value.forEach(param => {
              if (param.type === 'url') {
                importNode.dependencies.push(param.value);
              }
            });
          } else if (node.value.params.value.type === 'url') {
            importNode.dependencies.push(node.value.params.value.value);
          }
        }
      }

      for (const key in node) {
        if (typeof node[key] === 'object' && node[key] !== null) {
          if (Array.isArray(node[key])) {
            node[key].forEach(child => traverse(child));
          } else {
            traverse(node[key]);
          }
        }
      }
    }

    traverse(ast);

    // Build the graph
    const graph = {};
    importNodes.forEach(node => {
      graph[node.name] = { dependencies: node.dependencies };
    });

    return graph;

  } catch (error) {
    console.error("Error parsing Sass file:", error);
    return null;
  }
}

module.exports = buildImportGraph;
```

```javascript
function buildImportGraph(sassFilePath) {
  try {
    const fs = require('fs');
    const path = require('path');
    const sassParse = require('sass-parse');

    const source = fs.readFileSync(sassFilePath, 'utf8');
    const ast = sassParse(source);

    const importNodes = [];
    const graph = {};

    function traverse(node, parentNode = null) {
      if (node.type === 'import') {
        const importNode = {
          type: 'import',
          source: node.value,
          dependencies: [],
        };
        importNodes.push(importNode);

        if (parentNode) {
          if (!graph[parentNode.id]) {
            graph[parentNode.id] = [];
          }
          graph[parentNode.id].push(importNode);
        }
      }

      for (const child of node.children) {
        traverse(child, node);
      }
    }

    traverse(ast);

    return {
      nodes: importNodes,
      graph: graph,
    };

  } catch (error) {
    console.error("Error parsing Sass file:", error);
    return { nodes: [], graph: {} };
  }
}

module.exports = buildImportGraph;
```

