import { createParser, createTransformer, createSerializer } from 'mdast';
import * as gfm from 'mdast-gfm';

async function processGFM(markdown) {
  const parser = createParser({ extensions: [gfm()] });
  const root = await parser.parse(markdown);

  const transformer = createTransformer({
    plugins: [
      {
        transform: (node) => {
          if (node.type === 'strikethrough') {
            node.type = 'bold';
            node.content = node.content.toLowerCase() + '~~' + node.content.toUpperCase() + '~~';
          }
        },
      },
    ],
  });

  const transformedRoot = await transformer.transform(root);

  const serializer = createSerializer();
  return serializer.serialize(transformedRoot);
}

export default processGFM;
```

```javascript
import {
  Keypair,
  Signer,
  Verifier,
  Encoding,
  SHA256,
} from 'webcrypt';

/**
 * Signs a message using a private key.
 * @param {string} password The password used to derive the private key.
 * @param {string} message The message to sign.
 * @returns {string | null} The signature as a hexadecimal string, or null if an error occurs.
 */
async function signMessage(password, message) {
  try {
    const keypair = await Keypair.fromPassword(password);
    const signer = new Signer(keypair, SHA256);
    const encodedMessage = Encoding.toBuffer(message);
    const signature = await signer.sign(encodedMessage);
    return signature.toString('hex');
  } catch (error) {
    console.error("Error signing message:", error);
    return null;
  }
}

/**
 * Verifies a signature against a public key.
 * @param {string} password The password used to derive the private key.
 * @param {string} message The message that was signed.
 * @param {string} signature The signature to verify.
 * @returns {boolean} True if the signature is valid, false otherwise.
 */
async function verifySignature(password, message, signature) {
  try {
    const keypair = await Keypair.fromPassword(password);
    const verifier = new Verifier(keypair, SHA256);
    const encodedMessage = Encoding.toBuffer(message);
    const isValid = await verifier.verify(Encoding.fromHex(signature), encodedMessage);
    return isValid;
  } catch (error) {
    console.error("Error verifying signature:", error);
    return false;
  }
}


export { signMessage, verifySignature };
```

