import { tuf } from '@sigstore/tuf-client';

/**
 * Configures a Sigstore TUF client.
 * @param {string} serverUrl The URL of the TUF server.
 * @param {string} clientKeyPath Path to the client key file.
 * @param {string} clientSecretPath Path to the client secret file.
 * @returns {object} A TUF client object.
 * @throws {Error} If serverUrl, clientKeyPath, or clientSecretPath are missing.
 */
async function createTufClient(serverUrl, clientKeyPath, clientSecretPath) {
  if (!serverUrl) {
    throw new Error('Server URL is required.');
  }
  if (!clientKeyPath) {
    throw new Error('Client key path is required.');
  }
  if (!clientSecretPath) {
    throw new Error('Client secret path is required.');
  }

  try {
    const client = await tuf({
      serverUrl: serverUrl,
      clientKeyPath: clientKeyPath,
      clientSecretPath: clientSecretPath,
    });
    return client;
  } catch (error) {
    console.error('Error creating TUF client:', error);
    throw error;
  }
}


/**
 * Lists repositories in the TUF server.
 * @param {object} client The TUF client object.
 * @returns {Promise<Array<string>>} A promise that resolves to an array of repository names.
 * @throws {Error} If the request fails.
 */
async function listRepositories(client) {
  try {
    const repositories = await client.listRepositories();
    return repositories;
  } catch (error) {
    console.error('Error listing repositories:', error);
    throw error;
  }
}

/**
 * Creates a new deposit in a repository.
 * @param {object} client The TUF client object.
 * @param {string} repositoryName The name of the repository.
 * @param {string} depositName The name of the deposit to create.
 * @param {string} key The key to add to the deposit.
 * @returns {Promise<object>} A promise that resolves to the created deposit object.
 * @throws {Error} If the request fails.
 */
async function createDeposit(client, repositoryName, depositName, key) {
  try {
    const deposit = await client.createDeposit(repositoryName, depositName, key);
    return deposit;
  } catch (error) {
    console.error('Error creating deposit:', error);
    throw error;
  }
}

/**
 * Adds a new key to an existing deposit.
 * @param {object} client The TUF client object.
 * @param {string} repositoryName The name of the repository.
 * @param {string} depositName The name of the deposit to add the key to.
 * @param {string} key The key to add.
 * @returns {Promise<object>} A promise that resolves to the updated deposit object.
 * @throws {Error} If the request fails.
 */
async function addKeyToDeposit(client, repositoryName, depositName, key) {
  try {
    const deposit = await client.addKeyToDeposit(repositoryName, depositName, key);
    return deposit;
  } catch (error) {
    console.error('Error adding key to deposit:', error);
    throw error;
  }
}


export { createTufClient, listRepositories, createDeposit, addKeyToDeposit };
