import { marked } from 'marked';
import Terminus from 'terminus-theme-color-palette';

marked.setOptions({
  renderer: new CustomTerminusRenderer(Terminus),
});

class CustomTerminusRenderer extends marked.Renderer {
  render(tokens, context, env) {
    const element = tokens[0].type;

    switch (element) {
      case 'heading':
        return `<span style="color: ${env.color.header}${env.color.text}; font-size: 1.2em;">${tokens[0].text}</span>`;
      case 'bold':
        return `<span style="font-weight: bold; color: ${env.color.text};">${tokens[0].text}</span>`;
      case 'italic':
        return `<span style="font-style: italic; color: ${env.color.text};">${tokens[0].text}</span>`;
      case 'link':
        return `<span class="link" style="color: ${env.color.link}">${tokens[0].text}</span>`;
      case 'code':
        return `<span class="code" style="color: ${env.color.code}">${tokens[0].text}</span>`;
      case 'quote':
        return `<span class="quote" style="color: ${env.color.text}; font-style: italic; background-color: ${env.color.quote}; padding: 0.2em; border-left: 2px solid ${env.color.quote};">${tokens[0].text}</span>`;
      case 'listitem':
        return `<span style="color: ${env.color.text};">${tokens[0].text}</span>`;
      case 'paragraph':
        return `<p style="color: ${env.color.text};">${tokens[0].text}</p>`;
      default:
        return tokens[0].text;
    }
  }
}
