#!/usr/bin/env node

const process = require('process');
const fs = require('fs');
const path = require('path');
const { exec } = require('child_process');

function runJasmine(args) {
  const jasminePath = require('jasmine');
  const options = {};

  if (args.length > 0 && args[0] === '--spec') {
    options.specFile = args[1];
  }

  if (args.length > 0 && args[0] === 'run') {
    exec(`jasmine ${JSON.stringify(options)}`, (error, stdout, stderr) => {
      if (error) {
        console.error(`Error running Jasmine: ${error}`);
        return;
      }
      console.log(stdout);
      if (stderr) {
        console.error(`Jasmine stderr: ${stderr}`);
      }
    });
  } else if (args.length > 0 && args[0] === 'install') {
    exec('npm install -g jasmine-cli', (error, stdout, stderr) => {
      if (error) {
        console.error(`Error installing jasmine-cli: ${error}`);
        return;
      }
      console.log(stdout);
      if (stderr) {
        console.error(`jasmine-cli install stderr: ${stderr}`);
      }
    });
  } else {
    console.log('Usage: jasmine <command> [options]');
    console.log('Commands:');
    console.log('  run [specFile]');
    console.log('  install');
    console.log('  help');
  }
}

if (process.argv.length < 3) {
  console.log('Usage: jasmine <command> [options]');
  console.log('Commands:');
  console.log('  run [specFile]');
  console.log('  install');
  console.log('  help');
} else {
  const command = process.argv[2];
  const args = process.argv.slice(3);
  runJasmine(command, args);
}
