```javascript
import { Context } from '@opentelemetry/context';
import { getContext } from '@opentelemetry/context';
import { Tracing } from '@opentelemetry/trace';
import { Metrics } from '@opentelemetry/metrics';
import { Logs } from '@opentelemetry/logs';

/**
 * Async Hooks based OpenTelemetry Context Manager
 *
 * @returns {function} A function that accepts an async function and returns a function
 *                    that wraps the async function with OpenTelemetry context management.
 */
async function contextManager() {
  const tracing = new Tracing();
  const metrics = new Metrics();
  const logs = new Logs();

  const context = getContext();

  return async function (fn) {
    return async (...args) => {
      const currentContext = context.get();

      const wrappedFn = async (...argsToFn) => {
        const newContext = new Context(currentContext);
        try {
          newContext.setSpanName('function'); // Optional: Set span name
          const result = await fn(...argsToFn);
          return result;
        } finally {
          context.set(newContext);
        }
      };

      return await wrappedFn(...args);
    };
  };
}

export default contextManager;
```

