```javascript
const workerPool = require('worker_pool');
const path = require('path');

// Define the loaders
function loader1(file) {
  return new Promise((resolve, reject) => {
    // Simulate loading a file from a directory
    setTimeout(() => {
      const contents = `File contents for ${file}`;
      // Simulate writing to a different directory
      const outputPath = path.join('output', file);
      console.log(`Loaded ${file} and wrote to ${outputPath}`);
      resolve({ file: file, contents: contents });
    }, 500);
  });
}

function loader2(code) {
  return new Promise((resolve, reject) => {
    // Simulate transpiling ES6 code to ES5 code
    setTimeout(() => {
      const transpiledCode = `Transpiled code for ${code}`;
      console.log(`Transpiled ${code}`);
      resolve({ code: code, transpiledCode: transpiledCode });
    }, 300);
  });
}

function loader3(image) {
  return new Promise((resolve, reject) => {
    // Simulate optimizing an image
    setTimeout(() => {
      const optimizedImage = `Optimized image for ${image}`;
      console.log(`Optimized ${image}`);
      resolve({ image: image, optimizedImage: optimizedImage });
    }, 400);
  });
}

function loader4(file) {
  return new Promise((resolve, reject) => {
    // Simulate analyzing and reporting on file size
    setTimeout(() => {
      const fileSize = `File size of ${file}`;
      console.log(`Analyzed ${file}`);
      resolve({ file: file, fileSize: fileSize });
    }, 200);
  });

}

async function runLoaders(files) {
  const pool = workerPool({
    workers: 4, // Adjust the number of workers as needed
  });

  const tasks = [];

  // Create tasks for each loader
  for (const file of files) {
    tasks.push({
      loader: 'loader1',
      args: [file],
    });
    tasks.push({
      loader: 'loader2',
      args: [file],
    });
    tasks.push({
      loader: 'loader3',
      args: [file],
    });
    tasks.push({
      loader: 'loader4',
      args: [file],
    });
  }

  try {
    const results = await pool.run(tasks);
    console.log('All tasks completed successfully.');
    console.log('Results:', results);
  } catch (error) {
    console.error('An error occurred:', error);
  } finally {
    await pool.terminate();
  }
}

// Example usage:
const files = ['file1.txt', 'file2.js', 'image1.jpg'];
runLoaders(files);
