import { B3Propagator } from '@opentelemetry/propagator';

/**
 * Configures and initializes an OpenTelemetry B3 propagator.
 *
 * @param {object} options - Configuration options for the propagator.
 * @param {string} options.serviceName - The name of the service.
 * @param {boolean} options.traceIdHeader - Whether to use the `traceId` header.
 * @param {boolean} options.spanIdHeader - Whether to use the `spanId` header.
 * @param {boolean} options.parentSpanIdHeader - Whether to use the `parentSpanId` header.
 * @returns {B3Propagator} - The initialized B3 propagator.
 */
export function initializeB3Propagator(options = {}) {
  const { serviceName, traceIdHeader = 'traceId', spanIdHeader = 'spanId', parentSpanIdHeader = 'parentSpanId' } = options;

  const propagator = new B3Propagator({
    serviceName: serviceName,
    traceIdHeader: traceIdHeader,
    spanIdHeader: spanIdHeader,
    parentSpanIdHeader: parentSpanIdHeader,
  });

  return propagator;
}
