import { JaegerPropagator } from '@opentelemetry/propagator';

// Create a Jaeger propagator instance.  This will automatically
// inject Jaeger headers into outgoing HTTP requests.
const jaegerPropagator = new JaegerPropagator();

// To use the propagator, you'll typically need to configure your HTTP client
// to use it.  The exact method depends on the HTTP client library you're using.
// Here's an example using Node.js's built-in http module:

// Example usage with Node.js http module (replace with your actual HTTP client)
import http from 'http';

const server = http.createServer((req, res) => {
  // Access the propagator to get the Jaeger headers.
  const headers = jaegerPropagator.getHeaders();

  // Add the Jaeger headers to the response.
  for (const key in headers) {
    if (headers.hasOwnProperty(key)) {
      res[key] = headers[key];
    }
  }

  res.writeHead(200, headers);
  res.end('Hello, Jaeger!');
});

const port = 3000;
server.listen(port, () => {
  console.log(`Server listening on port ${port}`);
});
