// Define the schematic
import { SchematicsException } from '@angular/schematics';
import * as path from 'path';

export function myProjectCreator(options?: any) {
  return (ctx: any) => {
    // 1. Prompt for project name
    const projectName = ctx.prompt('Enter project name:');

    // 2. Create project directory
    const projectPath = path.resolve(ctx.getcwd(), projectName);

    // 3. Initialize Angular project
    ctx.run('ng', ['init', projectName]); // Assuming ng CLI is available

    // 4. Create default files (e.g., app.component.ts)
    const defaultFiles = [
      {
        name: 'app.component.ts',
        content: '// Your app component code here'
      }
    ];

    for (const file of defaultFiles) {
      ctx.copy(file.name, path.join(projectPath, file.name));
    }

    // 5. Add to package.json
    ctx.modify('package.json', (content) => {
      // Add dependencies, scripts, etc.
      return content;
    });

    return ctx;
  };
}

export function myComponentGenerator(options?: any) {
  return (ctx: any) => {
    const componentName = ctx.prompt('Enter component name:');
    const componentPath = path.join(ctx.getcwd(), 'src', 'app', componentName);

    // Create component directory if it doesn't exist
    if (!path.exists(componentPath)) {
      ctx.createDirectory(componentPath);
    }

    // Create component files (component.ts, component.html, component.css)
    ctx.copy('templates/component/component.ts', path.join(componentPath, 'component.ts'));
    ctx.copy('templates/component/component.html', path.join(componentPath, 'component.html'));
    ctx.copy('templates/component/component.css', path.join(componentPath, 'component.css'));

    // Update app.module.ts
    ctx.modify('src/app/app.module.ts', (content) => {
      // Add the component to the module declarations
      return content;
    });

    return ctx;
  };
}

// Example of a service generator
export function myServiceGenerator(options?: any) {
    return (ctx: any) => {
        const serviceName = ctx.prompt('Enter service name:');
        const servicePath = path.join(ctx.getcwd(), 'src', 'app', 'services', serviceName);

        if (!path.exists(servicePath)) {
            ctx.createDirectory(servicePath);
        }

        ctx.copy('templates/service/service.ts', path.join(servicePath, 'service.ts'));
        return ctx;
    }
}
