import { OTLP, Collector } from '@opentelemetry/js';

/**
 * Configures and starts the OpenTelemetry collector for exporting trace data.
 * @param {object} config - Configuration object for the OTLP exporter.
 * @returns {Promise<void>}
 */
async function startOTLPExporter(config) {
  const otlp = new OTLP({
    endpoint: config.endpoint,
    protocol: config.protocol || 'grpc', // Default to gRPC
  });

  const collector = new Collector({
    telemetryProvider: otlp,
    attributes: config.attributes || {},
  });

  try {
    await collector.start();
    console.log('OTLP exporter started successfully.');
  } catch (err) {
    console.error('Error starting OTLP exporter:', err);
    throw err;
  }
}

export { startOTLPExporter };
