/**
 * Processes OpenTelemetry data and outputs in OTLP format.
 *
 * @param {Array<Object>} telemetryData - An array of OpenTelemetry data objects.
 *                                       Each object should have a 'traces' property,
 *                                       which is an array of trace objects.
 *                                       Each trace object should have a 'spans' property,
 *                                       which is an array of span objects.
 * @returns {string} - The transformed data in OTLP format as a string.
 */
function processAndOutputOTLP(telemetryData) {
  if (!Array.isArray(telemetryData)) {
    console.error("Input must be an array.");
    return "";
  }

  const otlp = require('otlp-js');

  let otlpBuffer = Buffer.alloc(0);

  for (const data of telemetryData) {
    if (data && data.traces && Array.isArray(data.traces)) {
      for (const trace of data.traces) {
        if (trace && trace.spans && Array.isArray(trace.spans)) {
          for (const span of trace.spans) {
            // Simulate processing using a simple transformation.
            // Replace this with your actual processing logic.
            const transformedSpan = {
              attributes: span.attributes.map(attr => ({ key: attr.key, value: attr.value })),
              spanId: span.spanId,
              traceId: span.traceId,
              start: span.start,
              end: span.end,
              name: span.name
            };

            // Convert the transformed span to OTLP format.
            const otlpSpan = otlp.Span.create(transformedSpan);
            otlpBuffer = Buffer.concat([otlpBuffer, otlpSpan.toBuffer()]);
          }
        }
      }
    }
  }

  return otlpBuffer.toString('base64');
}

// Example Usage (replace with your actual data)
const sampleTelemetryData = [
  {
    traces: [
      {
        spans: [
          {
            spanId: 'span1',
            traceId: 'trace1',
            start: 1678886400000,
            end: 1678886460000,
            name: 'operation1',
            attributes: [{ key: 'http.url', value: 'http://example.com' }]
          },
          {
            spanId: 'span2',
            traceId: 'trace1',
            start: 1678886460000,
            end: 1678886520000,
            name: 'operation2',
            attributes: [{ key: 'http.url', value: 'http://example.com/path' }]
          }
        ]
      }
    ]
  }
];

const otlpOutput = processAndOutputOTLP(sampleTelemetryData);
console.log(otlpOutput);
