const winston = require('winston');

const Logzio = require('logzio');

/**
 * Winston transport wrapper for Logzio.
 * @param {object} options - Configuration options for the Logzio client.
 * @param {string} options.apiKey - Logzio API key.
 * @param {string} options.projectKey - Logzio project key.
 * @param {string} [options.logzioHost='logzio.com'] - Logzio host.
 * @param {number} [options.logzioPort=443] - Logzio port.
 */
function LogzioTransport(options) {
  if (!options || !options.apiKey || !options.projectKey) {
    throw new Error('LogzioTransport requires apiKey and projectKey.');
  }

  const logzio = new Logzio({
    apiKey: options.apiKey,
    projectKey: options.projectKey,
    host: options.logzioHost || 'logzio.com',
    port: options.logzioPort || 443,
  });

  return winston.transport({
    name: 'logzio',
    target: (message) => {
      logzio.send(message);
      return Promise.resolve(); // Ensure promise resolution
    },
    format: winston.format.json(), // Or your preferred format
  });
}

module.exports = LogzioTransport;
```

```javascript
const winston = require('winston');

class LogzioTransport extends winston.transport {
  constructor(options) {
    super({
      name: 'logzio',
      options: options,
    });
  }

  open(config) {
    this.client = require('logzio').Client(config);
    return Promise.resolve();
  }

  close() {
    if (this.client) {
      this.client.close();
    }
  }

  error(err, req, res, level, message) {
    try {
      this.client.error(level, message);
    } catch (error) {
      console.error('Logzio error:', error);
    }
  }

  info(message) {
    this.client.info(message);
  }

  warn(message) {
    this.client.warn(message);
  }

  debug(message) {
    this.client.debug(message);
  }

  verbose(message) {
    this.client.verbose(message);
  }

  silly(message) {
    this.client.silly(message);
  }
}

module.exports = LogzioTransport;
```

