/**
 * Parses and validates Swagger 2.0 and OpenAPI 3.0 documents.
 *
 * @param {string} specString - The Swagger/OpenAPI specification as a string.
 * @param {string} specFormat - The format of the specification ('swagger2' or 'openapi3'). Defaults to 'swagger2'.
 * @returns {object|null} - A JavaScript object representing the API definition, or null if parsing/validation fails.
 * @throws {Error} - If the specFormat is invalid.
 */
function parseAndValidateApiSpec(specString, specFormat = 'swagger2') {
  try {
    if (specFormat === 'swagger2') {
      return parseSwagger2(specString);
    } else if (specFormat === 'openapi3') {
      return parseOpenAPI3(specString);
    } else {
      throw new Error("Invalid specFormat. Must be 'swagger2' or 'openapi3'.");
    }
  } catch (error) {
    console.error("Error parsing/validating API spec:", error);
    return null;
  }
}


/**
 * Parses a Swagger 2.0 specification.
 * @param {string} specString - The Swagger 2.0 specification as a string.
 * @returns {object|null} - A JavaScript object representing the API definition.
 */
function parseSwagger2(specString) {
  try {
    const swashbuckle = require('swagger-jsdoc'); //Requires installation: npm install swagger-jsdoc
    const parsedSpec = swashbuckle.parse(specString);
    return parsedSpec;
  } catch (error) {
    console.error("Error parsing Swagger 2.0:", error);
    return null;
  }
}

/**
 * Parses an OpenAPI 3.0 specification.
 * @param {string} specString - The OpenAPI 3.0 specification as a string.
 * @returns {object|null} - A JavaScript object representing the API definition.
 */
function parseOpenAPI3(specString) {
  try {
    const openApi = require('openapi-spec'); //Requires installation: npm install openapi-spec
    const parsedSpec = openApi.parse(specString);
    return parsedSpec;
  } catch (error) {
    console.error("Error parsing OpenAPI 3.0:", error);
    return null;
  }
}


