```javascript
// icon-converter.js

/**
 * Converts Material Design SVG icons to Material-UI React components.
 *
 * @param {string} svgPath The path to the Material Design SVG file.
 * @param {object} [options={}] Optional configuration options.
 * @param {string} [options.name] The name of the React component to create. Defaults to the SVG filename without extension.
 * @param {object} [options.styleOverrides] An object containing style overrides for the component.
 * @param {object} [options.propsOverrides] An object containing prop overrides for the component.
 * @returns {import('react-svgr').ReactSVGR} A React component representing the converted icon.
 * @throws {Error} If the SVG file cannot be found or parsed.
 */
function convertIcon(svgPath, options = {}) {
  const { name, styleOverrides, propsOverrides } = options;

  try {
    const svg = new DOMParser().parseFromString(
      fetch(svgPath).then(response => response.text())
      , 'image/svg+xml'
    );

    const svgData = svg.documentElement.outerHTML;

    const ReactSVGR = import('react-svgr').then(module => module.default);

    if (!ReactSVGR) {
      throw new Error("react-svgr import failed. Ensure it is installed and accessible.");
    }

    const Icon = ReactSVGR(svgData, {
      name: name || path => path.replace(/\.[^/.]+$/, ""),
      styleOverrides: styleOverrides,
      propsOverrides: propsOverrides,
    });

    return Icon;

  } catch (error) {
    console.error("Error converting icon:", error);
    throw new Error(`Failed to convert icon from ${svgPath}: ${error.message}`);
  }
}

export default convertIcon;
```

```javascript
/**
 * Sorts Tailwind CSS classes in HTML code.
 *
 * @param {string} html The HTML code to process.
 * @returns {string} The modified HTML code with sorted Tailwind CSS classes.
 */
function sortTailwindClasses(html) {
  const { parse } = require('html-react-parser');
  const { parse as tailwindParse } = require('tailwind-html-parser');

  const ast = parse(html);

  function traverse(node) {
    if (node.type === 'Tag' && node.attributes) {
      for (const attr of node.attributes) {
        if (attr.name === 'class') {
          const classList = attr.value.split(' ');
          const sortedClassList = classList.sort();
          attr.value = sortedClassList.join(' ');
        }
      }
    }

    if (node.type === 'Text') {
      return;
    }

    if (node.type === 'Tag') {
      for (const child of node.children) {
        traverse(child);
      }
    }
  }

  traverse(ast);

  return parse(ast).toString();
}

module.exports = sortTailwindClasses;
```

