/**
 * Salesforce CLI Plugin using sfdx module.
 */

const sfdx = require('@salesforce/sfdx');
const { program } = require('commander');

program
  .version('1.0.0')
  .description('A Salesforce CLI Plugin for executing Salesforce operations.');

// Helper function to execute sfdx commands
async function executeSfdxCommand(command, options = {}) {
  try {
    const result = await sfdx.command(command, options);
    console.log(result);
    return result;
  } catch (error) {
    console.error('Error executing sfdx command:', error);
    throw error; // Re-throw to allow for higher-level error handling
  }
}


program
  .command('create-record')
  .description('Creates a new Salesforce record.')
  .option('-o, --object <objectName>', 'The Salesforce object to create (e.g., Account, Contact).')
  .option('-f, --fields <fields>', 'Comma-separated list of fields and values (e.g., Name=Test Account,Industry=Technology).')
  .action(async (options) => {
    const fields = options.fields.split(',');
    const data = {};

    for (const field of fields) {
      const [key, value] = field.split('=');
      data[key.trim()] = value.trim();
    }

    try {
      const result = await executeSfdxCommand('sfdx force:create:record', {
        type: options.object,
        data: data,
      });
      console.log('Record created successfully:', result);
    } catch (error) {
      console.error('Error creating record:', error);
    }
  });

