  .command('retrieve-metadata')
  .description('Retrieves Salesforce metadata.')
  .option('-t, --type <type>', 'The type of metadata to retrieve (e.g., ApexClass, CustomObject).')
  .action(async (options) => {
    try {
      const result = await executeSfdxCommand('sfdx force:mdapi:retrieveMetadata', {
        type: options.type,
      });
      console.log('Metadata retrieved successfully:', result);
    } catch (error) {
      console.error('Error retrieving metadata:', error);
    }
  });

program
  .command('http-request')
  .description('Makes an HTTP request to an external service.')
  .option('-u, --url <url>', 'The URL to make the request to.')
  .option('-m, --method <method>', 'The HTTP method (e.g., GET, POST).')
  .option('-d, --data <data>', 'The request body (JSON string).')
  .action(async (options) => {
    try {
      const optionsObj = {
        method: options.method,
        headers: {
          'Content-Type': 'application/json',
        },
      };

      if (options.data) {
        optionsObj.body = JSON.parse(options.data);
      }

      const result = await sfdx.http(options.url, optionsObj);
      console.log('HTTP request successful:', result);
    } catch (error) {
      console.error('Error making HTTP request:', error);
    }
  });


program.parse(process.argv);

