import Ajv from 'ajv';

/**
 * Creates a JSON schema validation function with performance optimizations.
 *
 * @param {object} schema The JSON schema to validate against.
 * @returns {function} A validation function that takes a data object and returns a boolean.
 * @throws {Error} If the schema is invalid.
 */
function createValidatedFunction(schema) {
  try {
    const ajv = new Ajv({
      allErrors: true,
      // Enable strict mode for better validation
      strict: true,
      // Use a faster JSON schema validator (if available)
      //  Consider using 'fast-json-schema' for significant performance gains.
      //  Install: npm install fast-json-schema
      //  ajv.use(require('fast-json-schema'));
    });

    const validate = ajv.compile(schema);

    return function validateData(data) {
      const valid = validate(data);
      if (!valid) {
        console.error("Validation Error:", validate.errors); // Log errors for debugging
      }
      return valid;
    };
  } catch (error) {
    throw new Error("Invalid JSON schema: " + error.message);
  }
}


