import ExcelWorkbookManager from 'excel-workbook-manager';

/**
 * Reads an XLSX file and returns the data as a JavaScript object.
 * @param {string} filePath The path to the XLSX file.
 * @returns {Promise<object>} A promise that resolves with the data as an object, or rejects with an error.
 */
async function readXlsx(filePath) {
  try {
    const workbookManager = new ExcelWorkbookManager();
    const workbook = await workbookManager.open(filePath);
    const data = await workbook.getData();
    workbookManager.close(workbook);
    return data;
  } catch (error) {
    console.error("Error reading XLSX file:", error);
    throw error;
  }
}

/**
 * Writes data to an XLSX file.
 * @param {string} filePath The path to the XLSX file.
 * @param {object} data The data to write to the file.
 * @param {string} sheetName The name of the sheet to write to.
 * @returns {Promise<void>} A promise that resolves when the file is written, or rejects with an error.
 */
async function writeXlsx(filePath, data, sheetName) {
  try {
    const workbookManager = new ExcelWorkbookManager();
    const workbook = await workbookManager.createWorkbook();
    const sheet = await workbook.createSheet(sheetName);

    // Write data to the sheet
    await sheet.write(data);

    await workbookManager.save(workbook, filePath);
    workbookManager.close(workbook);
  } catch (error) {
    console.error("Error writing XLSX file:", error);
    throw error;
  }
}

/**
 * Reads a CSV file and returns the data as an array of objects.
 * @param {string} filePath The path to the CSV file.
 * @returns {Promise<array>} A promise that resolves with the data as an array of objects, or rejects with an error.
 */
async function readCsv(filePath) {
  try {
    const fs = require('fs').promises;
    const data = await fs.readFile(filePath, 'utf8');
    const lines = data.split('\n');
    const headers = lines[0].split(',');
    const result = [];

    for (let i = 1; i < lines.length; i++) {
      const values = lines[i].split(',');
      const obj = {};
      for (let j = 0; j < headers.length; j++) {
        obj[headers[j].trim()] = values[j].trim();
      }
      result.push(obj);
    }
    return result;
  } catch (error) {
    console.error("Error reading CSV file:", error);
    throw error;
  }
}

/**
 * Writes data to a CSV file.
 * @param {string} filePath The path to the CSV file.
 * @param {array} data The data to write to the file.
 * @param {array} headers The headers for the CSV file.
 * @returns {Promise<void>} A promise that resolves when the file is written, or rejects with an error.
 */
async function writeCsv(filePath, data, headers) {
  try {
    const fs = require('fs').promises;
    const csv = require('csv-stringify');

    const csvData = {
      headers: headers,
      data: data
    };

    await new Promise((resolve, reject) => {
      csv.stringify(csvData, (err, output) => {
        if (err) {
          reject(err);
        }
        fs.writeFile(filePath, output, (err) => {
          if (err) {
            reject(err);
          }
          resolve();
        });
      });
    });
  } catch (error) {
    console.error("Error writing CSV file:", error);
    throw error;
  }
}
