```javascript
import gql from 'graphql-tag';
import { buildSchema } from 'graphql-jsonschema';

/**
 * GraphQL Schema Builder
 */
class SchemaBuilder {
  constructor() {
    this.schema = gql``; // Initialize with an empty schema
  }

  /**
   * Adds a field to the schema.
   * @param {string} fieldName The name of the field.
   * @param {object} fieldDefinition The field definition (type, args, resolve).
   */
  addField(fieldName, fieldDefinition) {
    this.schema += `
    ${this.formatFieldDefinition(fieldName, fieldDefinition)}
    `;
  }

  /**
   * Removes a field from the schema.
   * @param {string} fieldName The name of the field to remove.
   */
  removeField(fieldName) {
    this.schema = this.schema.replace(
      `\n  ${this.formatFieldDefinition(fieldName, { type: 'String' })}`, // Assuming String type for removal
      ''
    );
  }

  /**
   * Modifies a field in the schema.
   * @param {string} fieldName The name of the field to modify.
   * @param {object} newFieldDefinition The new field definition.
   */
  modifyField(fieldName, newFieldDefinition) {
    const oldField = this.schema.substring(
      this.schema.indexOf(this.formatFieldDefinition(fieldName, { type: 'String' }))
    );
    this.schema = this.schema.replace(
      oldField,
      this.formatFieldDefinition(fieldName, newFieldDefinition)
    );
  }

  /**
   * Formats a field definition into a GraphQL string.
   * @param {string} fieldName The name of the field.
   * @param {object} fieldDefinition The field definition.
   * @returns {string} The formatted field definition.
   */
  formatFieldDefinition(fieldName, fieldDefinition) {
    const type = fieldDefinition.type || 'String';
    const args = fieldDefinition.args || [];
    const resolve = fieldDefinition.resolve || null;

    let fieldString = `  ${fieldName}${args.length > 0 ? `(${args.map(arg => arg.name).join(', ')})` : ''} ${type}${resolve ? ` -> ${resolve}` : ''}`;
    return fieldString;
  }

  /**
   * Builds the GraphQL schema.
   * @returns {object} The GraphQL schema.
   */
  build() {
    try {
      const schema = buildSchema(this.schema);
      return schema;
    } catch (error) {
      console.error("Error building schema:", error);
      return null;
    }
  }
}

export default SchemaBuilder;
```

```javascript
import gql from 'graphql-tag';
import { buildSchema } from 'graphql-jsonschema';

/**
 * Creates a GraphQL schema.
 * @param {object} schemaDefinition - An object defining the GraphQL schema.
 * @returns {object} - The GraphQL schema object.
 */
function createSchema(schemaDefinition) {
  const schema = buildSchema(schemaDefinition);
  return schema;
}

/**
 * Adds a field to the schema.
 * @param {object} schema - The GraphQL schema object.
 * @param {string} type - The type of the field.
 * @param {string} name - The name of the field.
 * @param {object} [args] - The arguments of the field.
 * @param {object} [resolve] - The resolver function for the field.
 */
function addField(schema, type, name, args, resolve) {
  schema.addType(type);
  schema.addField(name, type, args, resolve);
}

/**
 * Removes a field from the schema.
 * @param {object} schema - The GraphQL schema object.
 * @param {string} name - The name of the field to remove.
 */
function removeField(schema, name) {
  schema.removeField(name);
}

/**
 * Modifies a field in the schema.
 * @param {object} schema - The GraphQL schema object.
 * @param {string} name - The name of the field to modify.
 * @param {object} [args] - The new arguments of the field.
 * @param {function} [resolve] - The new resolver function for the field.
 */
function modifyField(schema, name, args, resolve) {
  const field = schema.getField(name);
  if (field) {
    field.args = args;
    field.resolve = resolve;
  }
}

/**
 * Adds a new type to the schema.
 * @param {object} schema - The GraphQL schema object.
 * @param {string} typeName - The name of the new type.
 * @param {object} [fields] - The fields of the new type.
 */
function addType(schema, typeName, fields) {
  schema.addType(typeName, fields);
}

/**
 * Removes a type from the schema.
 * @param {object} schema - The GraphQL schema object.
 * @param {string} typeName - The name of the type to remove.
 */
function removeType(schema, typeName) {
  schema.removeType(typeName);
}

/**
 * Returns the GraphQL schema.
 * @param {object} schema - The GraphQL schema object.
 * @returns {object} - The GraphQL schema object.
 */
function getSchema(schema) {
  return schema;
}


export { createSchema, addField, removeField, modifyField, addType, removeType, getSchema };
