```javascript
const fs = require('fs').promises;
const sass = require('sass-js');
const path = require('path');

/**
 * Finds the dependencies (imported Sass files) of a given Sass file.
 *
 * @param {string} sassFilePath The path to the Sass file.
 * @returns {Promise<string[]>} A promise that resolves to an array of imported file paths.
 * @throws {Error} If the Sass file does not exist or if there is an error parsing the Sass file.
 */
async function findSassDependencies(sassFilePath) {
  try {
    const fileContent = await fs.readFile(sassFilePath, 'utf8');
    const parsedCSS = sass.parse(fileContent);
    const dependencies = [];

    function recursivelyFindImports(node) {
      if (node.type === 'block' && node.name === 'import') {
        const importPath = node.value.value;
        dependencies.push(importPath);
        recursivelyFindImports(sass.parse(importPath).body);
      }
    }

    recursivelyFindImports(parsedCSS.body);

    return dependencies;
  } catch (error) {
    throw new Error(`Error processing Sass file: ${error.message}`);
  }
}

module.exports = findSassDependencies;
