```javascript
import { MetricPoint, Metric, MetricStream } from '@datadog/js-metrics';

/**
 * Creates a buffered metrics reporter for Datadog using the HTTP API.
 *
 * @param {string} apiKey - Your Datadog API key.
 * @param {string} appKey - Your Datadog application key.
 * @param {string} hostname - The hostname of the machine reporting metrics.
 * @param {object} options - Optional configuration options.
 * @param {number} options.bufferSize - The maximum number of metric points to buffer. Defaults to 1000.
 * @param {number} options.reportingInterval - The interval at which to report metrics in milliseconds. Defaults to 5000.
 * @returns {object} - An object with a `report` method to send buffered metrics to Datadog.
 */
function createBufferedMetricsReporter(apiKey, appKey, hostname, options = {}) {
  const bufferSize = options.bufferSize || 1000;
  const reportingInterval = options.reportingInterval || 5000;

  let buffer = [];
  let intervalId;

  const report = () => {
    if (buffer.length > 0) {
      const batch = buffer.slice();
      buffer = [];

      const metricStream = new MetricStream({
        apiKey: apiKey,
        appKey: appKey,
        hostname: hostname,
      });

      batch.forEach(point => {
        metricStream.report(point);
      });

      metricStream.close();
    }
  };

  const addMetricPoint = (metric, value, tags = {}) => {
    const point = new MetricPoint({
      metric,
      value,
      tags,
    });
    buffer.push(point);

    if (!intervalId) {
      intervalId = setInterval(report, reportingInterval);
    }
  };

  return {
    addMetricPoint,
    report: () => {
      if (buffer.length > 0) {
        const batch = buffer.slice();
        buffer = [];

        const metricStream = new MetricStream({
          apiKey: apiKey,
          appKey: appKey,
          hostname: hostname,
        });

        batch.forEach(point => {
          metricStream.report(point);
        });

        metricStream.close();
      }
    },
    stop: () => {
      clearInterval(intervalId);
    }
  };
}

export default createBufferedMetricsReporter;
```

```javascript
import {
  Activity,
  Context,
  Resource,
  Span,
  Tracer,
  Provider,
  SDKOptions,
} from "@opentelemetry/occ";
import {
  NodeHttpReceiver,
  NodeHttpSender,
} from "@opentelemetry/node";

// Initialize OpenTelemetry SDK
const sdkOptions: SDKOptions = {
  serviceName: "my-web-application",
  apiURL: "https://api.opentelemetry.io/api/v1",
};

const tracer = new Tracer({
  resource: new Resource({
    attributes: {
      service: "my-web-application",
    },
  }),
});

const provider = new NodeHttpProvider(tracer);

// Register the provider
provider.register();

// Create NodeHttpReceiver and NodeHttpSender
const receiver = new NodeHttpReceiver(provider);
const sender = new NodeHttpSender(provider);

// Function to handle incoming HTTP/HTTPS requests
async function handleRequest(req: any, res: any) {
  const activity = Activity.start("http-request");
  const context = Context.get();

  try {
    // Simulate an HTTP request
    const response = await sender.send(req, context);

    activity.record("http.response.status", response.statusCode);
    activity.record("http.response.time", response.responseTime);

    console.log(`Request handled with status: ${response.statusCode}`);
    res.writeHead(200, { "Content-Type": "text/plain" });
    res.end("Hello, OpenTelemetry!");

  } catch (err) {
    activity.record("http.error.message", err.message);
    console.error("Error handling request:", err);
    res.writeHead(500, { "Content-Type": "text/plain" });
    res.end("Internal Server Error");
  } finally {
    activity.stop();
  }
}

// Example usage (replace with your actual HTTP server)
// This is a simplified example and would need to be integrated with a web framework like Express.js
// For example:
// import express from 'express';
// const app = express();
// app.get('/', handleRequest);
// app.listen(3000, () => {
//   console.log('Server listening on port 3000');
// });
```

The code initializes the OpenTelemetry SDK, sets up a tracer and provider for HTTP/HTTPS requests, and defines a `handleRequest` function to instrument incoming requests.  The `handleRequest` function starts an activity for each request, records relevant metrics (status code, response time), and handles potential errors.  The `NodeHttpReceiver` and `NodeHttpSender` are used to intercept and instrument HTTP/HTTPS requests.  The example usage shows how this could be integrated with an Express.js server.  The `Resource` is configured to include a service name for better identification of traces.  The `Context` is used to propagate tracing information across the request lifecycle.

