import { AWSProvider } from '@aws-sdk/credential-provider-core';
import { ContainerCredentialsProvider } from '@aws-sdk/credential-provider-container';
import { HttpCredentialsProvider } from '@aws-sdk/credential-provider-http';
import fetch from 'node-fetch';

/**
 * Creates an AWS credential provider that prioritizes container environment variables
 * and falls back to an HTTP source if necessary.
 *
 * @param {object} options - Configuration options for the provider.
 * @param {string[]} [options.containerEnvVars] - Array of environment variable names to check for credentials.
 * @param {string} [options.httpSourceUrl] - URL to fetch credentials from via HTTP.
 * @param {string} [options.httpSourceMethod] - HTTP method to use for fetching credentials (e.g., 'GET').
 * @returns {AWSProvider} - An AWS credential provider instance.
 * @throws {Error} - If required options are missing.
 */
export function createContainerHttpCredentialProvider(options) {
  if (!options.containerEnvVars) {
    throw new Error('containerEnvVars is required.');
  }

  const { containerEnvVars, httpSourceUrl, httpSourceMethod = 'GET' } = options;

  const containerProvider = new ContainerCredentialsProvider({
    envVars: containerEnvVars,
  });

  const httpProvider = new HttpCredentialsProvider({
    url: httpSourceUrl,
    method: httpSourceMethod,
    fetch: (url) => {
      return fetch(url);
    },
  });

  return new AWSProvider([containerProvider, httpProvider]);
}
