 * @param {string} message - The log message.
 * @param {object} [labels={}] - Optional labels to attach to the log entry.
 * @param {object} [attributes={}] - Optional attributes to attach to the log entry.
 * @param {string} [severity='info'] - The severity level of the log message (e.g., 'debug', 'info', 'warn', 'error').
 * @returns {Promise<void>} - A Promise that resolves when the log message has been sent to the collector.
 */
async function logMessage(message, labels = {}, attributes = {}, severity = 'info') {
  try {
    await Log.log({
      message: message,
      severity: severity,
      labels: labels,
      attributes: attributes,
    });
    console.log('Log message sent to OpenTelemetry Collector:', message);
  } catch (error) {
    console.error('Error logging message:', error);
    throw error;
  }
}


/**
 * Example usage:
 */

async function main() {
  try {
    // Configure the collector
    const collectorConfig = {
      serviceName: 'my-app',
      backend: 'otlp',
      backendOptions: {
        endpoint: 'http://localhost:4317', // Replace with your OTLP endpoint
      },
    };

    // Initialize the collector
    const collector = await initializeLogsCollector(collectorConfig);

    // Log a message with labels and attributes
    await logMessage('HTTP request received', { method: 'GET', path: '/users' }, { user_id: 123 }, 'info');

    // Log a warning message
    await logMessage('Database query failed', {}, { query: 'SELECT * FROM users WHERE id = 1' }, 'warn');

    // Log an error message
    await logMessage('Failed to connect to external service', {}, { service: 'external-service' }, 'error');

    //Example of aggregation (using the collector UI or a query language)
    //You would query the collector for logs with the label 'severity=error'
    console.log("Logs sent successfully. Check the OpenTelemetry Collector UI or query API for aggregated data.");

  } catch (error) {
    console.error('An error occurred:', error);
  }
}

//Run the main function
main();
