import { Editor } from '@prose/core';
import { History } from '@prose/history';

/**
 * Configures ProseMirror with undo/redo functionality.
 * @param {Editor} editor The ProseMirror editor instance.
 */
export function configureUndoRedo(editor) {
  const history = new History(editor);

  editor.commands.undo = history.undo;
  editor.commands.redo = history.redo;

  editor.dispatch.on('change', () => {
    history.push();
  });

  editor.dispatch.on('undo', () => {
    history.push();
  });

  editor.dispatch.on('redo', () => {
    history.push();
  });

  editor.dispatch.on('history', (state, action) => {
    if (action.type === 'history:push') {
      // Update the visual indicator of the current version.
      editor.container.querySelector('.version-indicator').textContent =
        `Version ${history.version}`;
    }
  });
}
