import { Collector } from '@opentelemetry/collector-js';
import { Trace } from '@opentelemetry/trace';

/**
 * Sends collected traces to the OpenTelemetry Collector.
 *
 * @param {string} collectorUrl The URL of the OpenTelemetry Collector.
 * @param {object} options Optional configuration options.
 */
async function sendTracesToCollector(collectorUrl, options = {}) {
  const collector = new Collector({
    endpoint: collectorUrl,
    ...options,
  });

  try {
    await collector.start();
    console.log(`OpenTelemetry Collector started at ${collectorUrl}`);

    // Simulate trace collection (replace with your actual trace collection logic)
    const traces = [
      new Trace({
        traceId: 'trace1',
        span: {
          spanId: 'span1',
          op: 'start',
          name: 'My Operation',
        },
      }),
      new Trace({
        traceId: 'trace2',
        span: {
          spanId: 'span2',
          op: 'start',
          name: 'Another Operation',
        },
      }),
    ];

    for (const trace of traces) {
      try {
        await collector.export(trace);
        console.log(`Successfully exported trace ${trace.traceId}`);
      } catch (error) {
        console.error(`Error exporting trace ${trace.traceId}:`, error);
        // Handle the error appropriately (e.g., retry, log, alert)
      }
    }

    // Keep the collector running for a while (e.g., 60 seconds)
    await new Promise((resolve) => setTimeout(resolve, 60000));

    await collector.stop();
    console.log('OpenTelemetry Collector stopped.');

  } catch (error) {
    console.error('Error starting or running the OpenTelemetry Collector:', error);
  }
}

export default sendTracesToCollector;
