import { createTracer, Collector } from '@opentelemetry/occ';
import { NodeHttpReceiver } from '@opentelemetry/exporters';
import { otlp } from '@opentelemetry/otlp';

async function setupOtlp() {
  const tracer = createTracer();

  const collector = new Collector({
    tracer: tracer,
  });

  const receiver = new NodeHttpReceiver({ port: 4317 });

  const otlpEndpoint = otlp.endpoint(receiver);

  await collector.start();

  console.log('OTLP receiver started on port 4317');

  return { tracer, collector, otlpEndpoint };
}


export default setupOtlp;
