/**
 * @param {import("broccoli-core").Tree} tree
 * @returns {import("broccoli-core").Tree}
 */
function regexFilter(tree) {
  const regexes = process.argv.slice(2); // Get regex patterns from command line arguments

  if (!regexes || regexes.length === 0) {
    console.warn("No regex patterns provided. No filtering will be applied.");
    return tree;
  }

  const filteredTree = {};

  for (const sourcePath in tree) {
    if (tree.hasOwnProperty(sourcePath)) {
      const sourceTree = tree[sourcePath];
      const newTree = {};

      for (const targetPath in sourceTree) {
        if (sourceTree.hasOwnProperty(targetPath)) {
          const targetTree = sourceTree[targetPath];
          const filePath = sourcePath + "/" + targetPath;

          try {
            const fileContent = fs.readFileSync(filePath, 'utf8');

            let shouldInclude = true;
            for (const regex of regexes) {
              if (util.regexMatch(fileContent, regex)) {
                shouldInclude = false;
                break;
              }
            }

            if (shouldInclude) {
              newTree[filePath] = targetTree;
            }
          } catch (error) {
            console.error(`Error reading or processing file ${filePath}:`, error);
            // Optionally, you could choose to include the file anyway, or skip it.
            // For now, we'll skip it.
          }
        }
      }

      if (Object.keys(newTree).length > 0) {
        filteredTree[sourcePath] = newTree;
      }
    }
  }

  return filteredTree;
}

// Export the plugin
module.exports = regexFilter;

