import { parse } from 'email-parser';

/**
 * Parses an email and extracts relevant information.
 *
 * @param {string} emailString The email content as a string.
 * @returns {object} An object containing the parsed email data.  Returns null if parsing fails.
 */
function parseEmail(emailString) {
  try {
    const parsed = parse(emailString);

    const emailData = {
      sender: parsed.from ? parsed.from.address : null,
      recipients: parsed.to ? parsed.to.map(to => to.address) : [],
      cc: parsed.cc ? parsed.cc.map(cc => cc.address) : [],
      bcc: parsed.bcc ? parsed.bcc.map(bcc => bcc.address) : [],
      subject: parsed.subject || null,
      body: parsed.text || parsed.html || null, // Prioritize text, then HTML
      date: parsed.date || null,
      attachments: parsed.attachments || [],
    };

    return emailData;

  } catch (error) {
    console.error("Error parsing email:", error);
    return null; // Or throw the error, depending on desired error handling
  }
}


/**
 * Example usage (demonstrates parsing a string and outputting as JSON)
 */
async function main() {
  const emailContent = `
    From: john.doe@example.com
    To: jane.doe@example.com
