    Date: Tue, 23 Apr 2024 10:00:00 -0700
    Content-Type: text/plain; charset=utf-8

    Hi Jane,

    Just a reminder about our meeting tomorrow.

    Best,
    John
  `;

  const parsedEmail = parseEmail(emailContent);

  if (parsedEmail) {
    console.log(JSON.stringify(parsedEmail, null, 2));
  } else {
    console.log("Email parsing failed.");
  }
}

