import { defineComponent, ref } from 'vue';
import { useMyStore } from '../store/index';

export default defineComponent({
  name: 'HomeView',
  setup() {
    const myStore = useMyStore();
    const count = ref(myStore.count);

    const increment = () => {
      myStore.increment();
      count.value = myStore.count;
    };

    const decrement = () => {
      myStore.decrement();
      count.value = myStore.count;
    };

    return {
      count,
      increment,
      decrement,
    };
