// This code demonstrates how to use babel-plugin-transform-flow-enums.
// Note: This code assumes you have babel configured with the plugin.
//       You'll need to install babel and the plugin:
//       npm install --save-dev @babel/core @babel/plugin-transform-flow-enums

// Example Flow enum definition
// In a real project, this would be in a .flow file.
const myEnum = {
  "color": ["red", "green", "blue"],
  "shape": ["circle", "square", "triangle"]
};


// Function to simulate the plugin's behavior (for demonstration purposes)
function transformFlowEnums(code) {
  // This is a simplified simulation.  The actual plugin does more.
  // It replaces enum definitions with their corresponding values.

  let transformedCode = code;

  // Replace enum definitions with their values.  This is a basic example.
  transformedCode = transformedCode.replace(/(\"color\":\s*\[(.*?)\])/g, (match, key, values) => {
    const valueArray = values.replace(/"/g, '').split(',').map(v => v.trim());
    return `const colorValues = [${valueArray.join(', ')}];`;
  });

  transformedCode = transformedCode.replace(/(\"shape\":\s*\[(.*?)\])/g, (match, key, values) => {
    const valueArray = values.replace(/"/g, '').split(',').map(v => v.trim());
    return `const shapeValues = [${valueArray.join(', ')}];`;
  });

  return transformedCode;
}


// Example usage:
const flowCode = `
// This is a Flow enum definition
