// };

// Example usage of the enum
function processColor(color) {
  console.log("Processing color:", color);
}

function processShape(shape) {
  console.log("Processing shape:", shape);
}

processColor("red");
processShape("circle");
`;

const transformedCode = transformFlowEnums(flowCode);

console.log(transformedCode);

// You would then use babel to transpile the transformedCode.
