/**
 * Imports necessary dependencies and authenticates with Salesforce API.
 *
 * @returns {object} An object containing the sfdxClient and organization information.
 */
async function initializeSFDXClient() {
  const sfdx = require('sfdx-client');

  try {
    const client = await sfdx.init();

    if (client) {
      return {
        client: client,
        organization: client.organization
      };
    } else {
      throw new Error('Failed to initialize sfdx client.');
    }
  } catch (error) {
    console.error('Error initializing SFDX client:', error);
    throw error; // Re-throw the error to be handled by the caller.
  }
}

module.exports = initializeSFDXClient;
