      // Simulate rich text formatting (basic example)
      let formattedContent = content.replace(/bold(\w+)/g, (match, word) => `<b>${word}</b>`);
      formattedContent = formattedContent.replace(/italic(\w+)/g, (match, word) => `<i>${word}</i>`);
      formattedContent = formattedContent.replace(/underline(\w+)/g, (match, word) => `<u>${word}</u>`);


      writeFileSync(outputFile, formattedContent, 'utf8');
      console.log(`Successfully converted ${inputFile} to ${outputFile}`);

    } catch (error) {
      console.error('Error:', error.message);
    }
  });

program.parse(process.argv);
