import * as oboe from 'oboe.js';

/**
 * Reads a JSON file and returns an object containing the data from the JSON file,
 * using the `oboe.js` library, without waiting for the stream to finish.
 *
 * @param {string} filePath The path to the JSON file.
 * @returns {Promise<object>} A promise that resolves to the parsed JSON object.
 * @throws {Error} If the file cannot be read or parsed.
 */
async function readJsonFileAsync(filePath) {
  try {
    const reader = new FileReader();

    reader.onload = (event) => {
      const jsonString = event.target.result;
      const parsedData = JSON.parse(jsonString);
      return parsedData;
    };

    reader.onerror = (error) => {
      throw new Error(`Error reading or parsing JSON file: ${error}`);
    };

    reader.readAsText(filePath);
  } catch (error) {
    console.error("Error:", error);
    throw error;
  }
}

export default readJsonFileAsync;
