import { Editor, EditorState } from '@tiptap/editor';
import { Plugin as ProsemirrorPlugin } from '@prosemirror/plugin';
import { Node as ProsemirrorNode } from '@prosemirror/model';

/**
 * A Tiptap plugin that wraps Prosemirror's editor and model.
 * @param {ProsemirrorEditor} pmEditor - The Prosemirror editor instance.
 * @returns {Plugin} - The Tiptap plugin.
 */
export function prosemirrorWrapper(pmEditor) {
  return {
    name: 'prosemirrorWrapper',
    api: {
      // Expose Prosemirror editor and model to Tiptap
      prosemirrorEditor: pmEditor,
      prosemirrorModel: pmEditor.model,
    },
    setup() {
      // Register Prosemirror nodes as Tiptap nodes
      registerProsemirrorNodes();
    },
  };

  function registerProsemirrorNodes() {
    // Register Prosemirror nodes as Tiptap nodes
    pmEditor.model.nodes.add(
      new Node(
        'prosemirrorNode',
        {
          group: 'prosemirror',
        },
        (node) => {
          return {
            type: node.type,
            data: node.data,
            // Add any other relevant data from the Prosemirror node
          };
        }
      )
    );
  }
}
