import { Widget } from '@tiptap/core';
import { Editor } from '@tiptap/editor';

/**
 * Tiptap extension for creating and managing links.
 */
export default function Link({ editor }) {
  const linkState = {
    id: null,
    url: '',
    title: '',
    target: '_blank',
  };

  const handleToggleLink = () => {
    if (editor.state.nodes.some((node) => node.type === 'link')) {
      editor.changeState((prevState) => ({
        ...prevState,
        nodes: prevState.nodes.map((node) =>
          node.type === 'link' ? 'unlink' : node.type
        ),
      }));
    } else {
      editor.changeState((prevState) => ({
        ...prevState,
        nodes: [...prevState.nodes, { type: 'link', ...linkState }],
      }));
    }
  };

  const handleAddLink = () => {
    editor.changeState((prevState) => ({
      ...prevState,
      nodes: [...prevState.nodes, { type: 'link', ...linkState }],
    }));
  };

  const handleRemoveLink = (index) => {
    editor.changeState((prevState) => ({
      ...prevState,
      nodes: prevState.nodes.filter((_, i) => i !== index),
    }));
  };

  const handleEditLink = (index) => {
    const node = editor.state.nodes[index];
    linkState.id = node.id;
    linkState.url = node.url || '';
    linkState.title = node.title || '';
    linkState.target = node.target || '_blank';

    editor.changeState((prevState) => ({
      ...prevState,
      nodes: prevState.nodes.map((n, i) =>
        i === index ? { ...n, ...linkState } : n
      ),
    }));
  };

  return {
    name: 'link',
    title: 'Link',
    icon: 'link',
    group: 'formatting',

    parseHTML() {
      return [{ tag: 'a', ...linkState }];
    },

    render() {
      const node = this.state.nodes[0];
      if (node && node.type === 'link') {
        return `<a href="${node.url}" target="${node.target}" id="${node.id}" data-tiptap-link-title="${node.title}">${node.text}</a>`;
      }
      return null;
    },

    commands: {
      toggleLink: handleToggleLink,
      addLink: handleAddLink,
      removeLink: handleRemoveLink,
      editLink: handleEditLink,
    },
  };
}
