import React, { useState, useEffect } from 'react';
import CodeMirror from '@codemirror/cm';
import { EditorView } from '@codemirror/view';
import { basicSetup } from '@codemirror/basic-setup';

const ReactCodeMirror = ({ value, onChange, options = {} }) => {
  const [view, setView] = useState(null);

  useEffect(() => {
    if (value !== null && value !== undefined) {
      const editorView = new EditorView({
        state: CodeMirror.init({
          value: value,
          ...options,
        }),
        parent: document.getElementById('react-codemirror-container'), // Ensure a container exists
      });
      setView(editorView);

      return () => {
        editorView.destroy();
      };
    } else {
      setView(null);
    }
  }, [value, options]);

  const handleonChange = (edit) => {
    if (onChange) {
      onChange(edit.changes);
    }
  };

  if (!view) {
    return <div id="react-codemirror-container" style={{ height: '400px', width: '100%' }} />;
  }

  return (
    <div id="react-codemirror-container" style={{ height: '400px', width: '100%' }}>
      <CodeMirror
        view={view}
        onChange={handleonChange}
        extensions={[basicSetup]}
        {...options}
      />
    </div>
  );
};

export default ReactCodeMirror;
```

