import React, { useState, useEffect, useRef } from 'react';
import CodeMirror from '@codemirror/cm';
import { EditorView } from '@codemirror/view';
import { javascript } from '@codemirror/lang-javascript';

function ErrorStackViewer({ errors }) {
  const [errorStack, setErrorStack] = useState(errors);
  const editorRef = useRef(null);

  useEffect(() => {
    setErrorStack(errors);
  }, [errors]);

  const handleEditorChange = (view) => {
    setErrorStack(view.state.doc.toDOM());
  };

  return (
    <div style={{ display: 'flex' }}>
      <div style={{ width: '50%', padding: '10px' }}>
        <h2>Error Stack</h2>
        <CodeMirror
          ref={editorRef}
          value={errorStack.join('\n')}
          theme="vs-dark"
          mode="javascript"
          extensions={[javascript]}
          onChange={handleEditorChange}
          style={{ width: '100%', height: '300px' }}
        />
      </div>
      <div style={{ width: '50%', padding: '10px' }}>
        <h2>Error Details</h2>
        {errorStack.length > 0 ? (
          <ul>
            {errorStack.map((error, index) => (
              <li key={index}>
                {error.message} - Line {error.line}, Column {error.column}
              </li>
            ))}
          </ul>
        ) : (
          <p>No errors to display.</p>
        )}
      </div>
    </div>
  );
}

export default ErrorStackViewer;
