        name: "my-app"
    },
    spec: {
        selector: {
            matchLabels: {
                app: "my-app"
            }
        },
        template: {
            metadata: {
                labels: {
                    app: "my-app"
                }
            },
            spec: {
                containers: [
                    {
                        name: "my-app-container",
                        image: "your-nodejs-app-image:latest", // Replace with your image
                        ports: [
                            { containerPort: 3000 } // Replace with your app's port
                        ],
                        resources: {
                            limits: {
                                cpu: "1",
                                memory: "1Gi"
                            },
                            requests: {
                                cpu: "0.5",
                                memory: "512Mi"
                            }
                        }
                    }
                ]
            }
        },
        replicas: 3
    },
    namespace: "default"
}, { dependsOn: [k8sCluster ] });

// Kubernetes Service
const appService = new kubernetes.Service("my-app-service", {
    metadata: {
        labels: {
            app: "my-app"
        }
    },
    spec: {
        selector: {
            app: "my-app"
        },
        ports: [
            {
                protocol: "TCP",
                port: 80,
                targetPort: 3000
            }
        ],
        type: "LoadBalancer" // Or ClusterIP, NodePort, etc.
    },
    namespace: "default",
    dependsOn: [appDeployment]
}, { dependsOn: [k8sCluster ] });

// Ingress (optional, for external access)
const ingress = new kubernetes.Ingress("my-app-ingress", {
    metadata: {
        annotations: {
            "kubernetes.io/ingress.class": "nginx" // Or your ingress controller
        }
    },
    spec: {
        rules: [
            {
                host: "yourdomain.com", // Replace with your domain
                http: {
                    paths: [
                        {
                            path: "/",
                            pathType: "Prefix",
                            backend: {
                                service: {
                                    name: "my-app-service",
                                    port: { number: 80 }
                                }
                            }
                        }
                    ]
                }
            }
        ]
    },
    namespace: "default",
    dependsOn: [appService]
}, { dependsOn: [k8sCluster ] });

// DNS Record
const dnsRecord = new dns.A("my-app-dns", {
    name: "yourdomain.com", // Replace with your domain
    type: "A",
    ttl: 300,
    records: [
        {
            value: pulumi.output(appService.status.loadBalancer.ingress[0].ip), // Get the LoadBalancer IP
            priority: 0
        }
    ]
});

// Export the outputs
export const clusterName = k8sCluster.name;
export const appServiceUrl = appService.status.loadBalancer.ingress[0].hostname; // Or .ip if not using LoadBalancer
export const dnsRecordName = dnsRecord.name;
export const dnsRecordValue = dnsRecord.records[0].value;
```

Key improvements and explanations:

* **Clear Structure:** The code is organized into logical sections (Kubernetes cluster, deployment, service, ingress, DNS).
* **Pulumi Project:**  Uses `pulumi.asset.Project` to properly initialize a Pulumi project.
* **Kubernetes Provider:**  Uses `@pulumi/kubernetes` for Kubernetes resource management.  The `provider` argument in `kubernetes.Cluster` is crucial and needs to be configured based on your Kubernetes environment (EKS, GKE, AKS, kind, etc.).
* **Node.js Application:**  Includes a basic Node.js application deployment with a container image placeholder.  You'll need to replace `"your-nodejs-app-image:latest"` with your actual Docker image.
* **Service Type:**  Uses `type: "LoadBalancer"` for the Kubernetes service, which is common for exposing applications externally.  You can change this to `ClusterIP`, `NodePort`, or other types as needed.
* **Ingress:**  Includes an optional Ingress resource for external access.  You'll need to configure an Ingress controller (e.g., Nginx, Traefik) in your Kubernetes cluster.
* **DNS Record:**  Creates an A record in DNS that points to the external IP address of the Kubernetes service.  It uses `pulumi.output` to dynamically retrieve the IP address after the service is created.
* **Dependencies:**  Uses `dependsOn` to ensure that resources are created in the correct order.
* **Outputs:**  Exports the cluster name, service URL, DNS record name, and DNS record value so you can easily access them after deployment.
* **Comments:**  Includes comments to explain the purpose of each section of the code.
* **Placeholder Image:**  Uses a placeholder image name.  You *must* replace this with the actual name of your Docker image.
* **Error Handling:**  This example does not include error handling.  In a production environment, you should add error handling to your code.
* **Configuration:**  The code includes placeholders for cluster configuration details (e.g., region, node size).  You'll need to configure these details based on your requirements.

To run this code:

1.  **Install Pulumi:**  Follow the instructions on the Pulumi website: [https://www.pulumi.com/docs/get-started/install/](https://www.pulumi.com/docs/get-started/install/)
2.  **Configure Kubernetes Provider:** Configure the Kubernetes provider to connect to your Kubernetes cluster.
3.  **Replace Placeholders:** Replace the placeholder values with your actual values (e.g., Docker image name, domain name).
4.  **Deploy:** Run `pulumi up` to deploy the project.

This provides a solid starting point.  You'll need to adapt it to your specific requirements and environment.  Remember to consult the Pulumi and Kubernetes documentation for more information.

```javascript
const fs = require('fs');
const path = require('path');

/**
 * Creates a Pulumi project, sets up a Kubernetes cluster, deploys a Node.js application, and configures a DNS entry.
 */
async function main() {
  const projectName = 'pulumi-k8s-nodejs-dns';
  const projectDir = path.join(__dirname, projectName);

  // 1. Create Pulumi project
  console.log(`Creating Pulumi project: ${projectName}`);
  fs.mkdirSync(projectDir, { recursive: true });
  process.chdir(projectDir);

  // 2. Create Pulumi program (main.ts)
  const mainTsContent = `
import * as k8s from "@pulumi/kubernetes";
import * as dns from "@pulumi/dns";
import * as pulumi from "@pulumi/pulumi";

const ns = new dns.PublicZone("my-pulumi-zone", {
    name: "pulumi-k8s-nodejs-dns.com",
});

const kubeconfig = pulumi.output(process.env.KUBECONFIG);

const myDeployment = new k8s.Deployment("my-nodejs-app", {
    metadata: {
        name: "my-nodejs-app"
    },
    spec: {
        selector: {
            matchLabels: {
                app: "my-nodejs-app"
            }
        },
        template: {
            metadata: {
                labels: {
                    app: "my-nodejs-app"
                }
            },
            spec: {
                containers: [
                    {
                        name: "my-nodejs-container",
                        image: "nginx:latest", // Replace with your Node.js app image
                        ports: [{ containerPort: 80 }],
                    }
                ]
            }
        }
    }
});

const myService = new k8s.Service("my-nodejs-service", {
    metadata: {
        name: "my-nodejs-service"
    },
    spec: {
        selector: {
            app: "my-nodejs-app"
        },
        ports: [{
            protocol: "TCP",
            port: 80,
            targetPort: 80
        }]
    }
});

const ingress = new k8s.Ingress("my-ingress", {
    metadata: {
        name: "my-ingress"
    },
    spec: {
        rules: [
            {
                host: "pulumi-k8s-nodejs-dns.com",
                http: {
                    paths: [
                        {
                            path: "/",
                            pathType: "Prefix",
                            backend: {
                                service: myService
                            }
                        }
                    ]
                }
            }
        ]
    }
});

export const ingressHost = ns.records.get("pulumi-k8s-nodejs-dns.com").then(record => record.data);
`;

  fs.writeFileSync(path.join(projectDir, 'main.ts'), mainTsContent);

  // 3. Create Pulumi.yaml
  const pulumiYamlContent = `
pulumi:
  name: ${projectName}
  version: 0.1.0
  description: A Pulumi project for Kubernetes deployment and DNS configuration.
  authors:
    - Your Name <your.email@example.com>
  dependencies:
    - "@pulumi/kubernetes"
    - "@pulumi/dns"
`;

  fs.writeFileSync(path.join(projectDir, 'Pulumi.yaml'), pulumiYamlContent);

  // 4. Initialize Pulumi project
  console.log(`Initializing Pulumi project: ${projectName}`);
  process.chdir('..'); // Go back to the parent directory
  const result = await new Promise((resolve, reject) => {
    const { exec } = require('child_process');
    exec('pulumi new', (error, stdout, stderr) => {
      if (error) {
        reject(error);
        return;
      }
      console.log(stdout);
      console.error(stderr);
      resolve();
    });
  });

  // 5. Deploy the application
  console.log(`Deploying application: ${projectName}`);
  process.chdir(projectDir);
  const deployResult = await new Promise((resolve, reject) => {
    const { exec } = require('child_process');
    exec('pulumi up --yes', (error, stdout, stderr) => {
      if (error) {
        reject(error);
        return;
      }
      console.log(stdout);
      console.error(stderr);
      resolve();
    });
  });

  console.log(`Application deployed successfully!`);
}

main().catch(err => {
  console.error("An error occurred:", err);
  process.exit(1);
});
