const path = require('path');
const imagemin = require('imagemin');
const imageminJpegReimager = require('imagemin-jpeg-reimager');
const imageminPngquant = require('imagemin-pngquant');
const imageminSvgo = require('imagemin-svgo');

/**
 * Minimizes an image using imagemin.
 *
 * @param {string} inputPath The path to the input image file.
 * @param {string} outputPath The path to the output minimized image file.
 * @param {string} format The desired output image format (e.g., 'jpeg', 'png').
 * @param {object} options Optional imagemin options.
 * @returns {Promise<void>} A promise that resolves when the image is minimized.
 * @throws {Error} If the input file does not exist.
 */
async function minimizeImage(inputPath, outputPath, format, options = {}) {
  if (!path.exists(inputPath)) {
    throw new Error(`Input file not found: ${inputPath}`);
  }

  const imageminOptions = {
    plugins: [
      imageminJpegReimager({ quality: 80 }), // Adjust quality as needed
      imageminPngquant({ quality: [0.65, 0.85], speed: 2 }), // Adjust quality as needed
      imageminSvgo({ plugins: [] }) // Enable SVG optimization
    ],
    ...options,
  };

  try {
    await imagemin([inputPath], {
      destination: path.dirname(outputPath),
      plugins: imageminOptions,
    });
    console.log(`Image minimized successfully to ${outputPath}`);
  } catch (error) {
    console.error(`Error minimizing image: ${error}`);
    throw error;
  }
}


module.exports = { minimizeImage };
