```javascript
import { sqldb } from 'sqldb';

/**
 * Executes a SQL query against a MySQL database using sqldb and returns a summary.
 *
 * @param {string} connectionString - The MySQL connection string.
 * @param {string} sqlQuery - The SQL query to execute.
 * @returns {Promise<object>} - A promise that resolves to an object containing the query summary.
 *                             The object includes:
 *                             - affectedRows: The number of rows affected by the query.
 *                             - insertedRows: The number of rows inserted by the query.
 *                             - updatedRows: The number of rows updated by the query.
 *                             - deletedRows: The number of rows deleted by the query.
 *                             - executionTime: The query execution time in milliseconds.
 *                             Returns null if an error occurs.
 */
async function executeQueryWithSummary(connectionString, sqlQuery) {
  try {
    const client = await sqldb.connect(connectionString);

    const result = await client.query(sqlQuery);

    const affectedRows = result.affectedRows;
    const insertedRows = result.insertedRows;
    const updatedRows = result.updatedRows;
    const deletedRows = result.deletedRows;
    const executionTime = result.executionTime;

    return {
      affectedRows,
      insertedRows,
      updatedRows,
      deletedRows,
      executionTime,
    };
  } catch (error) {
    console.error("Error executing query:", error);
    return null;
  } finally {
    if (client) {
      await client.end();
    }
  }
}

export default executeQueryWithSummary;
```

