 * @param {string} collectionId The ID of the collection.
 * @returns {Promise<CosmosClient>} A promise that resolves to the CosmosClient instance.
 * @throws {Error} If endpoint, key, databaseId, or collectionId are missing or invalid.
 */
async function createCosmosClient(endpoint, key, databaseId, collectionId) {
  if (!endpoint) {
    throw new Error('Endpoint is required.');
  }
  if (!key) {
    throw new Error('Key is required.');
  }
  if (!databaseId) {
    throw new Error('DatabaseId is required.');
  }
  if (!collectionId) {
    throw new Error('CollectionId is required.');
  }

  try {
    const client = new CosmosClient({ endpoint, key });
    return client;
  } catch (error) {
    console.error("Error creating CosmosClient:", error);
    throw error;
  }
}

export default createCosmosClient;
```

