/**
 * This function retrieves the primary email address from an Android device.
 * It uses the `android.accounts.AccountManager` class to access account information.
 *
 * @returns {Promise<string|null>} A promise that resolves to the primary email address
 *                                  or null if no primary email is found.
 */
async function getPrimaryEmail() {
  try {
    const accountManager = await require('android.accounts.AccountManager');
    const accounts = await accountManager.getAccounts();

    if (accounts && accounts.length > 0) {
      // Assuming the first account is the primary one.  This might need adjustment
      // depending on the specific Android version and configuration.
      const primaryAccount = accounts[0];
      const email = await accountManager.getAccountDetails(
        primaryAccount,
        null
      );

      if (email && email.aliases && email.aliases.length > 0) {
        return email.aliases[0]; // Return the first alias as the primary email
      } else {
        return null; // No email address found for the primary account
      }
    } else {
      return null; // No accounts found on the device
    }
  } catch (error) {
    console.error("Error getting primary email:", error);
    return null; // Handle errors gracefully
  }
}

