function uploadToFtp(ftpAddress, filePath) {
  try {
    const fs = require('fs');

    const fileContent = fs.readFileSync(filePath);

    const ftp = require('ftplib');

    const ftpClient = new ftp.FTP();
    ftpClient.connect(ftpAddress);

    ftpClient.storbinary(`STOR ${filePath}`, fileContent, (err) => {
      if (err) {
        console.error('Failed to upload to ftp:', err);
        fs.appendFile('ftplog.log', `Failed to upload to ftp: ${err}\n`, (err2) => {
          if (err2) {
            console.error('Error writing to log file:', err2);
          }
        });
        return;
      }

      console.log(`File successfully uploaded to ${ftpAddress}`);
      fs.appendFile('ftplog.log', `File successfully uploaded to ${ftpAddress}\n`, (err2) => {
        if (err2) {
          console.error('Error writing to log file:', err2);
        }
      });
    });

    ftpClient.quit();
  } catch (error) {
    console.error('An error occurred:', error);
    fs.appendFile('ftplog.log', `An error occurred: ${error}\n`, (err2) => {
      if (err2) {
        console.error('Error writing to log file:', err2);
      }
    });
  }
}

// Example usage:
const ftpAddress = "some ftp address";
const filePath = "your_file.txt";
uploadToFtp(ftpAddress, filePath);
```

