```javascript
const pycrypto = require('pycrypto');

/**
 * Encrypts a message using AES-256 with CBC mode.
 *
 * @param {string} message The message to encrypt.
 * @param {string} key The encryption key (must be 16 bytes).
 * @param {string} iv The initialization vector (must be 16 bytes).
 * @returns {string} The encrypted message as a hexadecimal string.
 * @throws {Error} If the key or IV are not the correct length.
 */
function encrypt(message, key, iv) {
  if (key.length !== 16) {
    throw new Error("Key must be 16 bytes long.");
  }
  if (iv.length !== 16) {
    throw new Error("IV must be 16 bytes long.");
  }

  const cipher = pycrypto.AES.newCipher(key);
  const encrypted = cipher.encrypt(message, iv);
  return encrypted.toString('hex');
}

/**
 * Decrypts a message encrypted with AES-256 in CBC mode.
 *
 * @param {string} encryptedMessage The encrypted message as a hexadecimal string.
 * @param {string} key The decryption key (must be 16 bytes).
 * @param {string} iv The initialization vector (must be 16 bytes).
 * @returns {string} The decrypted message.
 * @throws {Error} If the key or IV are not the correct length.
 */
function decrypt(encryptedMessage, key, iv) {
  if (key.length !== 16) {
    throw new Error("Key must be 16 bytes long.");
  }
  if (iv.length !== 16) {
    throw new Error("IV must be 16 bytes long.");
  }

  const cipher = pycrypto.AES.newCipher(key);
  const decrypted = cipher.decrypt(Buffer.from(encryptedMessage, 'hex'), iv);
  return decrypted.toString();
}


