function preventEdgeOverlap(dotString) {
  // This function takes a Graphviz dot string as input and returns a modified dot string
  // that attempts to prevent edge overlap.  It uses the `rankdir` and `splines` attributes
  // to influence the layout.  This is a heuristic approach and may not always produce
  // perfect results, but it often helps.

  const modifiedDotString = dotString.replace("rankdir=LR", "rankdir=TB"); // Try top to bottom layout
  modifiedDotString = modifiedDotString.replace("splines=always", "splines=ortho"); // Use orthogonal splines

  return modifiedDotString;
}

