import EmberObject from 'ember-object';

export default EmberObject.derive(EmberObject, {
  loadModels: function() {
    this.store.load('my-first-model', {
      params: { id: 1 }
    }).then(function(records) {
      this.firstModelRecords = records;
    });

    this.store.load('my-second-model', {
      params: { otherId: 2 }
    }).then(function(records) {
      this.secondModelRecords = records;
