```javascript
import { Driver } from '@neo4j/driver';

async function deleteAllData(uri, username, password, database) {
  const driver = new Driver(uri);

  try {
    const session = await driver.session();

    const deleteNodesQuery = 'MATCH (n) DETACH DELETE n';
    await session.run(deleteNodesQuery);

    const deleteRelationshipsQuery = 'MATCH ()-[r]->() DETACH DELETE r';
    await session.run(deleteRelationshipsQuery);

    console.log('All nodes and relationships deleted successfully.');

  } catch (err) {
    console.error('Error deleting data:', err);
  } finally {
    await session.close();
  }
}

// Replace with your Neo4j connection details
const uri = 'bolt://localhost:7687';
const username = 'neo4j';
const password = 'your_password';
const database = 'your_database';

deleteAllData(uri, username, password, database);
```

```javascript
import React, { Component } from 'react';
import { connect } from 'react-router-connect';

class MyComponent extends Component {
  render() {
    const { location } = this.props;
    const pathname = location.pathname;

    // You can extract information from the pathname to set the title
    let title = 'Default Title'; 

    if (pathname === '/home') {
      title = 'Home Page';
    } else if (pathname === '/about') {
      title = 'About Us';
    } else if (pathname.startsWith('/products/')) {
      const productId = pathname.split('/')[3]; // Extract product ID
      title = `Product ${productId}`;
    }

    return (
      <div>
        <h1>{title}</h1>
        {/* Other content */}
      </div>
    );
  }
}

const MyComponentWithRouter = connect(
  (location) => ({ location }),
  null
)(MyComponent);

export default MyComponentWithRouter;
```

