 }
});

app.on('ready',function(){
 mainWindow = new BrowserWindow({width:800, height : 600});
 mainWindow.loadUrl('file://' + __dirname + '/index.html');

 var authButton = document.getElementById("auth-button");
 authButton.addEventListener("click",function(){alert("clicked!");});

 mainWindow.openDevTools();

 mainWindow.on('closed',function(){
 mainWindow = null;
 });
});

But an error occurs as follows:
Uncaught Exception: ReferenceError: document is not defined

Can the DOM objects be accessed while building electron apps? or is there any other alternative way that can give me the required functionality?

response_prompt:
```javascript
// main.js

const { app, BrowserWindow } = require('electron');
require('crash-reporter').start();
console.log("oh yaeh!");
let mainWindow;

app.on('window-all-closed', function() {
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

app.on('ready', function() {
  mainWindow = new BrowserWindow({ width: 800, height: 600 });
  mainWindow.loadUrl('file://' + __dirname + '/index.html');

  // Accessing the DOM from the renderer process
  mainWindow.webContents.on('did-finish-load', () => {
    const authButton = mainWindow.webContents.getElementById('auth-button');
    if (authButton) {
      authButton.addEventListener('click', function() {
        alert('clicked!');
      });
    }
  });

  mainWindow.openDevTools();

  mainWindow.on('closed', function() {
    mainWindow = null;
  });
});
```

**Explanation:**

In Electron, the main process and the renderer process (where your HTML/JavaScript code runs) are separate.  Therefore, you cannot directly access the `document` object from the main process.

The solution is to use `mainWindow.webContents` to access the renderer process's content shell.  `mainWindow.webContents` provides access to the Electron `webContents` object, which represents the browser window.  From there, you can use methods like `getElementById` to find DOM elements within the loaded HTML.

The `did-finish-load` event is crucial.  It ensures that the HTML has fully loaded before you attempt to access the DOM elements.  Trying to access the DOM before it's loaded will result in errors.

The code now:

1.  Gets the `webContents` object from the `mainWindow`.
2.  Uses `webContents.getElementById('auth-button')` to find the button element in the HTML.
3.  Adds an event listener to the button in the renderer process.

