    layout: html([
      html.div({ id: 'main' }),
    ]),
    clientsideFunctions: {
      // Function to get data from the first graph
      get_data: ClientsideFunction(function(data) {
        return data; // Return the data as is
      })
    },
     callbacks: {
      // Callback to update the second graph based on the first
      'graph1_click': function(data, config) {
        // Access the data from the first graph's click event
        const clickedData = data.points[0].x; // Example: get x-value of clicked point

        // Use the clientside function to pass the data to the second graph
        const dataForGraph2 = clientside.get_data(clickedData);

        // Update the second graph's data
        config.data[1].x = dataForGraph2;
      }
    },
    data: [
      {
        labels: ['A', 'B', 'C', 'D', 'E'],
        x: [1, 2, 3, 4, 5],
        y: [2, 4, 1, 3, 5],
        type: 'scatter',
        mode: 'markers',
        name: 'Graph 1'
      },
      {
        labels: ['A', 'B', 'C', 'D', 'E'],
        x: [1, 2, 3, 4, 5],
        y: [5, 3, 2, 4, 1],
        type: 'scatter',
        mode: 'markers',
        name: 'Graph 2'
      }
    ]
  });
}

// Create the Dash app instance
const app = createDashApp();

// Render the app within the Jupyter Notebook
app.render('main');

// Example of how to access the app's elements in the notebook
// (This is for demonstration purposes and might need adjustments
