```javascript
const fs = require('fs');
const path = require('path');

function findUnusedPackages(packageJsonPath) {
  try {
    const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
    const dependencies = packageJson.dependencies || {};
    const devDependencies = packageJson.devDependencies || {};
    const installedModules = require('modules-utils').installedModules;

    const installedKeys = Object.keys(installedModules);

    const unused = [];

    for (const depName in dependencies) {
      if (!installedKeys.includes(depName)) {
        unused.push(depName);
      }
    }

    for (const devDepName in devDependencies) {
      if (!installedKeys.includes(devDepName)) {
        unused.push(devDepName);
      }
    }

    return unused;

  } catch (error) {
    console.error('Error processing package.json:', error);
    return [];
  }
}

// Example usage:
const packageJsonPath = path.join(__dirname, 'package.json'); // Adjust path if needed
const unusedPackages = findUnusedPackages(packageJsonPath);

if (unusedPackages.length > 0) {
  console.log('Unused packages:');
  console.log(unusedPackages);
} else {
  console.log('No unused packages found.');
}
```

The code reads the `package.json` file, parses it, and then uses the `modules-utils` library to get a list of installed modules. It compares the dependencies and devDependencies listed in `package.json` with the installed modules. Any dependency or devDependency that is not found in the installed modules is considered unused and added to an array.  The function returns this array of unused package names.  Error handling is included to catch potential issues with reading or parsing the `package.json` file.  The example usage shows how to call the function and print the results.  Make sure to install `modules-utils` using `npm install modules-utils`.

