// require() - Used to load modules.  It's a function call.
// It's typically used in the main application file or in modules that need to depend on other modules.
// It expects a string (the module name) as an argument and returns a promise.

// Example:
// Assume we have a module named 'myModule.js' that exports a function 'myFunction'.
// myModule.js:
// function myFunction() {
//   console.log("Hello from myModule!");
// }
// define({
//   myFunction: myFunction
// });

// main.js:
// require('myModule')  // Loads myModule.js and makes myFunction available through require.myModule.myFunction
// require('myModule').myFunction(); // Calls the function

// define() - Used to define a module. It's a function definition.
// It takes an object as an argument, where the keys of the object are the names of the exported members,
// and the values are the functions or objects that should be exported.
// It's typically used in modules that need to be loaded by other modules.

// Example:
// define({
//   myFunction: function() {
//     console.log("Hello from defined module!");
//   }
// });

// main.js:
// require('myModule') // Loads the module defined above.
// myModule.myFunction(); // Calls the exported function.



// Demo:  Illustrating the difference and usage

// moduleA.js (defined module)
function greet(name) {
  return "Hello, " + name + "!";
}

define({
  greet: greet
});

// moduleB.js (using require)
// This module depends on moduleA
function useGreeting(name) {
  const greeting = require('moduleA').greet(name);
  console.log(greeting);
}

// main.js (entry point)
require(['moduleB'], function(moduleB) {
  moduleB.useGreeting("World"); // Output: Hello, World!
});


// Another example demonstrating a simple module
// moduleC.js
function add(a, b) {
  return a + b;
}

define({
  add: add
});

// main.js
require('moduleC');
console.log(moduleC.add(5, 3)); // Output: 8
