import { get_default_app_config } from '@django/core/management/utils';

/**
 * Retrieves the current Django app configuration.
 * @returns {object} The app configuration object.
 */
const getDjangoConfig = () => {
  try {
    return get_default_app_config();
  } catch (error) {
    console.error("Error getting Django config:", error);
    return null;
  }
};

/**
 * Detects the database backend.
 * @returns {string | null} The database backend name (e.g., 'sqlite3', 'postgresql'), or null if detection fails.
 */
const detectDatabaseBackend = () => {
  const config = getDjangoConfig();

  if (!config) {
    return null;
  }

  const db_backend = config.settings.DATABASES['default'].OPTIONS.engine;

  return db_backend;
};

export default detectDatabaseBackend;
