```javascript
// network.js
export function getDataFromServer() {
  return Promise.resolve("actualData");
}

// widget.js
import { getDataFromServer } from 'network.js';

export class Widget() {
  constructor() {
    getDataFromServer("dataForWidget")
      .then(data => this.render(data));
  }

  render() {
    console.log("Rendering with:", "data");
  }
}

// test.js
import { Widget } from './widget.js';

describe("widget", function() {
  it("should render with mock data", function() {
    const mockGetDataFromServer = jest.fn().mockReturnValue(Promise.resolve("mockData"));
    // Mock the import
    global.getDataFromServer = mockGetDataFromServer;

    const widget = new Widget();

    expect(mockGetDataFromServer).toHaveBeenCalledWith("dataForWidget");
    expect(widget.render).toHaveBeenCalledWith("mockData");
  });
});
```

