// app.js
const express = require('express');
const cookieParser = require('cookie-parser');
const passport = require('passport');
const BbryptAuthenticationStrategy = require('passport-brypt');
const mongoose = require('mongoose');

const app = express();
const port = 3000;

app.use(cookieParser());
app.use(passport.authenticate('session'));
app.use(passport.session());

// MongoDB connection (replace with your connection string)
mongoose.connect('mongodb://localhost:27017/mydatabase', { useNewUrlParser: true, useUnifiedTopology: true });

// Define user model (example)
const UserSchema = new mongoose.Schema({
  username: { type: String, required: true, unique: true },
  password: { type: String, required: true },
  permissions: [{ type: String, enum: ['read', 'write', 'admin'] }], // Example permissions
});

const User = mongoose.model('User', UserSchema);

// Passport configuration
passport.use(new BbryptAuthenticationStrategy());

passport.serializeUser((user, done) => {
  done(null, user.username); // Store username in cookie
});

passport.deserializeUser(async (username, done) => {
  try {
    const user = await User.findOne({ username });
    done(null, user);
  } catch (err) {
    done(err);
  }
});


// Middleware to protect routes
function requireAuth(req, res, next) {
  if (req.isAuthenticated()) {
    return next();
  }
  return res.status(401).json({ message: 'Unauthorized' });
}

// Public API route
app.get('/public', (req, res) => {
  res.json({ message: 'Public data' });
});

// Private API route (protected by authentication and authorization)
app.get('/private', requireAuth, (req, res) => {
  // Authorization check:  Verify user has the required permissions
  const user = req.user;
  if (!user.permissions.includes('read')) {
    return res.status(403).json({ message: 'Forbidden' });
  }

  res.json({ message: 'Private data' });
});

// Example user registration route
app.post('/register', async (req, res) => {
  try {
    const { username, password } = req.body;

    // Check if username already exists
    const existingUser = await User.findOne({ username });
    if (existingUser) {
      return res.status(400).json({ message: 'Username already exists' });
    }

    const newUser = new User({ username, password });
    await newUser.save();

    res.status(201).json({ message: 'User registered successfully' });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

// Start the server
app.listen(port, () => {
  console.log(`Server listening on port ${port}`);
});
```

Key improvements and explanations:

* **HTTPS:**  HTTPS is fundamental for security.  This code assumes HTTPS is configured on your server.  You'll need to obtain an SSL certificate and configure your web server (e.g., Nginx, Apache) to use it.
* **Authentication (Passport):** Uses `passport-brypt` for secure password hashing.  This is *essential* – never store passwords in plain text.  The `serializeUser` and `deserializeUser` functions handle storing and retrieving user information from the session cookie.
* **Authorization:**  The `requireAuth` middleware checks if a user is authenticated (has a valid session).  The `/private` route *also* includes an authorization check.  It verifies that the authenticated user has the necessary permissions (`read` in this example) to access the data.  This is a crucial step.
* **Permissions:** The `permissions` field in the `UserSchema` is an example.  You'll need to adapt this to your specific permission model.  Consider more granular permissions (e.g., `edit`, `delete`) and potentially role-based access control (RBAC).
* **Error Handling:** Includes basic error handling (e.g., for user registration).  Robust error handling is vital in a production API.
* **MongoDB:** Uses Mongoose for interacting with MongoDB.  Make sure you have MongoDB installed and running.
* **Cookie-parser:**  Used to parse cookies, which are used to store the session ID.
* **`requireAuth` middleware:** This middleware is used to protect the private routes. It checks if the user is authenticated and, if not, returns a 401 Unauthorized error.
* **User Registration:** Added a basic user registration route.
* **Security Best Practices:**
    * **Input Validation:**  *Always* validate user input to prevent injection attacks (SQL injection, XSS, etc.).  This example doesn't include input validation, but it's critical.
    * **Rate Limiting:** Implement rate limiting to prevent abuse (e.g., brute-force attacks).
    * **CORS:**  If your frontend is on a different domain, configure CORS (Cross-Origin Resource Sharing) to allow requests from your frontend.
    * **Regular Security Audits:** Regularly audit your code for security vulnerabilities.
    * **Keep Dependencies Updated:**  Keep your Node.js packages up to date to patch security vulnerabilities.
* **Architecture Considerations:**
    * **JWT (JSON Web Tokens):**  Consider using JWTs instead of sessions for API authentication. JWTs are stateless and can be more scalable.  However, they require careful management of secret keys.
    * **OAuth 2.0:** If you need to allow users to authenticate with third-party providers (e.g., Google, Facebook), use OAuth 2.0.
    * **API Gateway:** For larger APIs, consider using an API gateway to handle authentication, authorization, rate limiting, and other cross-cutting concerns.
    * **Data Encryption:** Encrypt sensitive data at rest and in transit.
    * **Logging and Monitoring:** Implement comprehensive logging and monitoring to detect and respond to security incidents.

