});


// --- API Endpoint for Login (Local) ---
app.post('/login/local',
  passport.authenticate('local', { session: false }), // session: false for API
  (req, res) => {
    // Passport handles authentication.  'req.user' contains the authenticated user.
    // Send a JSON response with user data.
    res.json({ message: 'Login successful', user: req.user });
