import { Component, get } from '@ember/component';
import { action, computed, observable, disassociate } from '@ember/core/classes';
import { load, optimize } from 'ember-data';

@Component()
export default class InfiniteScroll extends Component {
  /**
   * @property {string} itemsPerPage - The number of items to load per page.
   */
  itemsPerPage = 20;

  /**
   * @property {string} collectionName - The Ember Data collection to load items from.
   */
  collectionName = 'myCollection';

  /**
   * @property {number} currentPage - The current page number.
   */
  currentPage = 1;

  /**
   * @property {number} totalItems - The total number of items in the collection.
   */
  totalItems = 0;

  /**
   * @property {Array<any>} items - The array of items to display.
   */
  items = [];

  /**
   * @property {boolean} isLoading - Whether data is currently being loaded.
   */
  isLoading = false;

  /**
   * @property {boolean} hasMore - Whether there are more items to load.
   */
  hasMore = true;

  /**
   * @computed
   * @returns {number} - The total number of pages.
   */
  get totalPages() {
    return Math.ceil(this.totalItems / this.itemsPerPage);
  }

  /**
   * @action
   * Loads the next page of items.
   */
  loadMore = action(async () => {
    if (!this.hasMore || this.isLoading) {
      return;
    }

    this.isLoading = true;

    try {
      const result = await load(this.collectionName, {
        page: this.currentPage + 1,
        pageSize: this.itemsPerPage
      });

      if (result && result.total_count > 0) {
        this.items = this.items.concat(result.records);
        this.totalItems = result.total_count;
        this.currentPage++;
        this.hasMore = result.total_count > this.itemsPerPage;
      } else {
        this.hasMore = false;
      }
    } catch (error) {
      console.error('Error loading more items:', error);
      // Handle error appropriately, e.g., display an error message to the user.
    } finally {
      this.isLoading = false;
    }
  });

  /**
   * @computed
   * @returns {boolean} - Whether the current page is not the first page.
   */
  get canLoadMore() {
    return this.currentPage > 1;
  }
}
