import { Component, amember } from '@ember/core';

@Component()
export default class InfiniteScroll extends Component {
  /**
   * @property {Array<any>} items The array of items to display.
   * @property {number} itemsPerPage The number of items to load per request.
   * @property {number} startIndex The index of the first item to display.
   * @property {number} itemsLoaded The number of items currently loaded.
   * @property {number} maxItems The maximum number of items to load.
   * @property {function} loadMore A function to load more items.
   */
  items = [];
  itemsPerPage = 10;
  startIndex = 0;
  itemsLoaded = 0;
  maxItems = 100; // Maximum number of items to load
  loadMore = (event) => {
    event.preventDefault();

    if (this.itemsLoaded >= this.maxItems) {
      return;
    }

    this.loadItems();
  };

  loadItems = async () => {
    if (this.itemsLoaded >= this.maxItems) {
      return;
    }

    const start = this.startIndex + this.itemsLoaded;
    const end = start + this.itemsPerPage;

    // Simulate an API call
    await new Promise((resolve) => setTimeout(resolve, 500));

    const newItems = Array.from({ length: this.itemsPerPage }, (_, i) => ({
      id: this.items.length + i,
      data: `Item ${this.items.length + i}`,
    }));

    this.items = this.items.concat(newItems);
    this.startIndex = end;
    this.itemsLoaded += this.itemsPerPage;
  };

  didMount() {
    this.loadItems();
  }

  render() {
    return `
      <div class="infinite-scroll-container">
        ${this.items.map((item) => `
          <div class="item ${item.id}">
            ${item.data}
          </div>
        `).join('')}
        <div class="load-more" data-load-more="${this.loadMore}">Load More</div>
      </div>
    `;
  }
}

