import lxml from 'lxml';

function findTagRecursively(xmlString, targetTag) {
  try {
    const root = lxml.fromstring(xmlString);
    const foundTags = root.xpath("//*[@type='%s']", [targetTag]);

    return foundTags;
  } catch (error) {
    console.error("Error parsing XML:", error);
    return [];
  }
}

