```javascript
import { defineComponent } from '@ember/component';
import { action, computed, observable, track } from '@ember/object';
import { EagerLoaded } from '@ember/application';

export default class MyComponent extends defineComponent(EagerLoaded) {
  @observable currentPage = '';

  @action
  setCurrentPage(page) {
    this.currentPage = page;
    this.sendGTMEvent();
  }

  @action
  sendGTMEvent() {
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push({
      'event': 'pageView',
      'page': this.currentPage
    });
  }

