```javascript
import { ScheduledExecutorService } from 'java.util.concurrent';
import { TimeUnit } from 'java.util.concurrent';

function createVirtualThreadScheduledExecutor(period, unit) {
  const executor = new ScheduledExecutorService(
    () => new java.util.concurrent.Thread(java.util.concurrent.ThreadFactory.newDefault())
  );
  executor.scheduleAtFixedRate(
    (task) => {
      task.run();
    },
    0,
    period,
    unit
  );
  return executor;
}

function runTask(taskNumber) {
  console.log(`Task ${taskNumber} running on virtual thread.`);
  // Simulate an I/O operation
  try {
    // Replace with your actual I/O operation
    Thread.sleep(1000); 
  } catch (e) {
    console.error("Error during I/O operation:", e);
  }
}

// Example usage: Schedule tasks to run every minute
const executor = createVirtualThreadScheduledExecutor(60, TimeUnit.SECONDS);

for (let i = 1; i <= 1000; i++) {
  executor.schedule(() => {
    runTask(i);
  }, i * 60 * 1000, TimeUnit.MILLISECONDS);
}

// Keep the main thread alive to allow scheduled tasks to run
// In a real application, you would have a more robust mechanism
// to keep the application running.
try {
  Thread.sleep(3600000); // Run for 1 hour
} catch (e) {
  console.error("Main thread interrupted:", e);
}
