import NextAuth from 'next-auth';
import GoogleProvider from 'next-auth/providers/google';

export default NextAuth({
  providers: [
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET,
    }),
  ],
  callbacks: {
    async session({ session, cookies }) {
      // Retrieve refresh token from cookie
      const refreshToken = cookies.get('refreshToken');

      // If refresh token exists, refresh the access token
      if (refreshToken) {
        try {
          // Make a request to your NestJS refresh-access-token API
          const response = await fetch(`${process.env.NEXT_PUBLIC_NEST_API_URL}/refresh-access-token`, {
            method: 'GET',
            headers: {
              'Cookie': `refreshToken=${refreshToken}`,
            },
          });

          if (response.ok) {
            const newAccessToken = await response.json();
            session.accessToken = newAccessToken.accessToken;
          }
        } catch (error) {
          console.error('Error refreshing access token:', error);
        }
      }

      return session;
    },
  },
});
```

