Problem: SocketUtils is @Deprecated since Spring Framework 6.
What is a proper replacement for it?
The docs only state as an alternative:

Instead of using SocketUtils to find an available local port for a server, it is recommended that you rely on a server's ability to start on a random port

Well, that's not what I want, neither can I use if, because I'm historically bound to that specific port!

response_prompt:
```javascript
import { promises as fs } from 'fs';
import { exec } from 'child_process';

async function findAvailablePort(startPort, maxRetries = 10) {
  for (let i = 0; i < maxRetries; i++) {
    const port = parseInt(startPort) + i;
    if (await isPortAvailable(port)) {
      return port;
    }
  }
  return null; // Or throw an error if no port is found
}

async function isPortAvailable(port) {
  return new Promise((resolve) => {
    const checkCommand = `netstat -ano | findstr /i "${port}"`;
    exec(checkCommand, (error, stdout, stderr) => {
      if (error) {
        resolve(true); // Assume port is available if netstat fails
      } else {
        resolve(stdout.trim() === "");
      }
    });
  });
}

// Example usage within a Spring Integration bean (replace with your actual bean)
import { BeanFactory } from 'spring-integration';
import { Component } from 'spring-integration';

@Component
class SocketConfiguration {
  @Value("${app.port}")
  private String port;

  @Bean
  public void initializeTcpPort(BeanFactory beanFactory) {
    const startPort = parseInt(this.port);
    const timeoutMillis = 120000; // 2 minutes in milliseconds

    const findPortTask = async () => {
      let availablePort = null;
      let retries = 0;

      while (availablePort === null && retries < 20) { //Added retry limit
        availablePort = await findAvailablePort(startPort, retries);
        retries++;
        if (availablePort !== null) {
          console.log(`Found available port: ${availablePort}`);
          break;
        }
        await new Promise(resolve => setTimeout(resolve, 1000)); // Wait 1 second before retrying
      }

      if (availablePort === null) {
        console.error("Failed to find an available port after multiple retries.");
        // Handle the failure appropriately (e.g., throw an exception, log an error)
      }
    };

    findPortTask();
  }
}
```

