```javascript
import * as corev1 from '@kubernetes/client-node';
import * as k8s from '@kubernetes/client-node';
import {
  v1 as v1beta1,
  AdmissionReview,
  AdmissionReviewStatus,
  V1,
} from 'k8s-types';
import {
  Reconcile,
  Client,
  KubeObject,
  KubeStatus,
  KubeCondition,
} from '@kubernetes/client-node';
import {
  metav1,
  Now,
} from 'date-fns';
import {
  fmt,
} from 'fmt';

// Assuming these are defined elsewhere, replace with your actual types
interface ebd {
  Generation: number;
  Status: {
    Conditions: KubeCondition[];
  };
}

interface ebdmanv1alpha1 {
  KubernetesvfmHealthy: string;
  ReasonError: string;
  ReasonReady: string;
  ResourceProgressing: string;
}

// Helper functions (replace with your actual implementations)
function FindStatusCondition(conditions: KubeCondition[], type: string): KubeCondition | undefined {
  return conditions.find((c) => c.Type === type);
}

function SetStatusCondition(conditions: KubeCondition[], condition: KubeCondition): void {
  const index = conditions.findIndex((c) => c.Type === condition.Type);
  if (index !== -1) {
    conditions[index] = condition;
  } else {
    conditions.push(condition);
  }
}

function conditionChanged(oldConditions: KubeCondition[], newConditions: KubeCondition[], conditionType: string): boolean {
  const oldCondition = FindStatusCondition(oldConditions, conditionType);
  const newCondition = FindStatusCondition(newConditions, conditionType);

  if (oldCondition === undefined && newCondition === undefined) {
    return false;
  }

  if (oldCondition === undefined || newCondition === undefined) {
    return true;
  }

  return (
    oldCondition.Status !== newCondition.Status ||
    oldCondition.Reason !== newCondition.Reason ||
    oldCondition.Message !== newCondition.Message
  );
}

class ebdReconciler implements Reconcile {
  constructor(private client: Client) {}

  async Reconcile(request: corev1.IClientRequest, response: corev1.IResponse) {
    const req = request.meta;
    const name = req.name;
    const namespace = req.namespace;

    try {
      const ebd: ebd = await this.client.get<ebd>('ebds', name, namespace);
      const oldConditions = ebd.Status.Conditions;

      const healthResult, err = await this.checkHealth(req, ebd);

      if (err) {
        console.error("Error checking health:", err);
        return;
      }

      if (healthResult) {
        const updatedEbd = { ...ebd };
        const updatedConditions = updatedEbd.Status.Conditions;
        if (conditionChanged(oldConditions, updatedConditions, 'KubernetesvfmHealthy')) {
          await this.client.patch<ebd>(
            'ebds',
            name,
            namespace,
            updatedEbd
          );
          console.log(`Updated ebd ${name} status`);
        }
      }
    } catch (error) {
      console.error("Error reconciling ebd:", error);
    }
  }

  async checkHealth(ctx: any, req: corev1.IClientRequest, ebd: ebd): Promise<boolean> {
    // Replace with your actual logic to check availability
    const vfmReady = true; // Example: Replace with your actual check

    const condition: KubeCondition = {
      Type: 'KubernetesvfmHealthy',
      Observebdneration: ebd.Generation,
      LastTransitionTime: Now(),
    };

    if (vfmReady) {
      condition.Status = 'True';
      condition.Reason = 'Ready';
      condition.Message = 'vfm custom resource is ready';
    } else {
      condition.Status = 'False';
      condition.Reason = 'ResourceProgressing';
      condition.Message = 'vfm custom resource is not ready';
    }

    const latestEbd: ebd = { ...ebd };
    const oldConditions = latestEbd.Status.Conditions;

    SetStatusCondition(oldConditions, condition);

    const latestEbdUpdated = { ...latestEbd };
    if (conditionChanged(oldConditions, latestEbdUpdated.Status.Conditions, 'KubernetesvfmHealthy')) {
      await this.client.patch<ebd>(
        'ebds',
        req.name,
        req.namespace,
        latestEbdUpdated
      );
    }

    return vfmReady;
  }
}

export default ebdReconciler;
