import { Platform, Application, ApplicationRequirements,
  Scene, SceneOptions,
  Group, VBox, BorderPane,
  ListView, Text,
  AnchorPane,
  javafx.geometry.Insets,
  javafx.geometry.Pos,
  javafx.scene.layout.HBox,
  javafx.scene.layout.GridPane,
  javafx.scene.layout.ColumnConstraints,
  javafx.scene.layout.RowConstraints
} from 'javafx-controls';

class App extends Application {
    public data: any[] = []; // Replace with your actual data source
    public itemWidth: number = 150;
    public itemHeight: number = 100;
    public itemSpacing: number = 10;

    public start(params: ApplicationRequirements): void {
        this.data = this.generateSampleData(10);

        const root = new BorderPane();
        root.setPadding(Insets.desktop());

        const listView = new ListView<any>();
        listView.getItems().addAll(this.data);
        listView.setItems(this.data);

        const hbox = new HBox();
        hbox.setAlignment(Pos.center());
        hbox.setPadding(Insets.top(10));
        root.setCenter(listView);

        const scene = new Scene(root, 800, 600);
        scene.setTitle("Fluid List");

        this.launchApp(scene);
    }

    private generateSampleData(count: number): any[] {
        const data: any[] = [];
        for (let i = 1; i <= count; i++) {
            data.push({ id: i, name: `Item ${i}` });
        }
        return data;
    }

    public launchApp(scene: Scene): void {
        Platform.start();
        Application.launch(this, scene);
    }
}
