```javascript
import { Application, ApplicationView, Group, VBox, BorderPane,addContainerGap,addContainerGapBinding, HBox, Label, Text, Border, Padding, Scene } from 'javafx.application';
import { SceneBinding } from 'javafx.scene';

class FluidLayout extends Application {
    public static main(args: string[]) {
        new FluidLayout().start(args);
    }

    private createFluidLayout() {
        const root = new BorderPane();
        const sceneBinding = SceneBinding.create(root);

        const vbox = new VBox();
        vbox.setAlignment(javafx.geometry.setAlignment.Center);
        vbox.setPadding(new Padding(Padding.padding(10)));

        const items = [];
        for (let i = 1; i <= 10; i++) {
            const item = new HBox();
            const label = new Label(i.toString());
            label.setPadding(new Padding(new Padding(5)));
            item.getChildren().add(label);
            items.push(item);
        }

        let currentRow = 0;
        let currentColumn = 0;
        let itemIndex = 0;

        const columnWidth = sceneBinding.width() / 3;
        const rowHeight = 50;

        const fluidLayout = (container: Group, index: number) => {
            if (index >= items.length) {
                return;
            }

            const item = items[index];
            container.getChildren().add(item);

            const itemWidth = columnWidth;
            const itemHeight = rowHeight;

            const x = currentColumn * itemWidth;
            const y = currentRow * itemHeight;

            item.setTranslateX(x);
            item.setTranslateY(y);

            currentColumn++;

            if (currentColumn > 2) {
                currentColumn = 0;
                currentRow++;
            }

            if (currentRow > 3) {
                currentRow = 0;
            }

            fluidLayout(container, index + 1);
        };

        fluidLayout(vbox, 0);

        root.setCenter(vbox);

        return sceneBinding;
    }
}
```

