```javascript
import { Canvas, rememberCanvas, rememberSize, mutableStateOf } from '@jetbrains/compose/canvas';
import { Modifier, Stroke } from 'androidx.compose.ui/modifier';
import { Color } from 'androidx.compose.ui/graphics';
import { animate, animateScroll, animateTransform } from 'kotlinx.coroutines';

@Composable
fun AnimatedHeart(size: androidx.compose.ui.unit.Size) {
    val path = remember { mutableStateOf(Path()) }
    val scale by remember { mutableStateOf(1f) }

    Canvas(modifier = Modifier.size(size)) {
        val heartPath = Path()
        heartPath.moveTo(0f, size.height / 3)
        heartPath.cubicTo(0f, 0f, size.width / 2, 0f, size.width / 2, size.height / 3)
        heartPath.cubicTo(size.width / 2, 0f, size.width, 0f, size.width, size.height / 3)
        heartPath.cubicTo(
            size.width,
            size.height * 2 / 3,
            size.width / 2,
            size.height,
            size.width / 2,
            size.height
        )
        heartPath.cubicTo(
            0f,
            size.height * 2 / 3,
            0f,
            size.height / 2,
            0f,
            size.height / 3
        )

        val stroke = Stroke(5f)

        // Animate the path drawing
        animate(
            update = {
                path.value = heartPath
            },
            animation = androidx.compose.animation.animateAndRepeatWith(
                state = scale,
                animation = androidx.compose.animation.keyframes {
                    0f to 1f
                },
                iterations = 3 // Adjust the number of iterations for the animation speed
            )
        ) {
            drawPath(
                color = Color.Red,
                path = path.value,
                style = stroke
            )
        }
    }
}
```

