request_prompt:
Wrapping a decorator from an external library with arguments - Make Caching Optional.

I'm using the cachetools library and I would like to wrap the decorator form this library and add a class self argument to enable/disable the caching at the class level e.e. MyClass(enable_cache=True)
An example usage would be something like:
class MyClass(object):
 def __init__(self, enable_cache=True):
 self.enable_cache = enable_cache
 self.cache = cachetools.LRUCache(maxsize=10)

 @cachetools.cachedmethod(operator.attrgetter('cache'))
 def calc(self, n):
 return 1*n

I'm not sure how to keep the cache as a shared self class object and allow for the enable_cache flag within my own wrapper decorator using this library.

response_prompt:
```javascript
import cachetools from 'cachetools';
import * as operator from 'operator';

class Cacheable {
  constructor(enable_cache = true) {
    this.enable_cache = enable_cache;
    this.cache = cachetools.LRUCache(maxsize=10);
  }

  static withCache(enable_cache = true) {
    return function(target, ...args) {
      return function(...args2) {
        if (target.enable_cache !== undefined) {
          target.enable_cache = enable_cache;
        }
        if (target.enable_cache) {
          return target.cache.call(target, ...args2);
        } else {
          return target(...args2);
        }
      };
    };
  }
}
```

