@Serializable
data class MyRecord(
    val title: String,
    val description: String
)

fun decodeQueryParams(url: String): MyRecord {
    val parsedUrl = parse(url).query
    val decoder = JSONDecoder()

    return try {
        decoder.decodeFromString<MyRecord>(parsedUrl)
    } catch (e: Exception) {
        println("Error decoding URL parameters: ${e.message}")
        MyRecord(title = "", description = "") // Or handle the error as needed
    }
}

fun main() {
