import * as tf from '@tensorflow/tfjs';
import * as cv2 from 'cv2';
import * as numpy from 'numpy';
import * as os from 'os';

class DataGen {
  constructor(path_input, path_mask, class_name = 'person', batch_size = 8, image_size = 128) {
    this.ids = os.listdir(path_mask);
    this.path_input = path_input;
    this.path_mask = path_mask;
    this.class_name = class_name;
    this.batch_size = batch_size;
    this.image_size = image_size;
    this.on_epoch_end();
  }

  __load__(id_name) {
    const image_path = os.path.join(this.path_input, id_name);
    const mask_path = os.path.join(this.path_mask, id_name);

    const image = cv2.imread(image_path, 1);
    const resized_image = cv2.resize(image, [this.image_size, this.image_size]);

    const mask = cv2.imread(mask_path, -1);
    const resized_mask = cv2.resize(mask, [this.image_size, this.image_size]);
    const reshaped_mask = resized_mask.reshape([this.image_size, this.image_size, 1]);

    const normalized_image = resized_image / 255.0;
    const normalized_mask = reshaped_mask / 255.0;

    return [normalized_image, normalized_mask];
  }

  __getitem__(index) {
    const id_name = this.ids[index];
    const [image, mask] = this.__load__(id_name);

    if (image && mask) {
      const images = tf.expandDims(tf.tensor(image), 0);
      const masks = tf.expandDims(tf.tensor(mask), 0);
      return [images, masks];
    } else {
      return [tf.zeros([this.image_size, this.image_size, 3]), tf.zeros([this.image_size, this.image_size, 1])];
    }
  }

  on_epoch_end() {
    // No action needed
  }

  __len__() {
    return this.ids.length;
  }
}

// Configure model
const image_size = 128;
const epochs = 100;
const batch_size = 10;
const train_steps = Math.ceil(100 / batch_size);

// Create data generators
const train_gen = new DataGen(
  "/kaggle/input/coco-2014-dataset-for-yolov3/coco2014/images/train2014",
  "/kaggle/working/mask_train_2014",
  'person',
  batch_size,
  image_size
);

const val_gen = new DataGen(
  "/kaggle/input/coco-2014-dataset-for-yolov3/coco2014/images/val2014",
  "/kaggle/working/mask_val_2014",
  'person',
  batch_size,
  image_size
);

// Define model architecture
const inputs = tf.input({ shape: [image_size, image_size, 3] });
const dropout_15 = tf.layers.dropout({ rate: 0.2, include: inputs });
const model = tf.model({ inputs, layers: [dropout_15, tf.layers.conv2d({ filters: 32, kernelSize: 3, activation: 'relu' }), tf.layers.conv2d({ filters: 32, kernelSize: 3, activation: 'relu' }), tf.layers.conv2d({ filters: 1, kernelSize: 1, activation: 'sigmoid' })] });

// Compile and train the model
const optimizer = tf.train.adam(0.001);
model.compile({ optimizer, loss: 'binary_crossentropy', metrics: ['accuracy'] });

async function trainModel() {
  for (let epoch = 0; epoch < epochs; epoch++) {
    const train_data = train_gen.get_next();
    const val_data = val_gen.get_next();

    if (train_data && val_data) {
      const [images, masks] = train_data;
      const [val_images, val_masks] = val_data;

      const loss = model.fit(images, masks, {
        epochs: 1,
        validationData: [val_images, val_masks],
        callbacks: {
          onEpochEnd: (epoch, logs) => {
            console.log(`Epoch ${epoch + 1}: Loss = ${logs.loss}, Accuracy = ${logs.acc}`);
          },
        },
      });
    } else {
      console.log(`Skipping epoch ${epoch + 1} due to data issues.`);
    }
  }
  console.log('Training complete.');
}

trainModel();
```

