// user.service.ts
import { Injectable } from '@nestjs/common';
import { Model } from '@nestjs/mongoose';
import { User } from '../models/user.model';
import { PasswordService } from '../password.service';
import { SessionService } from '../session.service';
import { findOne } from 'mongoose';
import { RpcException } from '@nestjs/microservices';
import { HttpStatus } from '@nestjs/common';

@Injectable()
export class UserService {
  constructor(
    private readonly userModel: Model<User>,
    private readonly passwordService: PasswordService,
    private readonly sessionService: SessionService,
  ) {}

  async findByEmail(email: string): Promise<User | string> {
    try {
      const user = await this.userModel.findOne({ email }).exec();
      if (!user) {
        return 'User not found!!';
      }
      return user;
    } catch (error) {
      throw new Error('Database error finding user');
    }
  }

  async login(email: string, password: string): Promise<{ user: any; token: string; refreshToken: string }> {
    try {
      const user = await this.findByEmail(email);

      if (typeof user === 'string') {
        throw new RpcException(user);
      }

      const comparePassword = await this.passwordService.comparePasswords(password, user.password);

      if (!comparePassword) {
        throw new RpcException('Invalid credentials');
      }

      const { token, refreshToken } = await this.sessionService.createSession(user._id, {
        userId: user._id,
        type: user.type,
      });

      return { user, token, refreshToken };
    } catch (error) {
      throw error; // Re-throw the error to be caught by the global exception filter
    }
  }
}

// user.controller.ts
import { Controller, Post, Body, UseGuards, Request, Response } from '@nestjs/common';
import { RpcMethod } from '@nestjs/microservices';
import { Payload } from '@nestjs/header';
import { UserService } from './user.service';
import { Login } from './dto/login.dto';
import { sendSuccess, sendError, ApiResponse } from '../utils/response.utils';
import { HttpException, HttpStatus } from '@nestjs/common';

@Controller('UserService')
export class UserController {
  constructor(private readonly userService: UserService) {}

  @RpcMethod('Login')
  async login(@Payload() payload: Login): Promise<ApiResponse> {
    try {
      const { email, password } = payload;
      const { user, token, refreshToken } = await this.userService.login(email, password);

      return sendSuccess(user, 'Log-in successful.');
    } catch (error) {
      if (error instanceof RpcException) {
        return sendError(error.message, error.getStatus());
      } else {
        return sendError('Internal Server Error', HttpStatus.INTERNAL_SERVER_ERROR);
      }
    }
  }
}

// api.gateway.controller.ts
import { Controller, Post, Body, UseGuards, Request, Response } from '@nestjs/common';
import { sendSuccess, sendError, ApiResponse } from '../utils/response.utils';
import { User } from '../models/user.model';
import { UserService } from '../user.service';
import { Login } from '../dto/login.dto';
import { findOne } from 'mongoose';
import { HttpStatus } from '@nestjs/common';

@Controller('login')
export class ApiGatewayController {
  constructor(private readonly userService: UserService) {}

  @Post()
  async login(@Body() loginData: Login): Promise<ApiResponse> {
    try {
      const user = await this.userService.login(loginData.email, loginData.password);

      return sendSuccess(user, 'Log-in successful.');
    } catch (error) {
      return sendError(error.message, HttpStatus.BAD_REQUEST);
    }
  }
}

