}

// models/user.model.ts
import { Schema, Model } from 'mongoose';

export const UserSchema = new Schema({
  email: { type: String, required: true, unique: true },
  password: { type: String, required: true },
  name: { type: String },
  phone: { type: String },
  type: { type: String, default: 'user' },
});

export const User = Model<User>(UserSchema);

// utils/response.utils.ts
export function sendSuccess(data: any, message: string = 'Success', statusCode: number = HttpStatus.OK): ApiResponse {
  return {
    status: 'success',
    statusCode,
    message,
    data,
  };
}

export function sendError(message: string, statusCode: number): ApiResponse {
  return {
    status: 'error',
    statusCode,
    message,
    data: null,
  };
}

export interface ApiResponse {
  status: 'success' | 'error';
  statusCode: number;
  message: string;
  data: any | null;
}

// filters/all-exceptions.filter.ts
import { ArgumentsHost, Catch, HttpException, HttpStatus, UseGuards } from '@nestjs/common';
import { ApiResponse } from '../utils/response.utils';

@Catch()
export class AllExceptionsFilter {
  catch(exception: any, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse();
    const status = exception instanceof HttpException ? exception.getStatus() : HttpStatus.INTERNAL_SERVER_ERROR;
    const message = exception instanceof HttpException ? exception.message : 'Internal Server Error';

    response.status(status).json(sendError(message, status));
  }
}
