```javascript
// router.js
class Router {
  constructor() {
    this.routes = [];
  }

  get(path, handler) {
    this.routes.push({ path, handler });
  }

  handleRequest(req) {
    for (const route of this.routes) {
      const match = url.parse(req.url, true);
      if (match.pathname === route.path) {
        route.handler(req, res);
        return;
      }
    }
    res.statusCode = 404;
    res.end('Not Found');
  }
}

module.exports = Router;
```

