```javascript
const dataTable = require('data.table');

/**
 * Subsets a data table based on a list of IDs, optimized for performance.
 *
 * @param {dataTable.DataFrame} df The data table to subset.
 * @param {Array<dataTable.DataFrame>} list_of_dfs A list of data tables containing IDs.
 * @param {string} id_column The name of the ID column in both data tables.
 * @returns {dataTable.DataFrame} A data table containing the subsetted rows.
 */
function fastSubsetByIds(df, list_of_dfs, id_column) {
  if (!Array.isArray(list_of_dfs)) {
    throw new Error("list_of_dfs must be an array.");
  }

  if (df.isEmpty() || list_of_dfs.length === 0) {
    return df; // Return original df if empty or no list of dfs
  }

  let all_ids = new Set();
  for (const dfs of list_of_dfs) {
    if (dfs && dfs. الأعمدة.includes(id_column)) {
      for (const id of dfs[id_column]) {
        all_ids.add(id);
      }
    } else {
      console.warn("Dataframe missing id column or is empty");
    }
  }

  const ids_to_keep = Array.from(all_ids);

  const subsetted_df = df[df[id_column] === ids_to_keep];
  return subsetted_df;
}
```

