async function oneHotEncodeTimeSeries(data, n_timesteps, n_categorical_features) {
  // Assuming 'data' is a numpy array and represents the time series data.
  // 'data' should have shape (samples, n_timesteps, n_categorical_features)

  const cat_inp = keras.layers.Input(shape=(n_timesteps, n_categorical_features), name = "categorical_input");
  const index = keras.layers.IntegerLookup();
  index.adapt(data); // Adapt the IntegerLookup layer with the data

  const encoder = keras.layers.CategoryEncoding(num_tokens=index.vocabulary_size(), output_mode = "one_hot")(cat_inp);

  return encoder;
}

