// app/authenticators/token.js
import Base from 'ember-simple-auth/authenticators/base';
import { inject as service } from '@ember/service';

export default class CustomAuthenticator extends Base {
  @service router;
  @service session;

  restore(data) {
    console.log('Restore');
    console.log(data);

    // Check if the cookie exists
    if (this.session.get('data.token')) {
      return this.session.get('data');
    }

    // If no token in session, attempt to retrieve from cookie
    const token = document.cookie.split('; ').find(cookie => cookie.startsWith('ember-simple-auth-token='));

    if (token) {
      const parts = token.split('=');
      if (parts.length === 2) {
        const cookieToken = parts[1];
        this.session.set('data.token', cookieToken);
        console.log('Token retrieved from cookie:', cookieToken);
        return this.session.get('data');
      }
    }

    throw 'no valid session data';
  }

