```javascript
import { MutableSet } from 'js-set';

class LiveSubCollection {
  constructor(originalSet, predicate) {
    this.originalSet = originalSet;
    this.predicate = predicate;
    this.set = new MutableSet();

    this.updateSet();
  }

  updateSet() {
    this.set.clear();
    for (const item of this.originalSet) {
      if (this.predicate(item)) {
        this.set.add(item);
      }
    }
  }

  get() {
    this.updateSet();
    return this.set;
  }
}

