```javascript
import * as fs from 'fs';
import * as path from 'path';
import * as tar from 'tar';
import * as stream from 'stream';
import * as util from 'util';
import * as sync from 'sync';
import * as context from 'context';
import * as io from 'stream/promises';
import * as json from 'json';
import { Client } from '@docker/node-client';

async function loadImageFromTar(cli: Client, tarFilePath: string): Promise<string, string> {
    try {
        const tarFile = fs.createReadStream(tarFilePath);
        const pr = new stream.Duplex();
        const pw = new stream.Duplex();

        tarFile.pipe(pr);
        pr.pipe(pw);

        const wg = sync.WaitGroup();
        wg.add(2);

        const imageLoadResponse = await cli.ImageLoad(context.background(), pw, false);

        const repoTag = await extractRepoTag(tarFile, pw);

        wg.wait();

        pw.destroy();

        const imageID = await getImageIDByRepoTag(cli, repoTag);

        return imageID, null;

    } catch (error) {
        return null, error as string;
    }
}

async function extractRepoTag(tarFile: stream.Readable, pw: stream.Writable): Promise<string> {
    let manifestData: string;
    let manifestHeader: tar.Header;

    for await (const header of tarFile) {
        if (header.name === 'manifest.json') {
            const data = await tarFile.read(header.size);
            manifestData = data.toString();
            break;
        }
    }

    if (!manifestData) {
        throw new Error('manifest.json not found in tar file');
    }

    try {
        const manifest = json.parse(manifestData);
        return manifest[0].RepoTags[0];
    } catch (error) {
        throw new Error('Failed to parse manifest.json: ' + error);
    }
}

async function getImageIDByRepoTag(cli: Client, repoTag: string): Promise<string> {
    try {
        const images = await cli.ImageList({ all: true });

        for (const image of images) {
            for (const tag of image.RepoTags) {
                if (tag === repoTag) {
                    return image.ID;
                }
            }
        }

        throw new Error(`image ID not found for repo tag: ${repoTag}`);
    } catch (error) {
        throw error;
    }
}
```

