// Assuming you have a way to access the camera parameters and image dimensions
// These are placeholders, replace with your actual values
const camera_fov = 61;
const image_width = 859.358;
const image_height = 484.983;
const camera_height = 91;
const pitch_angle = 94;
const yaw_angle = 0;

// Function to calculate world coordinates from pixel coordinates
function calc_position(u, v) {
    const aspect_ratio = image_width / image_height;
    const fov = (camera_fov * Math.PI) / 180;
    const y_fov = 2 * Math.atan(Math.tan(fov / 2) * Math.cos(Math.radians(pitch_angle)));
    const y_angle = Math.radians((v / image_height - 0.5) * y_fov * 180 / Math.PI + pitch_angle);
    const x_fov = 2 * Math.atan(Math.tan(fov / 2) * Math.cos(y_angle));
    const x_angle = Math.radians((u / image_width - 0.5) * x_fov * 180 / Math.PI);

    const direction = [
        -Math.sin(x_angle),
        Math.cos(x_angle) * Math.sin(y_angle),
        Math.cos(x_angle) * Math.cos(y_angle)
    ];

    const rotation_matrix = [
        [Math.cos(Math.radians(yaw_angle)), -Math.sin(Math.radians(yaw_angle)), 0],
        [Math.sin(Math.radians(yaw_angle)), Math.cos(Math.radians(yaw_angle)), 0],
        [0, 0, 1]
    ];

    const rotated_direction = [
        rotation_matrix[0][0] * direction[0] + rotation_matrix[0][1] * direction[1] + rotation_matrix[0][2] * direction[2],
        rotation_matrix[1][0] * direction[0] + rotation_matrix[1][1] * direction[1] + rotation_matrix[1][2] * direction[2],
        rotation_matrix[2][0] * direction[0] + rotation_matrix[2][1] * direction[1] + rotation_matrix[2][2] * direction[2]
    ];

    const world_coords = [
        camera_position[0] + rotated_direction[0] * camera_height / Math.tan(y_angle),
        camera_position[1] + rotated_direction[1] * camera_height / Math.tan(y_angle),
        camera_height + rotated_direction[2] * camera_height / Math.tan(y_angle)
    ];

    return world_coords;
}

// Define the camera position (replace with your actual values)
const camera_position = [-43.17687898427574, -22.89925324277859, 91];

// Function to create a GeoJSON FeatureCollection for a line
function createLineGeoJSON(coords) {
    const line = new LineString(coords);
    const geometry = {
        type: 'LineString',
        coordinates: [Array.from(line.xy)]
    };
    return { type: 'Feature', geometry };
}

// Function to create a GeoDataFrame from a list of coordinates
function createGeoDataFrame(coords, crs = 'EPSG:4326') {
    const points = coords.map(coord => ({ x: coord[0], y: coord[1] }));
    const geojson = {
        type: 'FeatureCollection',
        features: points.map(p => ({ type: 'Feature', geometry: { type: 'Point', coordinates: [p.x, p.y], crs: crs } }))
    };
    return new GeoDataFrame(geojson, crs);
}

// Calculate and plot the cardinal directions
const start_point = calc_position(429, 265);
const pitch_variation = 94; // Fixed pitch angle
const yaw_variation = 0; // Fixed yaw angle

const yaw_angles = Array.from({ length: 360 }, (_, i) => i);

const lines = [];
yaw_angles.forEach(yaw => {
    const coords = [start_point];
    for (let i = 0; i < 360; i += 10) {
        const angle = yaw + i;
        const point = calc_position(429, 265);
        coords.push(point);
    }
    lines.push(createLineGeoJSON(coords));
});

const geojson = {
    type: 'FeatureCollection',
    features: lines
};

const map = L.map([-22.9149, -43.1330], { zoom: 13 }).setView([-22.9149, -43.1330], 13);

L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
}).addTo(map);

L.geoJSON(geojson).addTo(map);

// You can add more sophisticated visualization or analysis here
