```javascript
const ftplib = require('ftplib');
const io = require('io');
const fs = require('fs');
const csv = require('csv-parser');

const FTP_SERVER = 'your_ftp_server';
const FTP_USER = 'your_ftp_user';
const FTP_PASSWORD = 'your_ftp_password';
const FTP_FILE = 'your_ftp_file.csv';
const OUTPUT_FILE = 'output.csv';

async function processCSV() {
  const ftp = new ftplib.FTP(FTP_SERVER);
  try {
    ftp.login(FTP_USER, FTP_PASSWORD);

    const csvData = new io.BytesIO();
    ftp.retrbinary(`RETR ${FTP_FILE}`, (data) => {
      csvData.write(data);
      csvData.pos = 0; // Reset position after writing
    });

    csvData.pos = 0; // Reset position before reading
    const csvStream = csv();

    csvStream.on('data', (row) => {
      // Perform calculations on each row
      const processedRow = row.map(cell => {
        // Example calculation: Convert to number if possible, otherwise return original
        const num = Number(cell);
        return isNaN(num) ? cell : num * 2; // Example: multiply by 2 if numeric
      });
      console.log(processedRow);
    });

    csvStream.on('end', () => {
      // Write the processed data to a new file
      fs.writeFile(OUTPUT_FILE, csvStream.output.toString(), (err) => {
        if (err) {
          console.error('Error writing to file:', err);
        } else {
          console.log(`Successfully wrote processed data to ${OUTPUT_FILE}`);
        }
      });
    });

    csvStream.on('error', (err) => {
      console.error('Error reading CSV data:', err);
    });

    ftp.quit();

  } catch (error) {
    console.error('FTP Error:', error);
  }
}

processCSV();
```

```javascript
const ftplib = require('ftplib');
const fs = require('fs');
const { createReadStream } = require('fs');

const FTP_SERVER = 'your_ftp_server';
const FTP_USER = 'your_ftp_user';
const FTP_PASSWORD = 'your_ftp_password';
const FTP_FILE = 'your_ftp_file.csv';
const OUTPUT_FILE = 'output.csv';

async function processCSV() {
  try {
    const ftp = new ftplib.FTP(FTP_SERVER);
    ftp.login(FTP_USER, FTP_PASSWORD);

    const csvData = new io.BytesIO();
    ftp.retrbinary('RETR ' + FTP_FILE, (data) => {
      csvData.write(data);
      ftp.quit();
    });

    const csvReader = require('csv-parser');
    const results = [];

    csvData.pipe(csvReader({ delimiter: ',' }))
      .on('data', (row) => {
        // Perform calculations on each row
        const calculatedRow = row.map((value) => {
          // Example calculation: Convert to number and square it
          const num = Number(value);
          return isNaN(num) ? value : num * num;
        });
        results.push(calculatedRow);
      })
      .on('end', () => {
        // Write the processed data to a new file
        fs.writeFileSync(OUTPUT_FILE, results.map(row => row.join(',')).join('\n'));
        console.log('CSV processing complete. Output written to', OUTPUT_FILE);
      })
      .on('error', (error) => {
        console.error('Error reading CSV data:', error);
      });

  } catch (error) {
    console.error('Error connecting to FTP or processing CSV:', error);
  }
}

processCSV();
```

