import * as Sentry from '@sentry/js';

let sentryIsBlocked = false;

async function checkSentryReachability() {
  if (!Sentry.isInitialized()) {
    console.warn("Sentry is not initialized. Cannot check reachability.");
    return;
  }

  try {
    await Sentry.captureMessage("Sentry reachability check"); // Or Sentry.captureException
    sentryIsBlocked = false;
  } catch (error) {
    sentryIsBlocked = true;
    console.error("Sentry reachability check failed:", error);
  }
}


Sentry.on('transition', (event) => {
  if (event.level === 'error') {
    checkSentryReachability();
  }
});

Sentry.on('shutdown', () => {
  // Reset the flag on shutdown to avoid false positives on next load
  sentryIsBlocked = false;
});

