```javascript
import React, { useState, useEffect, useRef } from 'react';
import { Alert, Toast } from 'react-native';
import { launchCameraAsync, launchImageLibraryAsync } from '@react-native-camera-roll/camera';
import { useCameraPermissions, useMediaLibraryPermissions } from '@react-native-camera-roll/permissions';
import { uuid } from 'uuid';

// Assuming FirebaseStorageService is defined elsewhere and has an uploadFile function
// For this example, we'll mock it
const FirebaseStorageService = {
  uploadFile: async (blob, path, setUploadStatus) => {
    // Simulate Firebase upload with a delay
    await new Promise(resolve => setTimeout(resolve, 500));
    setUploadStatus(0);
    return `https://your-firebase-storage-url/${path}`;
  },
};

// Define ImageType and MediaTypeOptions (replace with your actual definitions)
type ImageType = {
  url: string;
  type: string;
};
type MediaTypeOptions = {
  All: string;
};

function ImageSelector({
  onTakeImage,
  editImage,
  basePath,
}: {
  onTakeImage: (image: ImageType) => void;
  editImage: { url: string; type: string } | null;
  basePath: string;
}) {
  const [image, setImage] = useState<ImageType | null>(editImage ? editImage : null);
  const [showDurationErr, setShowDurationErr] = useState(false);
  const [galleryImage, setGalleryImage] = useState<any>(null); // Use any for initial state
  const [cameraPermissionInfo, requestPermission] = useCameraPermissions();
  const [mediaStatus, requestPermissionMedia] = useMediaLibraryPermissions();
  const [uploadStatus, setUploadStatus] = useState(-1);
  const video = useRef(null);
  const [status, setStatus] = useState({});

  async function verifyPermissions() {
    if (cameraPermissionInfo?.status === PermissionStatus.UNDETERMINED) {
      const permission = await requestPermission();
      return permission.granted;
    }
    if (cameraPermissionInfo?.status === PermissionStatus.DENIED) {
      Alert.alert(
        'Permission was denied',
        'Camera permissions are required to use this app.'
      );
      return false;
    }
    return true;
  }

  useEffect(() => {
    if (clearImage) {
      setImage(null);
    }
  }, [clearImage]);

  useEffect(() => {
    if (!cameraPermissionInfo?.granted) verifyPermissions();
    if (!mediaStatus?.granted) verifyGalleryPermissions();
  }, []);

  async function verifyGalleryPermissions() {
    if (mediaStatus?.status === PermissionStatus.UNDETERMINED) {
      const permission = await requestPermissionMedia();
      return permission.granted;
    }
    if (mediaStatus?.status === PermissionStatus.DENIED) {
      Alert.alert(
        'Permission was denied',
        'Gallery permissions will be needed to use this app.'
      );
      return false;
    }
    return true;
  }

  async function imageTakerHandler() {
    const hasPermission = await verifyPermissions();

    if (!hasPermission) {
      return;
    }

    const generatedFileId = uuid.v4();
    const image = await launchCameraAsync({
      mediaTypes: MediaTypeOptions.All,
      allowsEditing: true,
      quality: 0.6,
    });

    if (image.canceled) {
      setShowDurationErr(true);
      return;
    }

    if (image.assets) {
      try {
        const uri = image.assets[0].uri;

        const blob = await new Promise((resolve, reject) => {
          const xhr = new XMLHttpRequest();
          xhr.onload = function () {
            resolve(xhr.response);
          };
          xhr.onerror = function () {
            reject(new TypeError('Network request failed'));
          };
          xhr.responseType = 'blob';
          xhr.open('get', uri, true);
          xhr.send(null);
        });

        const downloadUrl = await FirebaseStorageService.uploadFile(
          blob as Blob,
          `${basePath}/${generatedFileId}`,
          setUploadStatus
        );
        setImage({ url: downloadUrl, type: image.assets[0].type! });
        onTakeImage({ url: downloadUrl, type: image.assets[0].type! });
      } catch (error: any) {
        console.log(error?.message, 'downloadImageurl error');
      } finally {
        Toast.show({
          type: 'congrats',
          text1: 'your blob',
          text2: 'has completed',
        });
      }
    }
  }

  async function imageSelectorHandler() {
    setShowDurationErr(false);
    setGalleryImage(null);
    const hasPermissionforGallery = await verifyGalleryPermissions();
    if (!hasPermissionforGallery) {
      return;
    }

    const generatedFileId = uuid.v4();
    const galleryImage = await launchImageLibraryAsync({
      mediaTypes: MediaTypeOptions.All,
      allowsEditing: true,
      quality: 0.6,
    });

    if (galleryImage.canceled || !galleryImage.assets || galleryImage.assets.length === 0) {
      setShowDurationErr(true);
      return;
    }

    if (galleryImage.assets[0].duration && galleryImage.assets[0].duration > 150000) {
      setShowDurationErr(true);
      return;
    }

    if (galleryImage.assets) {
      try {
        const uri = galleryImage.assets[0].uri;

        const blob = await new Promise((resolve, reject) => {
          const xhr = new XMLHttpRequest();
          xhr.onload = function () {
            resolve(xhr.response);
          };
          xhr.onerror = function () {
            reject(new TypeError('Network request failed'));
          };
          xhr.responseType = 'blob';
          xhr.open('get', uri, true);
          xhr.send(null);
        });

        const downloadUrl = await FirebaseStorageService.uploadFile(
          blob as Blob,
          `${basePath}/${generatedFileId}`,
          setUploadStatus
        );
        setGalleryImage({ url: downloadUrl, type: galleryImage.assets[0].type! });
        onTakeImage({ url: downloadUrl, type: galleryImage.assets[0].type! });
      } catch (error: any) {
        console.log(error?.message, 'downloadImageurl error');
      }
    }
  }

  let imagePreview = (
    <Image
      source={{ uri: image?.url }}
      style={{ width: 200, height: 200 }}
    />
  );

  if (image) {
    imagePreview = (
      <Image
        source={{ uri: image.url }}
        style={{ width: 200, height: 200 }}
      />
    );
  }

  if (galleryImage) {
    if (galleryImage.type === 'image') {
      imagePreview = (
        <Image
          source={{ uri: galleryImage.url }}
          style={{ width: 200, height: 200 }}
        />
      );
    } else if (galleryImage.type === 'video') {
      imagePreview = (
        <Video
          source={{ uri: galleryImage.url }}
          style={{ width: 200, height: 200 }}
          controls={false}
        />
      );
    }
  }

  return (
    <>
      {imagePreview}
      {uploadStatus > 0 && (
        <Text>Uploading...</Text>
      )}
      {showDurationErr && (
        <Text>
          Something went wrong, if video is longer than allotment of 2.5 minutes, please
          trim first.
        </Text>
      )}
    </>
  );
}

// Placeholder for Image and Video components (replace with your actual components)
const Image = ({ source, style }) => <View style={style} />;
const Video = ({ source, style }) => <View style={style} />;

// Placeholder for Text component
const Text = ({ children }) => <Text style={{}}> {children}</Text>;

// Placeholder for View component
const View = ({ style, children }) => <View style={style}>{children}</View>;

// Placeholder for Alert component
const Alert = ({ title, message }) => {
  Alert.alert(title, message);
};

// Placeholder for Toast component
const Toast = ({ text1, text2 }) => {
  Toast.show({ type: 'success', text1, text2 });
};

