const smtplib = require('smtplib');
const MIMEText = require('mime-types'). MIMEText;
const MIMEBase = require('mime-base'). MIMEBase;
const encoders = require('encoders');

async function sendEmailWithAttachment(sender_address, sender_pass, receiver_address, mail_content, file_path) {
  try {
    const session = smtplib.createConnection('-----', 587);
    session.starttls();
    await session.login(sender_address, sender_pass);

    const message = new MIMEText(mail_content, 'plain');

    const attach_file_name = 'temp.txt';
    const attach_file = require('fs').createReadStream(file_path);

    const payload = new MIMEBase('application', 'octate-stream');
    payload.set_payload(await attach_file.read());
    encoders.encode_base64(payload);
    payload.add_header('Content-Disposition', `attachment; filename="${attach_file_name}"`);

    message.attach(payload);

    const text = message.asString();
    await session.sendmail(receiver_address, text);
    session.end();
    console.log('Mail Sent');
  } catch (error) {
    console.error('Error sending email:', error);
  }
}

// Example usage (replace with your actual values)
