```javascript
import {
  Properties,
  Session,
  Authenticator,
  PasswordAuthentication,
  MimeMessage,
  InternetAddress,
  Message,
  BodyPart,
  MimeMultipart
} from 'javax.mail';

class SendEmailInformation {
  constructor(emailAddress, password, smtpServer, smtpPort, toEmail, subject, message) {
    this.emailAddress = emailAddress;
    this.password = password;
    this.smtpServer = smtpServer;
    this.smtpPort = smtpPort;
    this.toEmail = toEmail;
    this.subject = subject;
    this.message = message;
  }
}

class EmailService {
  sendEmail(sendEmailInformation) {
    try {
      const fromEmail = sendEmailInformation.emailAddress;
      const password = sendEmailInformation.password;
      const toEmail = sendEmailInformation.toEmail;
      const smtpServer = sendEmailInformation.smtpServer;
      const smtpPort = sendEmailInformation.smtpPort;
      const subject = sendEmailInformation.subject;
      const message = sendEmailInformation.message;

      const props = new Properties();
      props.put("mail.smtp.host", smtpServer);
      props.put("mail.smtp.port", smtpPort);
      props.put("mail.smtp.starttls.enable", "true");
      props.put("mail.smtp.auth", "true");

      const auth = new Authenticator() {
        protected PasswordAuthentication getPasswordAuthentication() {
          return new PasswordAuthentication(fromEmail, password);
        }
      };

      Session session = Session.getInstance(props, auth);

      const msg = new MimeMessage(session);
      msg.addHeader("Content-type", "text/HTML; charset=UTF-8");
      msg.addHeader("format", "flowed");
      msg.addHeader("Content-Transfer-Encoding", "8bit");

      msg.setFrom(new InternetAddress(fromEmail));
      msg.setReplyTo(new InternetAddress(toEmail));
      msg.setSubject(subject, "UTF-8");
      msg.setRecipients(Message.RecipientType.TO, new InternetAddress[]{toEmail});

      const messageBodyPart = new BodyPart();
      messageBodyPart.setText(message);

      const multipart = new MimeMultipart();
      multipart.addBodyPart(messageBodyPart);

      msg.setContent(multipart);

      const transport = session.getTransport("smtp");
      transport.connect();
      transport.sendMessage(msg, msg.getRecipients(Message.RecipientType.TO));
      transport.close();
    } catch (e) {
      console.error("Error sending email:", e);
      throw e;
    }
  }
}

@RestController
class EmailController {
  constructor() {}

  @PostMapping("/send-email")
  public SentEmail sendEmail(@RequestBody SendEmailInformation sendEmailInformation) {
    const emailService = new EmailService();
    return emailService.sendEmail(sendEmailInformation);
  }
}

class SentEmail {
  constructor(status, message) {
    this.status = status;
    this.message = message;
  }
}

class CouldNotSendEmailException extends Error {}
```

