```javascript
import { poll } from 'libpoll';

/**
 * Sends ICMPv6 Neighbor Solicitations on Linux using asynchronous I/O and poll.
 *
 * @param {Array<string>} nextHops An array of next hop IPv6 addresses.
 * @param {Array<string>} interfaces An array of interface names to send solicitations on.
 * @param {number} interval The interval between sending solicitations in milliseconds.
 * @returns {Promise<void>} A promise that resolves when the process is finished.
 */
async function sendNeighborSolicitations(nextHops, interfaces, interval) {
  const sockets = {};

  for (const interface of interfaces) {
    sockets[interface] = {
      socket: null,
      config: {
        fd: 3,
        nonblocking: true,
        icmp6Filter: true,
        dontRoute: true,
        ipv6MulticastHops: 1,
        ipv6UnicastHops: 1,
        ipv6RecvHopLimit: 1,
      },
    };
  }

  async function createSocket(interface) {
    const socket = socket(PF_INET6, SOCK_RAW, IPPROTO_ICMPV6);
    if (!socket) {
      console.error(`Failed to create socket for ${interface}`);
      return null;
    }

    for (const key in sockets[interface].config) {
      socket.setsockopt(key, sockets[interface].config[key]);
    }

    socket.bind({
      family: AF_INET6,
      addrIndex: interfaces.indexOf(interface),
    });

    return socket;
  }

  async function sendSolicitation(interface, targetAddress) {
    if (!sockets[interface].socket) {
      sockets[interface].socket = await createSocket(interface);
      if (!sockets[interface].socket) {
        return;
      }
    }

    const solicitation = createSolicitationPacket(interface, targetAddress);

    const result = await socketWrite(sockets[interface].socket, solicitation);

    if (result === -1) {
      console.error(`Failed to send solicitation on ${interface}`);
      return;
    }
  }

  async function receiveData(interface) {
    if (!sockets[interface].socket) {
      return null;
    }

    const buffer = Buffer.alloc(64); // Adjust buffer size as needed
    const bytesRead = await socketRead(sockets[interface].socket, buffer);

    if (bytesRead > 0) {
      const receivedData = buffer.slice(0, bytesRead);
      // Process received data (e.g., check for ICMPv6 Neighbor Advertisement)
      console.log(`Received data on ${interface}:`, receivedData.toString('hex'));
      return receivedData;
    }

    return null;
  }

  async function pollForEvents() {
    const readySockets = [];
    for (const interface in sockets) {
      if (sockets[interface].socket && sockets[interface].socket.isReady()) {
        readySockets.push(interface);
      }
    }

    for (const interface of readySockets) {
      const received = await receiveData(interface);
      if (received) {
        // Process received advertisement
        console.log(`Advertisement received on ${interface}`);
        // You can add logic here to handle the advertisement
      }
    }
  }

  async function socketWrite(socket, data) {
    return new Promise((resolve, reject) => {
      socket.write(data, (error) => {
        if (error) {
          console.error(`Error writing to socket: ${error}`);
          resolve(-1);
          return;
        }
        resolve(0);
      });
    });
  }

  async function socketRead(socket, buffer) {
    return new Promise((resolve, reject) => {
      socket.read(buffer, (error, bytesRead) => {
        if (error) {
          console.error(`Error reading from socket: ${error}`);
          resolve(-1);
          return;
        }
        resolve(bytesRead);
      });
    });
  }

  function createSolicitationPacket(interface, targetAddress) {
    // Construct ICMPv6 Neighbor Solicitation packet
    const sourceAddress = getInterfaceAddress(interface);
    const targetAddress = targetAddress;

    const packet = Buffer.alloc(156); // Minimum size for ICMPv6 Neighbor Solicitation

    // Fill in the packet fields
    packet.writeUInt16BE(0x5055, 0); // ICMPv6 type and code
    packet.writeUInt16BE(0x0101, 2); // ICMPv6 echo request
    packet.writeUInt16BE(0x0000, 4); // ICMPv6 checksum
    packet.writeUInt8(0x00, 6); // ICMPv6 hop limit
    packet.writeUInt8(0x00, 7); // ICMPv6 payload length
    packet.write(sourceAddress, 8); // Source address
    packet.write(targetAddress, 8 + 16); // Target address
    return packet;
  }

  function getInterfaceAddress(interface) {
    // Get IPv6 address of the interface
    const ifaddr = ifconfig(interface);
    if (ifaddr) {
      return ifaddr.toUpperCase();
    } else {
      console.error(`Could not get address for interface ${interface}`);
      return 'fe80::1'; // Default link-local address
    }
  }

  // Main loop
  let solicitationCount = 0;
  while (true) {
    for (const interface of interfaces) {
      if (solicitationCount % 5 === 0) { // Send every 5 iterations
        const targetAddress = '2001:db8:1::1'; // Replace with your target address
        sendSolicitation(interface, targetAddress);
      }
    }

    await pollForEvents();
    await new Promise((resolve) => setTimeout(resolve, interval));
    solicitationCount++;
  }
}
```

