const smtplib = require('smtplib');

async function sendEmail(senderEmail, recipientEmails, subject, body, password) {
  try {
    const context = require('tls').createDefaultContext();

    const smtp = new smtplib.SMTP('smtp.gmail.com', 465);
    smtp.set_context(context);
    await smtp.login(senderEmail, password);

    const message = {
      from: senderEmail,
      to: recipientEmails.join(', '),
      subject: subject,
      text: body,
    };

    await smtp.send(message);
    console.log('Email sent successfully!');
  } catch (error) {
    console.error('Error sending email:', error);
  } finally {
    try {
      await smtp.quit();
    } catch (e) {
      console.error("Error quitting SMTP connection:", e);
    }
  }
}

