    const srv = await ConnectToGmailAPI();
    const msg = await SendEmail(srv, "Test", "This is a test sending", "REDACTED@gmail.com");
    console.log('Email sent successfully:', msg);
  } catch (error) {
    console.error('An error occurred:', error);
  }
}

main();
