```javascript
// @store/theme.ts
import { useState, useEffect } from 'react';

export interface Theme {
  light: boolean;
  dark: boolean;
}

export const ThemeContext = React.createContext<Theme | undefined>(undefined);

export const ThemeProvider = ({ children }: { children: React.ReactNode }) => {
  const [theme, setTheme] = useState<Theme>({ light: false, dark: false });

  useEffect(() => {
    const storedTheme = localStorage.getItem('theme');
    if (storedTheme) {
      const parsedTheme = JSON.parse(storedTheme);
      setTheme(parsedTheme);
      document.body.classList.remove('light', 'dark');
      document.body.classList.add(parsedTheme.light ? 'light' : 'dark');
    } else {
      localStorage.setItem('theme', JSON.stringify({ light: false, dark: true }));
      document.body.classList.add('dark');
    }

    return () => {
      document.body.classList.remove('light', 'dark');
    };
  }, []);

  const toggle = () => {
    setTheme((prevTheme) => ({
      light: !prevTheme.light,
      dark: !prevTheme.dark,
    }));
    localStorage.setItem('theme', JSON.stringify(theme));
  };

  return (
    <ThemeProvider.Provider value={theme}>
      {children}
    </ThemeProvider.Provider>
  );
};
```

