}

const GlobalContent = ({ children }: GlobalContentProps) => {
  useEffect(() => {
    // This useEffect is to ensure the theme is applied to the body
    // after the component mounts.  This helps avoid hydration issues.
    const { theme } = useContext(ThemeContext);
    document.body.classList.set(theme);
  }, [theme]);

  return (
