```javascript
import { WebClient } from '@spring/webflux';

async function main() {
  const webClient = WebClient.create();

  const threadContext = webClient.context();

  // Set a value in the thread context
  threadContext.put('myKey', 'myValue');

  try {
    const response = await webClient.get('https://example.com');

    // Access the value from the thread context in the wiretap log
    const myValue = threadContext.get('myKey');
    console.log('Value from thread context:', myValue);

    // Optionally, log the thread context for debugging
    console.log('Thread Context:', threadContext.toString());

  } catch (error) {
    console.error('Error:', error);
  }
}

main();
```

The provided code demonstrates how to set and retrieve a value from the `threadContext` using Spring Webflux's `WebClient` and how this value can be accessed within the wiretap logs.  The `threadContext.put()` method is used to store the value, and `threadContext.get()` is used to retrieve it.  The `toString()` method can be used to inspect the entire thread context.  The example also includes error handling.  The key is that the `threadContext` is accessed within the same thread as the `WebClient` request, ensuring that the value is available when the wiretap logs are generated.

```javascript
import { WebClient } from '@spring/webflux';

async function main() {
  const webClient = WebClient.create();

  const threadContext = webClient.build().context();

  // Set a value in the thread context
  threadContext.put('myKey', 'myValue');

  // Example WebClient request
  try {
    const response = await webClient.get('https://httpbin.org/get')
      .exchange()
      .subscribe({
        next: (response) => {
          console.log('Response received:', response);
        },
        error: (error) => {
          console.error('Error:', error);
        },
        complete: () => {
          // Access the thread context from the subscribe callback
          const value = threadContext.get('myKey');
          console.log('Value from thread context:', value);
        }
      });
  } catch (e) {
    console.error("Error during request:", e);
  }
}

main();
```

```javascript
const fs = require('fs');
const path = require('path');
const log4j2 = require('log4j2');

// Initialize Log4j2
log4j2.init();

function processDirectory(folderPath) {
  const files = fs.readdirSync(folderPath);

  for (const file of files) {
    const filePath = path.join(folderPath, file);
    const stats = fs.statSync(filePath);

    if (stats.isFile()) {
      const fileExtension = path.extname(file).toLowerCase();
      let logFileName = path.basename(file, fileExtension) + '_' + fileExtension + '.log';
      const logFilePath = path.join(folderPath, logFileName);

      // Configure Log4j2 appender for the current file
      log4j2.addAppender(new log4j2.appender.FileAppender({
        file: logFilePath,
        append: true,
        encoding: 'UTF-8'
      }));

      // Get file content
      try {
        const fileContent = fs.readFileSync(filePath, 'utf8');
        log4j2.debug(`Processing file: ${file}, Log file: ${logFileName}`);
        log4j2.info(`File content: ${fileContent}`); // Log the content (consider limiting for large files)
      } catch (err) {
        log4j2.error(`Error reading file ${file}: ${err.message}`);
      }
    }
  }
}

// Example usage:
const folderPath = '/path/to/your/folder'; // Replace with your folder path
processDirectory(folderPath);
```

