```javascript
/**
 * Demonstrates the difference between exchange and retrieve methods in Micronaut HttpClient.
 *
 * @returns {void}
 */
function demonstrateExchangeVsRetrieve() {

  const http = require('micronaut-http-client').Http;

  // Example URL
  const url = 'https://jsonplaceholder.typicode.com/posts/1';

  // --------------------------------------------------------------------------
  // Exchange:  Used for POST, PUT, PATCH, DELETE, and other methods.
  // It allows you to send data in the request body.
  // --------------------------------------------------------------------------

  async function exchangeExample() {
    try {
      const client = http.createClient();

      const requestBody = {
        title: 'foo',
        body: 'bar',
        userId: 1,
      };

      const response = await client.exchange(
        url,
        {
          method: 'POST', // Explicitly set the method
          body: JSON.stringify(requestBody),
          contentType: 'application/json'
        }
      );

      console.log('Exchange Response Status:', response.status);
      console.log('Exchange Response Body:', response.body.toString()); // Convert to string for display

    } catch (error) {
      console.error('Exchange Error:', error);
    }
  }

  // --------------------------------------------------------------------------
  // Retrieve: Used for GET requests.  It automatically handles the request body.
  // --------------------------------------------------------------------------

  async function retrieveExample() {
    try {
      const client = http.createClient();

      const response = await client.retrieve(url);

      console.log('Retrieve Response Status:', response.status);
      console.log('Retrieve Response Body:', response.body.toString()); // Convert to string for display

    } catch (error) {
      console.error('Retrieve Error:', error);
    }
  }


  exchangeExample();
  retrieveExample();
}

demonstrateExchangeVsRetrieve();
```

