```javascript
import * as client from "@docker/node-client";
import * as os from "os";
import * as fs from "fs";
import * as io from "io";
import * as sync from "sync";
import * as context from "context";

async function main() {
    try {
        // Set up Docker client
        const cli = client.newClientWithOpts(client.FromEnv, client.WithAPIVersionNegotiation());

        // Path to your tar file
        const tarFilePath = "mongo.tar";

        const repoTag = await loadImageFromTar(cli, tarFilePath);
        console.log("RepoTag:", repoTag);

        // Get the image ID
        const imageID = await getImageIDByRepoTag(cli, repoTag);
        console.log("Image ID:", imageID);

    } catch (error) {
        console.error("Error:", error);
    }
}

async function loadImageFromTar(cli: client.Client, tarFilePath: string): Promise<string> {
    try {
        const tarFile = fs.createReadStream(tarFilePath);
        const pr = new io.Pipe();
        const tr = io.TeeReader(tarFile, pr);

        const wg = new sync.WaitGroup();
        const errChan1 = new Promise<Error>((resolve, reject) => {
            wg.add(1);
            cli.ImageLoad(context.background(), tr, false, (err, response) => {
                wg.done();
                if (err) {
                    reject(err);
                } else {
                    resolve(response);
                }
            });
        });

        await new Promise<void>((resolve) => {
            pr.on('data', (data) => {
                // Process data from tar file
                console.log("Tar data:", data.toString());
            });
            pr.on('end', () => {
                console.log("Tar file read complete");
                resolve();
            });
        });

        const imageLoadResponse = await errChan1;
        if (imageLoadResponse.err) {
            throw imageLoadResponse.err;
        }

        return imageLoadResponse.image.RepoTag;

    } catch (error) {
        console.error("Error loading image from tar:", error);
        throw error;
    }
}

async function getImageIDByRepoTag(cli: client.Client, repoTag: string): Promise<string> {
    try {
        const image = await cli.getImage(repoTag);
        return image.ID;
    } catch (error) {
        console.error("Error getting image ID:", error);
        throw error;
    }
}

main();
```

