```javascript
const LinkedIn = require('linkedin-oauth2-server').LinkedIn;
const passport = require('passport');
const linkedinStrategy = require('passport-linkedin-oauth2').Strategy;
const express = require('express');
const app = express();

// Replace with your actual database connection
const mongoose = require('mongoose');

// Define your user model (example)
const UserSchema = new mongoose.Schema({
  name: String,
  email: String,
  accessToken: String,
  refreshToken: String,
  type: String
});
const User = mongoose.model('User', UserSchema);

// Configure Passport
passport.use(
  new linkedinStrategy(
    {
      clientID: process.env.LINKEDIN_CLIENT_ID,
      clientSecret: process.env.LINKEDIN_CLIENT_SECRET,
      callbackURL: 'http://localhost:5000/server/api/users/linkedin/callback',
      scope: ['openid', 'profile', 'email']
    },
    async (accessToken, refreshToken, done) => {
      try {
        const user = await LinkedIn.getProfile({
          client_id: process.env.LINKEDIN_CLIENT_ID,
          client_secret: process.env.LINKEDIN_CLIENT_SECRET,
          access_token: accessToken
        });

        const name = user.name.formattedName;
        const email = user.email;

        let existingUser = await User.findOne({ email: email });

        if (existingUser) {
          return done(null, existingUser);
        }

        const newUser = new User({
          name: name,
          email: email,
          accessToken: accessToken,
          refreshToken: refreshToken,
          type: 'linkedin'
        });

        await newUser.save();
        return done(null, newUser);
      } catch (err) {
        console.error(err);
        return done(err, false);
      }
    }
  )
);

module.exports = app;
```

