import {
  document,
  view,
  Axis,
  KPI,
  Mark,
  Scale,
  layer,
} from "@deneb/core";
import {
  LinearScale,
  LinearChannelScale,
} from "@deneb/scales";

document.addEventListener("DOMContentLoaded", () => {
  const width = 600;
  const height = 400;

  const data = [
    { year: 2020, value: 10 },
    { year: 2021, value: 15 },
    { year: 2022, value: 8 },
    { year: 2023, value: 12 },
  ];

  const xValue = "year";
  const yValue = "value";

  const xScale = new LinearScale({
    domain: [Math.min(...data.map((d) => d[xValue])), Math.max(...data.map((d) => d[xValue]))],
    range: [0, width],
  });

  const yScale = new LinearScale({
    domain: [0, Math.max(...data.map((d) => d[yValue])) * 1.1],
    range: [height, 0],
  });

  const mark = {
    type: "line",
    x: xValue,
    y: yValue,
    scale: {
      x: xScale,
      y: yScale,
    },
  };

  const kpi = {
    type: "KPI",
    value: data[data.length - 1][yValue],
    label: "Value",
  };

  const axisX = new Axis({
    field: xValue,
    scale: xScale,
    label: {
      text: "Year",
    },
  });

  const axisY = new Axis({
    field: yValue,
    scale: yScale,
    label: {
      text: "Value",
    },
  });

  const viewDefinition = {
    marks: [
      mark,
    ],
    x: {
      field: xValue,
      type: "value",
      scale: xScale,
    },
    y: {
      field: yValue,
      type: "value",
      scale: yScale,
    },
    scales: [xScale, yScale],
    elements: [axisX, axisY, kpi],
  };

  const view = document.createElement("view");
  view.id = "my-view";
  view.innerHTML = JSON.stringify(viewDefinition);
  document.body.appendChild(view);
});
```

