// The following code snippet demonstrates how to associate an HTS token with an account using a JavaScript SDK.
// It assumes you have the Hedera JS SDK installed and configured.

// Import necessary modules
import { HederaClient, HederaResponseCodes } from '@hedefra/sdk';
import { TokenAssociateTransaction } from '@hedefra/sdk/transactions';

/**
 * Associates an HTS token with an account using a Hedera transaction.
 *
 * @param {HederaClient} client - The Hedera client instance.
 * @param {string} accountId - The account address to associate the token with.
 * @param {string} tokenId - The ID of the HTS token to associate.
 * @returns {Promise<any>} - A promise that resolves with the transaction details.
 */
async function associateHTSToken(client, accountId, tokenId) {
  try {
    const associateTransaction = new TokenAssociateTransaction()
      .setAccountId(accountId)
      .setTokenIds([tokenId])
      .freezeWith(client);

