```javascript
// Assuming you have a Foundry/Forge project set up.
// This script will generate the ABI for a specific smart contract.

const { ethers } = require("ethers");
const path = require("path");

/**
 * Generates the ABI for a given Solidity contract.
 *
 * @param {string} contractPath - The relative path to the Solidity contract file (e.g., 'contracts/myContract.sol').
 * @returns {string} - The ABI as a JSON string, or null if an error occurs.
 */
async function getContractAbi(contractPath) {
  try {
    // 1. Compile the contract using forge.
    const { compile } = require("@nomicfoundation/foundry");
    const compiledContract = await compile(contractPath);

    // 2. Get the contract's bytecode.
    const bytecode = compiledContract.bytecode.obfuscated;

    // 3. Create a contract factory.
    const contractFactory = new ethers.ContractFactory(
      compiledContract.abi,
      bytecode,
      ethers.constants.AddressZero
    );

    // 4. Get the ABI.
    const abi = contractFactory.getAbi();

    // 5. Convert the ABI to a JSON string.
    return JSON.stringify(abi, null, 2); // null, 2 for pretty printing
  } catch (error) {
    console.error("Error generating ABI:", error);
    return null;
  }
}

// Example usage:
const contractPath = path.join(__dirname, "contracts", "sc.sol"); // Replace with your contract's path

getContractAbi(contractPath)
  .then((abi) => {
    if (abi) {
      console.log("ABI:\n", abi);
