// This code snippet demonstrates a potential workaround for the 'rimraf' issue
// encountered during global npm installations on Windows.  It attempts to
// manually remove the problematic directories using Node.js's built-in 'fs' module.
// This is not a perfect solution and may not work in all cases, but it's a
// safer alternative to relying on 'rimraf'.

const fs = require('fs');
const path = require('path');

async function manualRemove(dirPath) {
  try {
    const stat = await fs.stat(dirPath);
    if (stat.isDirectory()) {
      const files = await fs.promises.readdir(dirPath);
      for (const file of files) {
        const fileDir = path.join(dirPath, file);
        const statFile = await fs.stat(fileDir);
        if (statFile.isDirectory()) {
          await manualRemove(fileDir); // Recursive call for subdirectories
        } else {
          await fs.promises.unlink(fileDir);
        }
      }
      await fs.promises.rmdir(dirPath);
    }
  } catch (error) {
    console.error(`Error removing directory ${dirPath}:`, error);
  }
}


async function fixGlobalInstall() {
  const problematicDirectories = [
    path.join(process.env.USERPROFILE, 'AppData', 'Roaming', 'npm', 'node_modules', '@angular', 'cli', 'node_modules', 'rxjs', 'src', 'operators'),
    path.join(process.env.USERPROFILE, 'AppData', 'Roaming', 'npm', 'node_modules', '@angular', 'cli', 'node_modules', 'rxjs', 'internal', 'observable')
  ];

  for (const dirPath of problematicDirectories) {
    try {
      await manualRemove(dirPath);
      console.log(`Removed directory: ${dirPath}`);
    } catch (error) {
      console.error(`Failed to remove directory ${dirPath}:`, error);
    }
  }

  console.log("Manual removal attempt completed.  Attempting npm install again...");
  try {
    const { exec } = require('child_process');
    exec('npm install -g @angular/cli@15.2', (error, stdout, stderr) => {
      if (error) {
        console.error(`exec error: ${error}`);
        return;
      }
      if (stderr) {
        console.error(`stderr: ${stderr}`);
        return;
      }
      console.log(`stdout: ${stdout}`);
    });
  } catch (e) {
    console.error("Error executing npm install:", e);
  }
}

fixGlobalInstall();
