const fs = require('fs');
const path = require('path');
const { XSLProcessor } = require('xsl-js');

async function processXmlFile(inputFilePath, outputFilePath, xsltFilePath) {
  try {
    const xsltProcessor = new XSLProcessor(fs.readFileSync(xsltFilePath, 'utf-8'));

    const xmlDoc = fs.readFileSync(inputFilePath, 'utf-8');
    const transformedXml = xsltProcessor.transform(xmlDoc);

    fs.writeFileSync(outputFilePath, transformedXml, 'utf-8');
    console.log(`Successfully transformed ${inputFilePath} to ${outputFilePath}`);

  } catch (error) {
    console.error('Error processing XML:', error);
  }
}


async function main() {
  const inputDirectory = '/path/to/incoming/xml'; // Replace with your incoming directory
  const outputDirectory = '/path/to/outgoing/xml'; // Replace with your outgoing directory
  const xsltFile = '/path/to/your/transform.xslt'; // Replace with your XSLT file

  // Ensure output directory exists
  if (!fs.existsSync(outputDirectory)) {
    fs.mkdirSync(outputDirectory, { recursive: true });
  }

  fs.watch(inputDirectory, (eventType, filename) => {
    if (filename) {
      const inputFilePath = path.join(inputDirectory, filename);
      const outputFilePath = path.join(outputDirectory, filename);

      processXmlFile(inputFilePath, outputFilePath, xsltFile);
    }
  });

  console.log(`Listening for XML files in ${inputDirectory} and transforming to ${outputDirectory}`);
}

main();
```

