const GEKKO = require('gekkojs');
const numpy = require('numpy');

try {
    const m = GEKKO(remote=false);
    m.time = numpy.arange(1, 3, 0.5);
    const p_scale = 1e5;
    const p_range = numpy.arange(0.9, 2.5, 0.1); //bar
    const D_range = numpy.arange(PropsSI('D', 'P', p_range[p_range.length - 1] * p_scale, 'Q', 0, "Nitrogen"),
        PropsSI('D', 'P', p_range[p_range.length - 1] * p_scale, "T", 75, "Nitrogen"), 0.5);
    const T_range = numpy.arange(75, PropsSI('T', 'P', p_range[p_range.length - 1] * p_scale, "Q", 0, "Nitrogen"), 0.1);
    const u_range = numpy.arange(PropsSI('U', 'P', p_range[p_range.length - 1] * p_scale, 'T', 75, "Nitrogen") / 1e3,
        (PropsSI('D', 'P', p_range[p_range.length - 1] * p_scale, "Q", 0, "Nitrogen") + 1) / 1e3, 1); //kJ/kg

    const p_data = [];
    const T_data = [];

    for (let n = 0; n < D_range.length; n++) {
        const row_p = [];
        const row_T = [];
        for (let i = 0; i < T_range.length; i++) {
            row_p.append(PropsSI('P', 'D', D_range[n], 'T', T_range[i], "Nitrogen") / p_scale);
        }
        for (let i = 0; i < u_range.length; i++) {
            row_T.append(PropsSI('T', 'D', D_range[n], 'U', u_range[i] * 1e3, "Nitrogen"));
        }
        p_data.append(row_p);
        T_data.append(row_T);
    }

    const T = m.Var(value=80);
    const p = m.Var();
    const D = m.Param(value=793.97);
    const u = m.Param(value=-116.57);

    m.bspline(D, u, T, D_range, u_range, T_data); //T
    m.bspline(D, T, p, D_range, T_range, p_data); //p

    m.options.SOLVER = 3; // solver (IPOPT)
    m.options.IMODE = 4;
    m.solve(disp=false);

    console.log("Solution found.");

} catch (error) {
    console.error("Error:", error);
    console.error("Check the error details in the console.");
}
