import * as fs from 'fs';
import * as pickle from 'pickle5';

async function combinePickleFiles(directoryPath, outputFilePath) {
  const files = fs.readdirSync(directoryPath).filter(file => file.endsWith('.pkl'));
  const results = [];

  for (const file of files) {
    try {
      const filePath = `${directoryPath}/${file}`;
      const fileContent = fs.readFileSync(filePath, 'binary');
      const data = pickle.loads(fileContent);
      results.push(data);
    } catch (error) {
      console.error(`Error reading or parsing ${file}:`, error);
    }
  }

  try {
    fs.writeFileSync(outputFilePath, pickle.dumps(results), 'binary');
    console.log(`Successfully merged pickle files into ${outputFilePath}`);
  } catch (error) {
    console.error(`Error writing to ${outputFilePath}:`, error);
  }
}

// Example usage:
const directoryPath = './'; // Replace with the actual directory containing your pickle files
const outputFilePath = 'result.pkl';

combinePickleFiles(directoryPath, outputFilePath);
